epicSlot('market', 'archer').push(
{ title:'장터 — 활을 파는 좌판',
  text:`활이 걸려 있다.<br><br>
    시위가 걸린 채로다. 활은 안 쓸 때 시위를 푸는 게 상식이다.<br>
    걸어 두면 힘이 죽는다.<br><br>
    전부 걸린 채로 걸려 있다. 오래.`,
  opts:[
    { l:'① 시위를 풀어 준다.', dc:11, kind:'heal', p:600,
      good:`하나씩 풀었다. 열두 자루.<br><br>푸는 동안 활이 한 번씩 튕긴다. 숨 돌리는 소리 같다.<br>풀고 나니 좌판 주인이 고개를 숙였다.<br><br>활은 쉬게 해 줘야 한다. 궁수가 제일 먼저 배우는 것이다.`, flag:'unstrung',
      bad:`푸는데 시위가 안 빠진다.<br><br>고리가 아니라 붙어 있다. 자라서 붙었다.<br>억지로 하면 활이 부러진다. 그만뒀다.`, poll:6 },
    { l:'② 한 자루 당겨 본다.', dc:13, p:650,
      good:`당겨 봤다. 무겁다. 아주 무겁다.<br><br>이쪽 힘으로 반쯤 당겨진다.<br>이걸 쓰던 사람은 이쪽보다 셌다는 뜻이다.<br><br>놓았다. 놓는 소리가 오래 남았다.`, flag:'heavyBow',
      bad:`당기는데 시위가 끊어진다.<br><br>끊긴 자리가 손등을 쳤다. 피가 났다.<br>오래 걸어 둔 시위는 그렇게 된다.`, poll:8 }
  ] }
);

epicSlot('village', 'archer').push(
{ title:'빈 마을 — 지붕 위',
  text:`집 지붕에 올라가 본다.<br><br>
    궁수는 높은 데부터 확인한다. 버릇이다.<br>
    올라가니 마을이 다 보인다.<br><br>
    굴뚝이 스물넷이다. 집은 스물셋인데.`,
  opts:[
    { l:'① 어느 굴뚝이 남는지 겨눈다.', mini:'aim', miniOpt:{ p:800, shots:3, need:2 },
      good:`하나씩 겨눠 가며 세었다.<br><br>겨누면 초점이 잡힌다. 초점이 안 잡히는 게 하나 있다.<br>마을 밖, 숲 쪽.<br><br>거기 한 채가 더 있다.`, flag:'deepFound', flag2:true,
      bad:`겨누는데 굴뚝이 흔들린다.<br><br>연기가 아니라 굴뚝이 흔들린다.<br>세 번 겨누고 그만뒀다.` },
    { l:'② 지붕에서 내려다본다.', dc:11, kind:'sense', p:550,
      good:`마당마다 자국이 있다. 사람이 서 있던 자국.<br><br>전부 한 방향을 보고 있었다. 마을 밖 숲 쪽.<br>스물셋 명이 같은 곳을 보고 서 있었던 것이다.`, flag:'allFacing',
      bad:`내려다보는데 지붕이 꺼진다.<br><br>썩은 게 아니라 무르다.<br>급히 내려왔다.`, poll:7 }
  ] }
);

epicSlot('temple', 'archer').push(
{ title:'신전 — 쏘면 안 되는 곳',
  text:`신전 천장이 높다.<br><br>
    위쪽에 뭔가 걸려 있다. 손이 안 닿는 높이.<br>
    쏘면 떨어뜨릴 수 있다.<br><br>
    신전에서 활을 쏘는 건 예의가 아니다.`,
  opts:[
    { l:'① 쏜다.', dc:13, p:700,
      doom:{ title:'쏜 화살', what:'화살이 돌아오고 있습니다', dc:14, sec:70,
        text:`쐈다. 걸린 것이 떨어진다.<br><br>주우려는데 화살이 안 보인다. 떨어지지 않았다.<br>천장 어딘가에 남아 있다.<br><br>그리고 온다. 위에서 아래로, 이쪽을 향해.<br>신전은 쏜 것을 돌려주는 곳이었다.`,
        dieText:`신전에서 쏘면 안 되는 이유가 있었다.<br><br>예의 문제가 아니라 구조 문제였다.<br>여기서는 던진 것이 돌아온다.` },
      good:`쐈다. 걸린 것이 떨어진다. 천이다.<br><br>펴 보니 깃발이다. 낡았고 색이 빠졌다.<br>화살은 천장에 박힌 채로 있다. 못 뽑는다.<br><br>남겨 두고 깃발만 챙겼다.`, flag:'shotBanner' },
    { l:'② 막대로 건드려 본다.', dc:12, p:600,
      good:`제단 옆 지팡이로 밀어 봤다. 안 닿는다.<br><br>두 개를 이어 봤다. 닿았다.<br>천이 떨어진다. 먼지가 났다.<br><br>쏘지 않고 해결했다. 궁수치고는 드문 일이다.`, flag:'pokedDown',
      bad:`막대가 짧다.<br><br>세 번 시도하고 그만뒀다.<br>걸린 건 그대로 있다.`, poll:5 }
  ] }
);

epicSlot('grave', 'archer').push(
{ title:'묘지 — 화살이 박힌 비석',
  text:`비석 하나에 화살이 박혀 있다.<br><br>
    깊다. 돌에 그만큼 박히려면 아주 가까이서 쐈거나,<br>
    아주 센 활로 쐈어야 한다.<br><br>
    깃이 아직 붙어 있다. 오래되지 않았다.`,
  opts:[
    { l:'① 깃을 본다.', dc:12, kind:'gaze', p:650,
      good:`깃 묶는 방식이 이쪽과 같다.<br><br>같은 방식으로 배운 사람이 여기 있었다.<br>깃 색도 같다. 쓰는 깃털이 같다는 뜻이다.<br><br>뽑지 않았다. 남의 화살은 뽑는 게 아니다.`, flag:'sameFletch',
      bad:`보는데 깃이 바스러진다.<br><br>만지지도 않았는데.<br>남은 건 대뿐이다.`, poll:6 },
    { l:'② 뽑는다.', dc:14, kind:'break', p:750,
      doom:{ title:'박힌 화살', what:'비석이 기울고 있습니다', dc:13, sec:65,
        text:`잡고 당겼다. 안 나온다.<br><br>더 당겼다. 비석이 같이 딸려 온다.<br>화살이 비석을 잡고 있었던 게 아니라, 비석을 세워 두고 있었다.<br><br>기운다. 이쪽으로.<br>손이 화살에 감겨 안 빠진다.`,
        dieText:`남의 화살은 뽑는 게 아니다.<br><br>박아 둔 이유가 있고, 이유는 대개 말해 주지 않는다.<br>비석이 스물넷이 됐다.` },
      good:`조금 흔들다 손을 뗐다.<br><br>흔드니 비석이 같이 흔들린다. 뽑으면 안 된다는 뜻이다.<br>그대로 뒀다.<br><br>궁수는 자기 화살만 회수한다.`, flag:'leftArrow' }
  ] }
);

epicSlot('road', 'archer').push(
{ title:'끊긴 길 — 건너편을 겨눈다',
  text:`안개 너머가 흐리다.<br><br>
    뭔가 있는 것 같기도 하고 아닌 것 같기도 하다.<br>
    궁수는 겨누면 보인다. 겨누는 건 보는 방식이다.<br><br>
    다만 겨누면 저쪽도 겨눠진 걸 안다.`,
  opts:[
    { l:'① 겨눠서 확인한다.', mini:'aim', miniOpt:{ p:750, shots:2, need:1, hard:1 },
      good:`겨눴다. 초점이 잡힌다.<br><br>사람이다. 서 있다. 이쪽을 보고 있다.<br>활을 들고 있다. 이쪽을 겨누고 있다.<br><br>둘 다 안 쐈다. 둘 다 내렸다. 그걸로 끝났다.`, flag:'mirrorArcher',
      bad:`겨누는데 초점이 안 잡힌다.<br><br>안개가 아니라 다른 것이 시야를 흐린다.<br>눈이 아프다.` },
    { l:'② 소리로 확인한다.', dc:12, kind:'sense', p:650,
      good:`활대로 땅을 한 번 쳤다.<br><br>저쪽에서 같은 소리가 돌아온다. 한 박자 늦게.<br>있다는 뜻이다. 그리고 흉내 낸다는 뜻이다.<br><br>안 건넜다.`, flag:'echoCheck',
      bad:`쳤는데 소리가 안 돌아온다.<br><br>안개가 먹었다.<br>확인할 방법이 없어졌다.`, poll:6 }
  ] }
);

// ==========================================
// 🐗 사냥꾼 — 10장면
// ==========================================
epicSlot('market', 'hunter').push(
{ title:'장터 — 가죽',
  text:`좌판에 가죽이 쌓여 있다.<br><br>
    무두질이 잘 되어 있다. 털도 고르다.<br>
    다만 짐승 가죽이 아니다.<br><br>
    사냥꾼은 가죽을 보면 무슨 짐승인지 안다. 이건 모르겠다.`,
  opts:[
    { l:'① 뒷면을 본다.', dc:13, kind:'sense', p:700,
      good:`뒤집어 봤다. 결이 사람 살과 비슷하다.<br><br>다만 사람은 아니다. 사람이었던 것도 아니다.<br>처음부터 이런 것이 있다는 뜻이다.<br><br>안 샀다. 사냥꾼은 모르는 짐승을 안 건드린다.`, flag:'strangeHide',
      bad:`뒤집는데 따뜻하다.<br><br>벗긴 지 얼마 안 된 가죽이다.<br>그럼 여기 그 짐승이 있다는 뜻이다.`, poll:8 },
    { l:'② 한 장 산다.', dc:11, p:550,
      good:`한 장 샀다. 덮으면 따뜻할 것이다.<br><br>밤에 덮고 잤다. 따뜻했다.<br>아침에 보니 털 방향이 바뀌어 있었다.`, flag:'boughtHide',
      bad:`고르는데 한 장이 움직인다.<br><br>바람이 없었다.<br>안 샀다.`, poll:7 }
  ] }
);

epicSlot('lake', 'hunter').push(
{ title:'거울 호수 — 물 마시러 오는 것',
  text:`물가에 자국이 있다.<br><br>
    물 마시러 오는 자국이다. 여럿, 여러 번.<br>
    사냥꾼은 물가를 좋아한다. 짐승이 반드시 오는 곳이니까.<br><br>
    다만 자국이 오는 방향만 있고 가는 방향이 없다.`,
  opts:[
    { l:'① 기다린다.', dc:13, kind:'sense', p:750,
      good:`풀에 엎드려 기다렸다. 오래.<br><br>왔다. 물을 마신다. 소리가 안 난다.<br>다 마시고 물로 들어갔다. 가는 자국이 없는 이유다.<br><br>물에서 나와 물로 돌아간다.`, flag:'drinkers',
      bad:`기다리는데 뒤가 서늘하다.<br><br>돌아보니 자국이 새로 생겼다. 이쪽 뒤에.<br>지나갔다는 뜻이다. 옆으로.`, poll:8 },
    { l:'② 자국을 따라 물로 들어간다.', dc:15, p:850,
      doom:{ title:'물속의 길', what:'물속으로 들어갔습니다', dc:14, sec:70,
        text:`발목까지 들어갔다. 자국이 이어진다.<br><br>무릎까지. 허리까지. 자국이 계속 이어진다.<br>바닥이 단단하다. 길이 나 있다.<br><br>돌아보니 물가가 멀다. 생각보다 훨씬 멀다.<br>몇 걸음 안 들어왔는데.`,
        dieText:`사냥꾼은 자국을 따라가는 사람이다.<br><br>자국이 어디로 이어지는지는 자국을 남긴 것만 안다.<br>따라간 쪽은 대개 나중에 안다.` },
      good:`발목까지 들어가서 멈췄다.<br><br>바닥이 단단하다. 길이 나 있다. 물속으로 이어지는 길.<br>따라가면 어디로 가는지 알 수 있다.<br><br>알고 싶지 않아졌다. 나왔다.`, flag:'underPath' }
  ] }
);

epicSlot('ruin', 'hunter').push(
{ title:'폐허 — 뼈',
  text:`기둥 아래에 뼈가 있다.<br><br>
    짐승 뼈다. 부러진 자리가 깨끗하다.<br>
    뜯은 게 아니라 잘린 것이다.<br><br>
    사냥꾼은 짐승이 짐승을 먹은 자리와 사람이 손질한 자리를 구분한다.`,
  opts:[
    { l:'① 손질 방식을 본다.', dc:12, kind:'sense', p:650,
      good:`관절을 따라 잘랐다. 배운 사람 솜씨다.<br><br>사냥꾼이거나 백정이거나.<br>여기서 사냥해서 여기서 손질했다는 뜻이다.<br><br>불 땐 자리도 있다. 오래됐다.`, flag:'butchered',
      bad:`보다 보니 뼈가 안 맞는다.<br><br>한 짐승 것이 아니다. 여러 짐승 뼈를 모아 놓았다.<br>모양이 하나가 되게.`, poll:8 },
    { l:'② 뼈를 맞춰 본다.', dc:14, kind:'gaze', p:750,
      doom:{ title:'맞춘 뼈', what:'맞춘 것이 일어났습니다', dc:14, sec:70,
        text:`관절 순서대로 놓아 봤다.<br><br>맞는다. 서로 다른 짐승 뼈인데 맞물린다.<br>맞물리자 형태가 나온다. 두 발로 서는 형태다.<br><br>마지막 뼈를 놓자 전체가 한 번 떨린다.<br>기다리고 있었던 것이다. 맞춰 줄 손을.`,
        dieText:`사냥꾼은 짐승을 해체하는 사람이다.<br><br>조립하는 사람이 아니다.<br>왜 나뉘어 있었는지 생각했어야 했다.` },
      good:`세 개까지 맞추고 그만뒀다.<br><br>맞을수록 형태가 보인다. 두 발로 서는 형태.<br>더 맞추면 안 될 것 같았다.<br><br>흩어 놓았다. 원래대로.`, flag:'scatteredBones' }
  ] }
);

epicSlot('temple', 'hunter').push(
{ title:'신전 — 제물 자리',
  text:`제단 옆에 홈이 있다.<br><br>
    피를 받던 홈이다. 사냥한 것을 바치던 자리.<br>
    사냥꾼은 이런 걸 알아본다.<br><br>
    홈이 깊다. 오래 썼다.`,
  opts:[
    { l:'① 바쳐 본다.', dc:12, kind:'bond', p:700,
      good:`가진 것 중 하나를 홈에 놓았다. 말린 고기 한 조각.<br><br>놓자 홈이 빨아들인다. 피가 아닌데 빨아들인다.<br>다 먹고 나니 제단이 조금 밝아졌다.<br><br>얻은 게 있는지는 모르겠다. 예의는 차렸다.`, flag:'offeredMeat',
      bad:`놓았는데 안 먹는다.<br><br>원하는 게 그게 아니었다.<br>도로 집어 넣었다.`, poll:6 },
    { l:'② 홈의 크기를 잰다.', dc:13, kind:'gaze', p:700,
      good:`홈 폭이 넓다. 사슴이나 멧돼지 크기가 아니다.<br><br>사람이 누울 폭이다.<br>깊이도 맞는다.<br><br>재고 나서 한참 서 있었다.`, flag:'measuredGroove',
      bad:`재는데 홈이 손에 맞춰 넓어진다.<br><br>손을 대면 손 크기로, 팔을 대면 팔 크기로.<br>뺐다.`, poll:8 }
  ] }
);

epicSlot('road', 'hunter').push(
{ title:'끊긴 길 — 건너간 자국',
  text:`안개 위에 자국이 있다.<br><br>
    네 발 자국이다. 안개 위를 네 발로 건넜다.<br>
    무게가 가벼웠거나, 안개가 받아 줬거나.<br><br>
    사냥꾼은 무게를 자국 깊이로 잰다. 얕다.`,
  opts:[
    { l:'① 네 발로 건넌다.', dc:14, kind:'evade', p:800,
      good:`엎드려서 기어 건넜다. 무게를 넷으로 나눠서.<br><br>안 빠진다. 안개가 받아 준다.<br>건너편에 닿아 일어섰다. 무릎이 젖었다.<br><br>사냥꾼은 짐승 흉내를 낼 줄 안다. 그게 도움이 됐다.`, flag:'crawledOver',
      bad:`기어가다 한 손이 빠진다.<br><br>빼는데 다른 손도 빠진다.<br>되돌아 나왔다. 손이 안개 냄새가 났다.`, poll:9 },
    { l:'② 자국 주인을 기다린다.', co:'call',
      coOpt:{ ask:'건너간 것이 있습니다. 같이 기다려 주십시오.', sec:60, p:900,
        text:`혼자 기다리다 마주치면 곤란하다.`,
        doneText:`둘이 엎드려 기다렸다.<br><br>왔다. 건너온다. 네 발로. 안개 위를 가볍게.<br>지나간다. 둘 다 숨을 참았다.<br><br>지나간 뒤에 둘 다 한참 말이 없었다.<br>본 것을 어떻게 말해야 할지 몰라서.`,
        failText:`혼자 기다렸다.<br><br>오래 기다렸다. 안 왔다.<br>기다리는 걸 안다는 뜻일 수도 있다.` },
      good:`봤다.`, bad:`못 봤다.` }
  ] }
);

// ==========================================
// 🔮 점성술사 — 10장면
// ==========================================
epicSlot('gate', 'seer').push(
{ title:'성문 — 새겨진 하늘',
  text:`아치 안쪽에 점이 찍혀 있다.<br><br>
    별자리다. 돌에 새긴 것.<br>
    들어오는 사람이 올려다보게 새겨 놓았다.<br><br>
    한 점이 파여 있다. 지운 게 아니라 파냈다.`,
  opts:[
    { l:'① 파인 자리를 본다.', dc:12, kind:'gaze', p:650,
      good:`파인 자리가 깊다. 정으로 파냈다.<br><br>별 하나를 지우려고 애쓴 흔적이다.<br>탑 관측대에서 본 빈자리와 같은 자리다.<br><br>하늘에서도 없고 여기서도 지웠다.`, flag:'chiseledStar',
      bad:`보다 보니 다른 점도 흐리다.<br><br>지워지는 중이다. 천천히.<br>다음 차례가 어느 것인지는 알 수 없다.`, poll:7 },
    { l:'② 파인 자리에 표시를 넣는다.', dc:13, p:700,
      good:`분필로 점을 찍었다. 원래 자리에.<br><br>찍자 별자리가 완성된다. 형태가 잡힌다.<br>무릎 꿇은 사람 모양이다.<br><br>탑에서 그린 것과 같다.`, flag:'restoredPoint',
      bad:`찍은 점이 지워진다.<br><br>손으로 문지른 게 아니라 저절로.<br>세 번 찍고 그만뒀다.`, poll:8 }
  ] }
);

epicSlot('village', 'seer').push(
{ title:'빈 마을 — 지붕 위의 하늘',
  text:`마을에서 하늘을 본다.<br><br>
    탑에서 본 것과 다르다. 별 위치가 어긋난다.<br>
    같은 하늘인데 보는 자리에 따라 다르다.<br><br>
    점성술사에게는 있을 수 없는 일이다.`,
  opts:[
    { l:'① 두 하늘의 차이를 잰다.', dc:14, kind:'gaze', p:800,
      good:`각도를 재 봤다. 어긋난 정도가 일정하다.<br><br>일정하다는 건 규칙이 있다는 뜻이다.<br>마을 하늘은 탑 하늘보다 한 칸 뒤다.<br><br>마을이 과거를 보고 있는 것이다.`, flag:'skewSky',
      bad:`재는데 기준이 안 잡힌다.<br><br>기준 별이 움직인다. 두 하늘 다.<br>잴 수가 없다.`, poll:8 },
    { l:'② 마을 하늘을 기록한다.', dc:12, p:650,
      good:`보이는 대로 그렸다.<br><br>그리고 보니 빠진 자리가 있다. 탑에서 본 그 자리.<br>여기서도 비어 있다.<br><br>어느 하늘에서든 비어 있는 자리였다.`, flag:'sameGap',
      bad:`그리는 동안 하늘이 돈다.<br><br>그린 게 안 맞게 된다.<br>세 번 다시 그렸다.`, poll:7 }
  ] }
);

epicSlot('ruin', 'seer').push(
{ title:'폐허 — 천장의 별',
  text:`지붕이 없는데 천장 무늬가 떠 있다.<br><br>
    무늬가 아니라 점이다. 스물넷 줄로 늘어서 있다.<br>
    점성술사 눈에는 하늘로 보인다.<br><br>
    맨 윗줄이 비어 있다.`,
  opts:[
    { l:'① 별자리로 읽는다.', dc:13, kind:'gaze', p:750,
      good:`줄마다 하나씩 별자리다. 스물셋 개.<br><br>전부 아는 자리다. 이름을 다 부를 수 있다.<br>맨 윗줄만 빈다. 이름 없는 자리.<br><br>여기가 지상에 옮겨 놓은 하늘이었다.`, flag:'ceilingSky',
      bad:`읽다 보니 점이 움직인다.<br><br>읽은 자리가 안 읽은 자리로 옮겨 간다.<br>스물셋을 다 못 읽었다.`, poll:8 },
    { l:'② 빈 줄에 점을 찍는다.', dc:15, p:850,
      doom:{ title:'찍은 점', what:'천장이 내려오고 있습니다', dc:14, sec:70,
        text:`빈 줄에 점을 하나 찍었다.<br><br>찍자 무늬가 완성된다. 스물넷 줄.<br>완성된 것은 내려온다. 그게 규칙이었던 모양이다.<br><br>천장이 내려온다. 무게가 있다.<br>찍은 점이 이쪽 머리 위다.`,
        dieText:`하늘은 완성되면 내려온다.<br><br>그래서 스물넷째 자리를 비워 두었던 것이다.<br>비워 둔 데는 이유가 있다.` },
      good:`찍으려다 손을 멈췄다.<br><br>스물셋이 다 차 있고 하나가 비었다.<br>이 배열을 여러 곳에서 봤다. 전부 비어 있었다.<br><br>비어 있는 게 맞는 것이다. 안 찍었다.`, flag:'leftRowEmpty' }
  ] }
);

epicSlot('temple', 'seer').push(
{ title:'신전 — 바닥의 원',
  text:`바닥에 원이 새겨져 있다.<br><br>
    가장자리에 눈금이 있다. 열둘. 해를 나누는 눈금이다.<br>
    가운데 서면 그림자가 눈금을 가리킨다.<br><br>
    해가 없는데 그림자가 있다.`,
  opts:[
    { l:'① 가운데 선다.', dc:12, p:700,
      good:`섰다. 그림자가 생긴다. 한 눈금을 가리킨다.<br><br>세 번째 눈금이다. 새벽 세 시 자리.<br>여기 시간은 세 시에 멈춰 있다.<br><br>나오자 그림자가 없어졌다.`, flag:'threeMark',
      bad:`섰는데 그림자가 여럿이다.<br><br>사방으로 뻗는다. 전부 다른 눈금을 가리킨다.<br>어느 게 맞는지 알 수 없다.`, poll:7 },
    { l:'② 눈금을 세어 본다.', dc:11, kind:'gaze', p:600,
      good:`열둘이 맞다. 다만 하나가 두 번 새겨져 있다.<br><br>세 번째 눈금이 겹쳐 새겨졌다. 두 번.<br>같은 시각이 두 번 있었다는 뜻이다.<br><br>그런 날이 있었던 모양이다.`, flag:'doubleHour',
      bad:`세다 보니 열셋이다.<br><br>다시 세니 열둘이다. 또 세니 열셋이다.<br>그만 셌다.`, poll:6 }
  ] }
);

epicSlot('road', 'seer').push(
{ title:'끊긴 길 — 별이 안 보이는 자리',
  text:`끊긴 자리 위로 하늘이 비어 있다.<br><br>
    다른 곳은 별이 보이는데 여기만 없다.<br>
    구름도 아니다. 그냥 없다.<br><br>
    별이 없는 하늘 아래는 점성술사가 길을 못 찾는다.`,
  opts:[
    { l:'① 기억으로 채워서 본다.', dc:14, kind:'gaze', p:800,
      good:`탑에서 본 배치를 떠올려 겹쳐 봤다.<br><br>여기 있어야 할 별이 셋. 전부 안 보인다.<br>셋이 빠진 자리가 삼각형을 이룬다.<br><br>그 삼각형 가운데가 끊긴 자리다. 우연이 아니다.`, flag:'triangleGap',
      bad:`떠올리려는데 배치가 안 떠오른다.<br><br>탑에서 분명히 봤는데.<br>본 게 맞는지도 이제 확신이 없다.`, poll:8 },
    { l:'② 동료에게 확인시킨다.', co:'witness',
      coOpt:{ ask:'하늘에 이상한 자리가 있습니다. 같이 봐 주십시오.', sec:60, p:950,
        text:`혼자 본 하늘은 기록이 안 된다.`,
        doneText:`동료가 와서 같이 올려다봤다.<br><br>가리킨 자리를 보고 고개를 끄덕였다. 안 보인다고 했다.<br>둘 다 안 보인다고 했으면 정말로 없는 것이다.<br><br>기록에 두 이름을 적었다.`,
        failText:`혼자 봤다.<br><br>혼자 본 하늘은 환시로 처리된다.<br>규정이 그렇다. 여기서 규정이 무슨 소용인지는 모르겠지만.` },
      good:`기록이 됐다.`, bad:`환시로 남았다.` }
  ] }
);
;

