epicSlot('market', 'assassin').push(
{ title:'장터 — 등 뒤',
  text:`장터는 사람이 많다.<br><br>
    많은 곳에서는 숨기 쉽다. 다만 등 뒤도 많아진다.<br>
    암살자는 등 뒤가 많은 곳을 싫어한다.<br><br>
    좌판 사이로 걸으면 양쪽이 다 등이다.`,
  opts:[
    { l:'① 벽을 등지고 간다.', dc:12, kind:'hide', p:650,
      good:`가장자리로 돌았다. 한쪽은 벽, 한쪽만 보면 된다.<br><br>느리다. 느린 대신 등이 하나 줄었다.<br>암살자가 오래 사는 방식이다.`, flag:'wallSide',
      bad:`벽에 붙었는데 벽이 미지근하다.<br><br>등이 닿은 자리가 따뜻해진다.<br>벽도 등이었다.`, poll:7 },
    { l:'② 좌판 사이를 빠르게 지난다.', dc:14, kind:'evade', p:750,
      doom:{ title:'좌판 사이', what:'양쪽에서 붙잡혔습니다', dc:14, sec:70,
        text:`빠르게 지났다. 셋째 좌판에서 양쪽 손이 나온다.<br><br>어깨를 잡는다. 양쪽에서 동시에.<br>힘이 세지 않다. 다만 놓지 않는다.<br><br>빠져나가려면 한쪽을 버려야 한다.<br>버릴 팔을 고르고 있는 자신을 알아차렸다.`,
        dieText:`사람 많은 곳에서 숨는 건 쉽다.<br><br>사람 많은 곳에서 빠져나가는 건 어렵다.<br>암살자는 늘 들어가는 것만 생각한다.` },
      good:`셋째 좌판에서 손이 나왔다. 피했다.<br><br>몸을 낮추고 그대로 달렸다.<br>끝까지 안 잡혔다. 반 발자국 차이였다.`, flag:'slippedThrough' }
  ] }
);

epicSlot('village', 'assassin').push(
{ title:'빈 마을 — 숨을 곳',
  text:`집이 스물셋이고 문이 전부 열려 있다.<br><br>
    숨을 곳이 스물셋이라는 뜻이다.<br>
    암살자는 숨을 곳을 미리 봐 둔다. 버릇이다.<br><br>
    다만 열린 문은 숨을 곳이 아니다.`,
  opts:[
    { l:'① 잠긴 집을 확인한다.', dc:12, kind:'hide', p:650,
      good:`한 집만 잠겼다. 잠긴 곳이 숨을 곳이다.<br><br>안 들어갔다. 위치만 외워 뒀다.<br>필요할 때 쓸 것이다.<br><br>암살자는 도망갈 자리를 먼저 정한다.`, flag:'markedRefuge',
      bad:`잠긴 집 문에 손을 댔더니 열린다.<br><br>안에서 열어 준 것이다.<br>안 들어갔다.`, poll:7 },
    { l:'② 지붕 위로 다닌다.', dc:13, kind:'evade', p:700,
      good:`지붕으로 올라 집집을 건너다녔다.<br><br>아래로 다니는 것보다 빠르다. 보는 눈도 없다.<br>스물셋 집을 열 번쯤 건넜다.<br><br>마지막 집 지붕에서 마을 전체가 보였다. 마당마다 자국이 있다.`, flag:'roofRoute',
      bad:`지붕이 꺼진다.<br><br>썩은 게 아니라 무르다. 발이 빠진다.<br>빠진 집 안에서 뭔가 올려다보고 있었다.`, poll:8 }
  ] }
);

epicSlot('forest', 'assassin').push(
{ title:'검은 숲 — 소리 없는 걸음',
  text:`낙엽이 두껍다.<br><br>
    밟으면 소리가 난다. 소리가 나면 안 된다.<br>
    암살자는 낙엽 위를 걷는 법을 배운다.<br><br>
    발끝부터, 바깥쪽부터, 천천히.`,
  opts:[
    { l:'① 배운 대로 걷는다.', mini:'beat', miniOpt:{ p:800, total:12, gap:820 },
      good:`열두 걸음. 소리가 안 났다.<br><br>걷는 동안 숲이 조용했다. 원래 조용한 곳인데 더 조용했다.<br>듣고 있었던 것이다.<br><br>안 들킨 것으로 됐다.`, flag:'silentForest',
      bad:`여덟 번째에서 소리가 났다.<br><br>작았다. 그래도 났다.<br>나무가 전부 한 번 흔들렸다. 바람은 없었다.` },
    { l:'② 나뭇가지를 타고 간다.', dc:14, kind:'evade', p:800,
      doom:{ title:'가지 위', what:'가지가 잡고 있습니다', dc:13, sec:65,
        text:`올라가 가지를 타고 건넜다.<br><br>가지가 미지근하다. 잡으면 잡힌다.<br>손을 떼려는데 안 떨어진다.<br><br>가지가 감긴다. 팔에, 다리에.<br>천천히, 서두르지 않고.`,
        dieText:`암살자는 높은 데를 안전하게 여긴다.<br><br>여기 나무는 여기 편이었다.<br>기울지 않고 곧게 선 나무가 한 그루 늘었다.` },
      good:`가지를 타고 세 그루를 건넜다.<br><br>미지근하다. 오래 잡고 있으면 안 될 온도다.<br>세 그루에서 내려왔다.<br><br>내려오길 잘했다. 네 번째 가지가 움직이고 있었다.`, flag:'branchWalk' }
  ] }
);

epicSlot('temple', 'assassin').push(
{ title:'신전 — 죽이지 않는 곳',
  text:`신전은 피를 안 흘리는 곳이다.<br><br>
    암살자도 그건 지킨다. 믿어서가 아니라 규칙이라서.<br>
    지키지 않으면 뒤가 시끄러워진다.<br><br>
    제단 앞에 누가 앉아 있다.`,
  opts:[
    { l:'① 지나친다.', dc:11, kind:'hide', p:600,
      good:`뒤로 돌아 지나갔다.<br><br>앉은 것이 고개를 들지 않았다.<br>여기서는 서로 안 건드린다. 그런 자리다.<br><br>나오면서 한 번 고개를 숙였다. 이쪽도 규칙은 안다.`, flag:'passedShrine',
      bad:`지나치는데 손이 칼자루로 간다.<br><br>버릇이다. 버릇이 여기서는 위험하다.<br>손을 떼는 데 시간이 걸렸다.`, poll:7 },
    { l:'② 앉은 것을 확인한다.', dc:13, kind:'gaze', p:700,
      good:`앞으로 돌아가 봤다.<br><br>무릎을 꿇은 자세로 굳어 있다. 오래.<br>손이 모여 있고 얼굴이 없다.<br><br>기도하다 그렇게 됐다. 여기서는 그런 식으로 끝난다.`, flag:'kneelingOne',
      bad:`앞으로 도는데 그것도 돈다.<br><br>같은 속도로. 계속 등만 보인다.<br>그만뒀다.`, poll:8 }
  ] }
);

epicSlot('lake', 'assassin').push(
{ title:'거울 호수 — 비친 것을 지운다',
  text:`물에 비친 것이 이쪽을 따라 한다.<br><br>
    암살자에게 비치는 건 위험하다. 비치면 들킨다.<br>
    비친 것을 없애는 방법이 몇 가지 있다.<br><br>
    전부 물을 건드려야 한다.`,
  opts:[
    { l:'① 물가에서 멀어진다.', dc:11, p:550,
      good:`물이 안 보이는 데까지 물러났다.<br><br>안 비치면 안 들킨다. 제일 간단한 방법이다.<br>간단한 방법이 제일 낫다.`, flag:'awayFromWater',
      bad:`물러났는데 물가가 넓어진다.<br><br>따라온다. 발밑이 젖는다.<br>더 물러났다.`, poll:7 },
    { l:'② 물을 흐린다.', dc:13, kind:'break', p:700,
      doom:{ title:'흐린 물', what:'비친 것이 나왔습니다', dc:14, sec:70,
        text:`흙을 던져 물을 흐렸다.<br><br>비친 것이 안 보인다. 됐다고 생각했다.<br>흙이 가라앉는다. 맑아진다.<br><br>비친 것이 없다. 물이 맑은데 아무것도 안 비친다.<br>등 뒤에서 발소리가 난다. 이쪽 걸음과 같은 박자로.`,
        dieText:`비친 것을 지우면 없어지는 게 아니다.<br><br>비칠 자리가 없어졌을 뿐이다.<br>그럼 어딘가 다른 자리에 있게 된다.` },
      good:`던지려다 손을 내렸다.<br><br>흐리면 안 보인다. 안 보이는 게 없어진 건 아니다.<br>암살자는 그 차이를 안다.<br><br>그냥 물러났다.`, flag:'didntStir' }
  ] }
);

