// 🪤 밀렵꾼 — 10장면
// ==========================================
epicSlot('market', 'poacher').push(
{ title:'장터 — 팔 수 없는 것',
  text:`좌판에 산 것이 놓여 있다.<br><br>
    우리에 갇힌 채로. 작고, 조용하다.<br>
    금렵구에서 잡은 것이다. 밀렵꾼은 안다.<br><br>
    파는 쪽도 밀렵꾼이었다는 뜻이다.`,
  opts:[
    { l:'① 사서 풀어 준다.', dc:12, kind:'bond', p:700,
      good:`샀다. 값은 안 받았다. 동업자로 본 모양이다.<br><br>우리를 들고 숲 가장자리까지 갔다. 열어 줬다.<br>안 나간다. 한참 있다 나갔다.<br><br>밀렵꾼이 놓아주는 건 이상한 일이다. 두 번째다.`, flag:'freedCaged',
      bad:`사려는데 주인이 손을 젓는다.<br><br>안 판다는 뜻이다.<br>팔려고 내놓은 게 아니었다. 보여 주려고 내놓은 것이었다.`, poll:7 },
    { l:'② 어떻게 잡았는지 묻는다.', dc:13, kind:'sense', p:700,
      good:`물었다. 주인이 덫을 꺼내 보여 준다.<br><br>이쪽이 쓰는 것과 같은 구조다. 장력 거는 방식까지.<br>같은 데서 배운 사람이다.<br><br>어디서 배웠냐고는 안 물었다. 물으면 안 되는 것도 있다.`, flag:'sameTrap',
      bad:`묻자 주인이 고개를 든다.<br><br>얼굴이 없다. 없는 얼굴로 우리 쪽을 본다.<br>우리 안 것이 몸을 움츠렸다.`, poll:8 }
  ] }
);

epicSlot('village', 'poacher').push(
{ title:'빈 마을 — 잡을 것이 없다',
  text:`마을에 산 것이 없다.<br><br>
    개도 닭도 없다. 우리가 비어 있고 짚만 눌려 있다.<br>
    밀렵꾼에게 산 것 없는 곳은 아무것도 아닌 곳이다.<br><br>
    다만 눌린 짚이 아직 따뜻하다.`,
  opts:[
    { l:'① 온기를 따라간다.', dc:13, kind:'sense', p:700,
      good:`따뜻한 자리를 짚어 가며 갔다.<br><br>우리에서 마당으로, 마당에서 마을 밖으로.<br>밖으로 나가는 방향이다. 숲 쪽.<br><br>최근에 나갔다. 아주 최근에.`, flag:'warmTrail',
      bad:`따라가다 보니 온기가 원을 그린다.<br><br>마을을 한 바퀴 돌아 제자리다.<br>나간 게 아니라 돌고 있었다.`, poll:8 },
    { l:'② 우리에 덫을 놓는다.', dc:12, kind:'hide', p:650,
      doom:{ title:'놓은 덫', what:'덫에 걸린 것이 왔습니다', dc:14, sec:70,
        text:`빈 우리에 덫을 놓고 물러나 기다렸다.<br><br>닫히는 소리가 났다. 크게.<br>가 보니 덫이 부서져 있다. 걸렸다가 부순 것이다.<br><br>뭔가 이쪽으로 오고 있다. 덫 냄새를 따라서.<br>덫을 놓은 손 냄새도 같이.`,
        dieText:`덫은 걸리는 것만 잡는 도구가 아니다.<br><br>놓은 사람을 알려 주는 도구이기도 하다.<br>냄새로.` },
      good:`놓았다가 곧 거뒀다.<br><br>여기서 잡히는 게 뭔지 모르는 채로 놓는 건 아니다 싶었다.<br>모르는 것은 안 잡는다. 오래 하는 밀렵꾼의 규칙이다.`, flag:'pulledTrap' }
  ] }
);

epicSlot('ruin', 'poacher').push(
{ title:'폐허 — 사는 것',
  text:`기둥 사이에 둥지가 있다.<br><br>
    새 둥지가 아니다. 더 크고 낮다.<br>
    폐허에 사는 것이 있다는 뜻이다.<br><br>
    둥지 주변에 뼈가 없다. 먹고 남긴 게 없다.`,
  opts:[
    { l:'① 무엇이 사는지 본다.', dc:13, kind:'sense', p:700,
      good:`둥지 재료를 봤다. 천과 가죽이다.<br><br>사람 옷이다. 찢어서 물어다 깔았다.<br>먹고 남긴 게 없는 건 남길 부분이 없어서다.<br><br>물러났다.`, flag:'clothNest',
      bad:`보는데 둥지가 따뜻하다.<br><br>비어 있는데 따뜻하다.<br>방금까지 있었다는 뜻이다.`, poll:8 },
    { l:'② 둥지를 헤집는다.', dc:14, p:750,
      doom:{ title:'헤집은 둥지', what:'주인이 돌아왔습니다', dc:14, sec:70,
        text:`뒤졌다. 아래쪽에 뭔가 있다.<br><br>알이다. 큰 것 하나.<br>집으려는데 그림자가 진다. 위에서.<br><br>둥지 주인은 위에서 내려온다.<br>기둥 위에 있었던 것이다. 처음부터.`,
        dieText:`둥지를 헤집는 건 밀렵꾼이 제일 먼저 배우고<br>제일 먼저 하지 말라고 배우는 것이다.<br><br>알은 어미가 지키기 때문이다.` },
      good:`헤집다 손을 멈췄다.<br><br>아래쪽에 큰 알이 하나 있다.<br>덮어 뒀다. 그대로 둔 채 물러났다.<br><br>알은 안 건드린다. 밀렵꾼의 규칙이다.`, flag:'coveredEgg' }
  ] }
);

epicSlot('temple', 'poacher').push(
{ title:'신전 — 제물이 되던 것',
  text:`제단 옆 홈이 깊다.<br><br>
    여기 뭔가를 바쳤다. 밀렵꾼 눈에는 잡아 온 것으로 보인다.<br>
    홈 옆에 우리가 있다.<br><br>
    우리 살이 안쪽으로 휘어 있다.`,
  opts:[
    { l:'① 우리를 본다.', dc:12, kind:'gaze', p:650,
      good:`안쪽에서 밀어서 휘었다.<br><br>나가려던 것이 밀었다는 뜻이다.<br>그런데 문은 안 열렸다. 그럼 어떻게 됐는지는 홈이 말해 준다.<br><br>우리 바닥에 털이 남아 있다. 사람 머리카락도.`, flag:'bentCage',
      bad:`보는데 우리 문이 저절로 열린다.<br><br>안으로 들어오라는 자세로.<br>물러났다.`, poll:8 },
    { l:'② 우리를 부순다.', dc:13, kind:'break', p:700,
      good:`살을 벌려 부쉈다. 힘이 들었다.<br><br>부수고 나니 개운했다. 밀렵꾼이 우리를 부수는 건 처음이다.<br>여기서는 이게 맞았다.<br><br>부순 살을 하나 챙겼다. 쇠가 좋다.`, flag:'brokeCage',
      bad:`부수는데 소리가 크다.<br><br>신전 전체가 울린다.<br>울림이 멎을 때까지 기다렸다. 오래 걸렸다.`, poll:7 }
  ] }
);

epicSlot('road', 'poacher').push(
{ title:'끊긴 길 — 지고 건넌다',
  text:`자루가 무겁다.<br><br>
    안개 위를 건너려면 가벼워야 한다.<br>
    자루를 버리면 건널 수 있고, 들면 빠진다.<br><br>
    밀렵꾼은 잡은 것을 안 버린다.`,
  opts:[
    { l:'① 자루를 던져 건넌 뒤 줍는다.', dc:13, kind:'luck', p:750,
      good:`힘껏 던졌다. 건너편에 떨어졌다.<br><br>가벼워진 몸으로 건넜다. 안 빠졌다.<br>주워 보니 안에 든 것이 무사하다.<br><br>던진 게 미안해서 자루를 고쳐 메었다.`, flag:'tossedSack',
      bad:`던진 자루가 안개 위에 떨어진다.<br><br>안 가라앉는다. 다만 안쪽으로 조금씩 당겨진다.<br>건너가 주웠다. 겨우.`, poll:8 },
    { l:'② 동료에게 먼저 건네고 건넌다.', co:'handoff',
      coOpt:{ ask:'건너편으로 자루를 받아 주십시오.', sec:60, p:900,
        text:`받아 줄 사람이 있으면 던질 필요가 없다.`,
        doneText:`동료가 건너편에서 받았다.<br><br>손에서 손으로. 안개 위로 팔만 뻗어서.<br>둘 다 안 빠졌다.<br><br>건너가 자루를 돌려받았다. 안에 든 것이 조용했다.`,
        failText:`혼자 지고 건넜다.<br><br>무릎까지 빠졌다. 두 번.<br>건너긴 했다. 자루가 젖었다.` },
      good:`건넸다.`, bad:`지고 건넜다.` }
  ] }
);

// ==========================================
// ⛏ 도굴꾼 — 10장면
// ==========================================
epicSlot('market', 'digger').push(
{ title:'장터 — 무덤에서 나온 것',
  text:`좌판에 오래된 물건이 놓여 있다.<br><br>
    흙이 아직 묻어 있다. 닦지도 않고 내놓았다.<br>
    도굴꾼은 무덤에서 나온 것을 안다.<br><br>
    냄새가 다르다.`,
  opts:[
    { l:'① 어느 무덤 것인지 짐작한다.', dc:13, kind:'sense', p:700,
      good:`흙 색을 봤다. 묘지 흙이다. 그 푸석한 흙.<br><br>스물셋 기 중 하나에서 나온 것이다.<br>어느 것인지까지는 모르겠다.<br><br>사지 않았다. 도굴꾼이 도굴한 것을 사는 건 이상하다.`, flag:'gravegoods',
      bad:`흙을 만지자 젖는다.<br><br>마른 흙이었는데 손에서 젖는다.<br>털었다. 잘 안 털렸다.`, poll:7 },
    { l:'② 되돌려 놓겠다고 한다.', dc:12, kind:'bond', p:700,
      good:`주인에게 말했다. 되돌려 놓겠다고.<br><br>말없이 밀어 줬다. 값도 안 받았다.<br>내놓은 이유가 그거였는지도 모른다. 누가 가져가라고.<br><br>품에 넣었다.`, flag:'willReturn',
      bad:`말하자 주인이 고개를 젓는다.<br><br>안 된다는 뜻이다. 한 번 나온 건 안 돌아간다는 뜻일 수도 있다.<br>두고 나왔다.`, poll:6 }
  ] }
);

epicSlot('village', 'digger').push(
{ title:'빈 마을 — 바닥 아래',
  text:`집 바닥이 흙이다.<br><br>
    한 집만 다진 자국이 다르다. 최근에 파고 덮었다.<br>
    도굴꾼은 다진 자국을 본다.<br><br>
    다시 덮은 자리는 표시가 난다.`,
  opts:[
    { l:'① 판다.', dc:13, p:750,
      doom:{ title:'바닥 아래', what:'파던 자리에 빠졌습니다', dc:13, sec:65,
        text:`팠다. 얕다. 금방 닿았다.<br><br>천이 나온다. 감싸 놓은 것이다.<br>벗기려는데 흙이 아래로 꺼진다.<br><br>얕은 게 아니었다. 위만 다져 놓고 아래는 비어 있었다.<br>떨어졌다. 깊다.`,
        dieText:`마을 집 바닥 아래가 비어 있었다.<br><br>스물셋 집이 전부 그럴 수도 있다.<br>확인할 방법은 파 보는 것뿐이고, 파면 이렇게 된다.` },
      good:`조심스럽게 팠다. 손으로.<br><br>천이 나온다. 감싼 것이 있다.<br>벗기지 않았다. 감싼 데는 이유가 있다.<br><br>덮고 다졌다. 원래대로.`, flag:'reburied' },
    { l:'② 다진 자국만 세어 본다.', dc:11, kind:'gaze', p:600,
      good:`집집마다 봤다. 다진 자국이 있는 집이 스물셋 중 스물셋이다.<br><br>전부 팠다가 덮었다.<br>같은 날에 같은 방식으로.<br><br>세고 나서 파고 싶은 마음이 없어졌다.`, flag:'allDug',
      bad:`세는데 한 집이 더 있다.<br><br>스물넷째 다진 자국이다. 집이 없는 자리에.<br>거기만 파 두고 안 덮었다.`, poll:8 }
  ] }
);

epicSlot('tower', 'digger').push(
{ title:'탑 — 초석 아래',
  text:`탑이 기울어 있다.<br><br>
    초석 한쪽이 들려 있다. 아래가 보인다.<br>
    도굴꾼은 탑 아래에 뭘 묻는지 안다.<br><br>
    기초를 세울 때 묻는 것이 있다.`,
  opts:[
    { l:'① 들린 틈으로 본다.', dc:12, kind:'gaze', p:700,
      good:`엎드려 들여다봤다.<br><br>항아리가 있다. 기초 제물이다. 탑을 세울 때 묻는 것.<br>항아리 입이 열려 있다. 안이 비었다.<br><br>안에 있던 것이 나갔다. 탑이 기운 건 그래서일 수도 있다.`, flag:'foundationJar',
      bad:`들여다보는데 안쪽에서 뭔가 이쪽을 본다.<br><br>눈이 아니라 그냥 보는 느낌이다.<br>물러났다.`, poll:8 },
    { l:'② 손을 넣어 꺼낸다.', dc:15, kind:'hide', p:850,
      doom:{ title:'초석 아래', what:'팔이 끼었습니다', dc:14, sec:70,
        text:`팔을 넣었다. 어깨까지.<br><br>항아리에 닿는다. 안이 비어 있다. 바닥에 뭔가 남았다.<br>집었다. 작고 딱딱하다.<br><br>빼려는데 초석이 내려앉는다. 들려 있던 만큼.<br>팔이 끼었다. 탑 전체 무게가 얹혀 있다.`,
        dieText:`기초 제물은 탑을 세워 두는 것이다.<br><br>꺼내면 탑이 내려앉고, 내려앉으면 대신할 것이 필요하다.<br>탑이 다시 섰다.` },
      good:`손끝만 넣어 봤다.<br><br>닿는 게 없다. 비어 있다.<br>팔을 빼고 초석 아래를 도로 막았다. 돌을 괴어서.<br><br>탑이 한 뼘 바로 섰다. 그걸로 됐다.`, flag:'proppedBase' }
  ] }
);

epicSlot('forest', 'digger').push(
{ title:'검은 숲 — 뿌리 아래',
  text:`나무 아래 흙이 부풀어 있다.<br><br>
    뿌리가 뭔가를 밀어 올린 것이다.<br>
    도굴꾼은 나무가 밀어 올린 것을 안다.<br><br>
    대개 오래 묻힌 것들이다.`,
  opts:[
    { l:'① 파낸다.', dc:13, p:750,
      good:`뿌리 사이를 파냈다. 상자가 나온다.<br><br>나무가 감싸고 있었다. 뿌리가 상자를 안고 자랐다.<br>꺼내려면 뿌리를 잘라야 한다.<br><br>안 잘랐다. 뚜껑만 열어 안을 봤다. 종이가 있다. 젖지 않았다.`, flag:'rootBox',
      bad:`파는데 뿌리가 조인다.<br><br>손을 감는다. 천천히.<br>빼는 데 힘이 들었다.`, poll:8 },
    { l:'② 나무를 벤다.', dc:15, kind:'break', p:800,
      doom:{ title:'벤 뿌리', what:'뿌리가 감고 있습니다', dc:14, sec:70,
        text:`뿌리를 잘랐다. 상자를 꺼내려고.<br><br>잘린 자리에서 물이 나온다. 붉다.<br>남은 뿌리가 움직인다. 잘린 쪽을 향해서가 아니라 이쪽을 향해.<br><br>감긴다. 발목부터.<br>상자를 놓으면 될 텐데 손이 안 펴진다.`,
        dieText:`나무가 감싸고 있던 건 지키고 있던 것이다.<br><br>지키던 것을 뺏으면 대신 가져간다.<br>도굴꾼은 늘 그 값을 나중에 안다.` },
      good:`벨까 하다 그만뒀다.<br><br>나무가 안고 자란 것을 뺏는 건 아니다 싶었다.<br>상자는 두고 뚜껑만 열어 봤다.<br><br>종이가 들어 있다. 한 장 꺼내 왔다. 나머지는 뒀다.`, flag:'tookOnePage' }
  ] }
);

epicSlot('lake', 'digger').push(
{ title:'거울 호수 — 물가에 묻은 것',
  text:`물가 흙이 다르다.<br><br>
    한 자리만 색이 짙다. 파고 덮은 자리다.<br>
    물가에 묻는 건 젖는 걸 알면서 묻는 것이다.<br><br>
    젖어도 상관없는 것이거나, 젖어야 하는 것이거나.`,
  opts:[
    { l:'① 판다.', dc:12, p:700,
      good:`팠다. 얕다. 천에 싼 것이 나온다.<br><br>풀어 보니 돌이다. 그냥 돌.<br>다만 매끈하다. 오래 만져서 매끈해진 돌.<br><br>누가 오래 쥐고 있던 것이다. 도로 묻었다.`, flag:'smoothStone',
      bad:`파는데 물이 차오른다.<br><br>판 만큼 물이 들어온다.<br>손을 넣었다가 뺐다. 뭔가 잡혔었다.`, poll:8 },
    { l:'② 동료와 같이 판다.', co:'sync',
      coOpt:{ ask:'물가를 팝니다. 물을 퍼내 줄 사람이 필요합니다.', sec:60, p:950,
        text:`혼자 파면 물이 먼저 찬다.`,
        doneText:`한쪽이 파고 한쪽이 퍼냈다.<br><br>물이 차는 속도보다 빠르게 팠다.<br>천에 싼 것이 나온다. 풀어 보니 돌이다.<br><br>둘 다 한참 봤다. 돌을 왜 묻어 두었는지는 몰랐다.<br>도로 묻었다. 둘이 덮으니 금방이었다.`,
        failText:`혼자 팠다. 물이 먼저 찼다.<br><br>손만 넣어 더듬었다. 뭔가 잡혔는데 못 꺼냈다.<br>덮었다.` },
      good:`꺼냈다.`, bad:`못 꺼냈다.` }
  ] }
);
;

