epicSlot('gate', 'merchant').push(
{ title:'성문 — 통행세',
  text:`아치 아래 석상이 손을 내민다.<br><br>
    통행세를 받던 자리다. 상인은 이런 걸 알아본다.<br>
    받는 손 모양이 그렇게 굳어 있다.<br><br>
    얼마를 냈는지는 안 적혀 있다.`,
  opts:[
    { l:'① 값을 매겨 낸다.', dc:12, kind:'bond', p:650,
      good:`주머니에서 적당히 꺼내 손에 놓았다.<br><br>손이 오므라든다. 받았다는 뜻이다.<br>받고 나니 아치가 조금 높아진 것 같다.<br><br>값을 치르고 들어가는 게 낫다. 외상은 나중에 비싸다.`, flag:'paidToll',
      bad:`놓았는데 손이 안 오므라든다.<br><br>모자란 것이다. 더 놓았다. 그래도 그대로다.<br>포인트로 받는 곳이 아니었다.`, poll:7 },
    { l:'② 외상으로 하고 지난다.', dc:14, p:750,
      doom:{ title:'외상', what:'외상값을 받으러 왔습니다', dc:14, sec:70,
        text:`손에 아무것도 안 놓고 지나갔다.<br><br>외상이다. 상인은 외상에 익숙하다.<br>다만 여기 외상은 이자가 붙는다.<br><br>등 뒤에서 돌 갈리는 소리가 난다. 석상이 일어섰다.<br>받으러 오는 것이다. 값을 정하는 쪽은 저쪽이다.`,
        dieText:`상인은 외상을 주는 쪽이지 지는 쪽이 아니다.<br><br>여기서 한 번 뒤집혔다.<br>받아 간 것이 무엇이었는지는 장부에만 적혀 있다.` },
      good:`빈손을 내밀어 보였다. 없다는 뜻으로.<br><br>석상이 손을 거둔다. 서운해하지 않는다.<br>없으면 안 받는 규칙인 모양이다.<br><br>상인은 없는 척을 잘한다. 이번엔 진짜 없었다.`, flag:'showedEmpty' }
  ] }
);

epicSlot('temple', 'merchant').push(
{ title:'신전 — 값을 안 받는 곳',
  text:`헌금함이 있다.<br><br>
    넣는 곳이지 받는 곳이 아니다.<br>
    상인은 한 방향으로만 가는 돈을 이상하게 여긴다.<br><br>
    함에 든 것은 종이다. 동전이 아니라.`,
  opts:[
    { l:'① 종이를 읽는다.', dc:12, kind:'gaze', p:650,
      good:`펴 봤다. 부탁이 적혀 있다.<br><br>낫게 해 달라, 돌려 달라, 찾게 해 달라.<br>스물셋 장.<br><br>값이 안 적힌 거래다. 이런 거래도 있다는 걸 여기서 배웠다.`, flag:'readWishes',
      bad:`펴는데 글씨가 번진다.<br><br>젖지도 않았는데. 읽으려 하면 번진다.<br>읽을 자격이 있는 사람이 정해져 있다.`, poll:7 },
    { l:'② 한 장 써서 넣는다.', dc:13, kind:'bond', p:700,
      good:`종이에 적어 넣었다.<br><br>무엇을 적었는지는 나중에 잊었다.<br>적을 때는 분명히 알았는데.<br><br>넣고 나니 함이 조금 무거워진 소리가 났다.`, flag:'wroteWish',
      bad:`적으려는데 값이 먼저 떠오른다.<br><br>얼마짜리 부탁인지 계산하고 있었다.<br>상인의 버릇이다. 여기서는 안 통한다.`, poll:6 }
  ] }
);

epicSlot('forest', 'merchant').push(
{ title:'검은 숲 — 팔 것이 자란다',
  text:`숲에 값나가는 것이 있다.<br><br>
    약초, 수액, 목재. 상인 눈에는 전부 물건이다.<br>
    지고 갈 수 있는 만큼만 가져가면 된다.<br><br>
    다만 여기 것은 값을 매기기 전에 값이 붙어 있다.`,
  opts:[
    { l:'① 값이 붙은 것을 본다.', dc:13, kind:'gaze', p:700,
      good:`나무마다 표식이 있다. 숫자다.<br><br>값이다. 누가 이미 매겨 놓았다.<br>싼 것도 있고 비싼 것도 있다.<br><br>제일 비싼 나무가 숲 가운데 있다. 안 가기로 했다.`, flag:'pricedForest',
      bad:`표식을 세다 보니 이쪽에도 붙는다.<br><br>옷자락에 숫자가 찍혔다.<br>문질러 지웠다. 흐릿하게 남았다.`, poll:8 },
    { l:'② 값이 싼 것부터 가져간다.', dc:12, p:650,
      good:`싼 것으로 골라 지었다.<br><br>싼 건 대개 문제가 적다. 상인이 오래 사는 방식이다.<br>가벼워서 지고 가기도 편했다.`, flag:'cheapHaul',
      bad:`싼 것을 집자 값이 오른다.<br><br>집으면 오른다. 놓으면 내린다.<br>집는 순간 비싸지는 구조였다.`, poll:7 }
  ] }
);

epicSlot('tower', 'merchant').push(
{ title:'탑 — 위에서 본 시세',
  text:`꼭대기에서 마을과 장터가 보인다.<br><br>
    상인은 높은 데서 시장을 본다. 어디에 뭐가 모이는지 보인다.<br>
    여기서는 아무것도 안 모인다.<br><br>
    한 곳만 다르다. 숲과 묘지 사이.`,
  opts:[
    { l:'① 그쪽을 본다.', dc:13, kind:'gaze', p:800,
      good:`한 곳으로 모이는 게 있다. 눈에 보이지는 않는다.<br><br>다만 길 자국이 그쪽을 향한다. 마을에서도, 묘지에서도.<br>거래가 일어나는 곳이 있다는 뜻이다.<br><br>상인이 제일 먼저 찾는 곳이다.`, flag:'deepFound', flag2:true,
      bad:`보려는데 눈이 흐려진다.<br><br>거리를 못 재겠다. 가까운지 먼지 모르겠다.<br>세 번 보고 그만뒀다.`, poll:7 },
    { l:'② 장부에 적는다.', dc:11, p:600,
      good:`보이는 대로 적었다. 어디서 어디로 가는 자국이 있는지.<br><br>적어 두면 나중에 값이 된다.<br>상인은 정보를 물건으로 다룬다.<br><br>적고 나니 자국 하나가 더 보였다.`, flag:'mappedTrade',
      bad:`적는데 먹이 마른다.<br><br>여기서는 적히는 게 더딘 모양이다.<br>절반만 적었다.`, poll:6 }
  ] }
);

epicSlot('lake', 'merchant').push(
{ title:'거울 호수 — 비친 값',
  text:`물에 좌판이 비친다.<br><br>
    여기 좌판이 없는데 비친다.<br>
    비친 좌판에 물건이 놓여 있고 값이 적혀 있다.<br><br>
    읽을 수는 있다. 거꾸로 읽으면 된다.`,
  opts:[
    { l:'① 값을 읽는다.', dc:13, kind:'gaze', p:750,
      good:`거꾸로 읽었다.<br><br>여기 장터에서 본 물건들이다. 값이 전부 다르다.<br>비친 쪽이 싸다. 훨씬.<br><br>사러 갈 수는 없다. 비친 좌판이니까.<br>다만 여기 값이 비싸다는 건 알게 됐다.`, flag:'mirrorPrices',
      bad:`읽는데 값이 오른다.<br><br>읽을 때마다 숫자가 커진다.<br>보는 게 값을 올리는 구조였다.`, poll:8 },
    { l:'② 손을 넣어 사 본다.', dc:15, p:850,
      doom:{ title:'비친 거래', what:'거래가 성립했습니다', dc:14, sec:70,
        text:`물에 손을 넣어 비친 물건을 집었다.<br><br>잡힌다. 실제로 잡힌다.<br>당기려는데 저쪽에서도 당긴다. 값을 받으려는 것이다.<br><br>거래는 양쪽이 있어야 성립한다.<br>성립했다. 치를 차례다.`,
        dieText:`상인은 값을 치르는 쪽이 아니라 받는 쪽에 익숙하다.<br><br>비친 좌판에서는 반대다.<br>비친 쪽이 상인이었다.` },
      good:`손을 넣었다가 뺐다.<br><br>차갑다. 잡힐 것 같았는데 잡으면 안 될 것 같았다.<br>거래는 한 번 성립하면 못 무른다.<br><br>상인은 그걸 제일 잘 안다.`, flag:'noMirrorDeal' }
  ] }
);

// ==========================================
// 📜 전령 — 10장면
// ==========================================
epicSlot('market', 'courier').push(
{ title:'장터 — 붙은 전단',
  text:`기둥에 종이가 붙어 있다.<br><br>
    전단이다. 알리는 글. 전령이 붙이고 다니는 것.<br>
    글씨가 익숙하다. 전령들이 쓰는 서체다.<br><br>
    내용은 한 줄이다.`,
  opts:[
    { l:'① 읽는다.', dc:11, p:600,
      good:`<span style="color:#d4af37;">"스물셋은 안에 있음. 전달 완료."</span><br><br>전달을 마쳤다는 보고다. 붙여 두고 간 것이다.<br>보고할 곳이 없으면 이렇게 한다.<br><br>전령이 마지막에 하는 일이다.`, flag:'postedNotice',
      bad:`읽는데 글자가 바뀐다.<br><br>두 번째에는 다른 내용이다.<br>세 번째에는 이쪽 이름이 들어 있다.`, poll:8 },
    { l:'② 이쪽 전단을 붙인다.', dc:12, kind:'bond', p:650,
      good:`종이에 적어 붙였다. 여기까지 왔다고.<br><br>붙이고 나니 옆에 또 하나가 붙어 있다.<br>다른 전령이 방금 붙인 것 같다. 아무도 없었는데.<br><br>같은 내용이었다.`, flag:'postedMine',
      bad:`붙이는데 풀이 안 먹는다.<br><br>세 번 붙이고 세 번 떨어졌다.<br>기둥이 안 받아 준다.`, poll:6 }
  ] }
);

epicSlot('temple', 'courier').push(
{ title:'신전 — 전할 곳이 없는 편지',
  text:`제단에 편지가 놓여 있다.<br><br>
    받는 사람 자리가 비어 있다.<br>
    전령은 받는 사람이 없는 편지를 제일 곤란해한다.<br><br>
    버릴 수도 없고 전할 수도 없다.`,
  opts:[
    { l:'① 제단에 그대로 둔다.', dc:11, p:600,
      good:`손대지 않고 뒀다.<br><br>여기 둔 사람이 여기 두려고 둔 것이다.<br>받는 사람이 없는 게 아니라, 받는 쪽이 여기인 것이다.<br><br>전령은 남의 배달에 끼어들지 않는다.`, flag:'leftLetter',
      bad:`두고 나오려는데 품에 들어와 있다.<br><br>집은 적이 없다.<br>도로 놓았다. 또 들어왔다.`, poll:8 },
    { l:'② 받는 사람을 적어 넣는다.', dc:14, kind:'bond', p:800,
      doom:{ title:'적은 이름', what:'배달이 시작됐습니다', dc:14, sec:70,
        text:`빈 자리에 이름을 적었다. 아무 이름이나.<br><br>적자 편지가 무거워진다. 배달이 시작된 것이다.<br>전령은 받는 사람에게 닿을 때까지 못 놓는다.<br><br>적은 이름이 누구인지 모른다.<br>모르는 사람에게 닿을 때까지 걸어야 한다.`,
        dieText:`전령은 받는 사람이 정해진 것만 든다.<br><br>정해지지 않은 것을 정해 버리면<br>정한 쪽이 책임진다.` },
      good:`적으려다 붓을 놓았다.<br><br>받는 사람을 정하는 건 전령의 일이 아니다.<br>보내는 쪽이 정한다.<br><br>빈 채로 뒀다. 빈 채로 두는 것도 일이다.`, flag:'leftBlankTo' }
  ] }
);

epicSlot('forest', 'courier').push(
{ title:'검은 숲 — 지름길',
  text:`숲을 가로지르면 빠르다.<br><br>
    돌아가면 오래 걸리고 가로지르면 짧다.<br>
    전령은 늘 짧은 쪽을 고른다. 그게 일이다.<br><br>
    다만 짧은 쪽에 길이 없다.`,
  opts:[
    { l:'① 가로지른다.', dc:13, kind:'evade', p:750,
      doom:{ title:'지름길', what:'숲에서 못 나가고 있습니다', dc:13, sec:65,
        text:`길 없는 쪽으로 들어갔다.<br><br>나무가 같다. 전부 같다. 방향이 안 잡힌다.<br>해가 없어 방향을 못 잡는다.<br><br>같은 자리를 세 번 지났다. 네 번째에 알았다.<br>지름길은 없고, 들어온 길도 없어졌다.`,
        dieText:`전령은 빠른 길을 고르는 사람이다.<br><br>없는 길을 빠른 길로 착각하면 아무 데도 못 간다.<br>전할 것을 들고 도는 것도 전달은 아니다.` },
      good:`가로질렀다. 표식을 남기며.<br><br>나무에 칼집을 내며 갔다. 돌아올 걱정은 안 했다.<br>전령은 앞으로만 간다.<br><br>나왔다. 돌아간 것보다 반은 빨랐다.`, flag:'cutThrough' },
    { l:'② 길을 따라 돌아간다.', dc:10, p:500,
      good:`길로 돌았다. 오래 걸렸다.<br><br>늦는 전령은 못 오는 전령보다 낫다.<br>스승이 그렇게 말했었다. 맞는 말이었다.`, flag:'wentAroundWood',
      bad:`길이 중간에 끊긴다.<br><br>돌아가려는데 돌아갈 길도 없다.<br>결국 숲으로 들어갔다.`, poll:7 }
  ] }
);

epicSlot('tower', 'courier').push(
{ title:'탑 — 위로 전한다',
  text:`탑 꼭대기에 누가 있다는 소식이 있다.<br><br>
    전할 것이 있으면 올라가야 한다.<br>
    계단이 스물넷이다. 올라갈 때만.<br><br>
    전령은 계단을 세면서 오른다. 버릇이다.`,
  opts:[
    { l:'① 올라가 전한다.', dc:12, kind:'bond', p:700,
      good:`올라갔다. 꼭대기에 아무도 없다.<br><br>관측대에 기록이 있다. 마지막 장에 적었다.<br>여기까지 전하러 왔다고, 받을 사람이 없었다고.<br><br>적는 것도 전달이다. 언젠가 읽힌다.`, flag:'deliveredUp',
      bad:`올라가는데 계단이 안 끝난다.<br><br>스물넷을 넘어 계속 오른다.<br>세는 걸 그만두니 꼭대기가 나왔다.`, poll:7 },
    { l:'② 아래에서 소리쳐 전한다.', dc:11, p:600,
      good:`아래에서 소리쳤다. 내용은 짧게.<br><br>위에서 대답이 없다. 그래도 전했다.<br>전령은 닿았는지 확인할 의무는 없다.<br><br>전한 것으로 끝이다.`, flag:'shoutedUp',
      bad:`소리쳤는데 메아리만 온다.<br><br>메아리가 내용을 바꿔서 돌아온다.<br>다른 말이 됐다.`, poll:7 }
  ] }
);

epicSlot('grave', 'courier').push(
{ title:'묘지 — 마지막 배달',
  text:`비석 앞에 편지가 놓여 있다.<br><br>
    젖었다가 마른 자국이 있다. 오래 놓여 있었다.<br>
    받는 사람이 여기 묻혀 있다는 뜻이다.<br><br>
    전령은 이런 배달도 한다.`,
  opts:[
    { l:'① 읽어 준다.', dc:12, kind:'bond', p:700,
      good:`펴서 소리 내어 읽었다.<br><br>내용은 짧다. 미안하다는 말과 이름 하나.<br>읽고 나서 도로 놓았다. 돌로 눌러서.<br><br>읽어 주는 것까지가 전령의 일이다.`, flag:'readAloud',
      bad:`펴자 글씨가 없다.<br><br>백지다. 오래 놓여 있어서 빠진 것인지, 원래 백지였는지.<br>읽을 게 없어서 그냥 서 있었다.`, poll:7 },
    { l:'② 동료와 같이 읽는다.', co:'witness',
      coOpt:{ ask:'전할 데가 없는 편지가 있습니다. 같이 읽어 주십시오.', sec:60, p:900,
        text:`혼자 읽으면 혼잣말이고 둘이 읽으면 전달이다.`,
        doneText:`둘이서 번갈아 읽었다.<br><br>한 줄씩. 끝까지.<br>다 읽고 둘 다 한참 서 있었다.<br><br>받는 사람이 없어도 읽은 사람이 둘이면 전달이 된다.<br>전령들끼리 그렇게 친다.`,
        failText:`혼자 읽었다.<br><br>혼잣말 같았다.<br>도로 놓고 왔다.` },
      good:`전달됐다.`, bad:`혼잣말이 됐다.` }
  ] }
);

// ==========================================
// 🐎 마부 — 10장면
// ==========================================
epicSlot('market', 'driver').push(
{ title:'장터 — 바퀴를 고친다',
  text:`좌판 뒤에 수레가 있다.<br><br>
    바퀴 하나가 빠졌다. 테가 헐거워져서 빠진 것이다.<br>
    마부는 바퀴를 고칠 줄 안다. 고쳐야 가니까.<br><br>
    테를 다시 끼우려면 불이 있어야 한다.`,
  opts:[
    { l:'① 화덕을 빌려 고친다.', co:'handoff',
      coOpt:{ ask:'바퀴 테를 달굴 손이 필요합니다.', sec:60, p:950,
        text:`불 다루는 사람이 있으면 금방이다.`,
        doneText:`누가 와서 불을 봐 줬다.<br><br>테를 달궈 끼우고 물을 부었다. 쇠가 조이며 소리가 났다.<br>딱 맞는다.<br><br>둘이서 바퀴를 끼웠다. 수레가 굴러간다.<br>굴러가는 걸 보는 건 몇 번을 봐도 좋다.`,
        failText:`혼자 해 봤다. 불이 모자란다.<br><br>테가 덜 달궈져서 안 들어간다.<br>수레를 두고 갔다.` },
      good:`고쳤다.`, bad:`못 고쳤다.`, flag:'fixedWheel' },
    { l:'② 수레를 그냥 끈다.', dc:13, kind:'break', p:700,
      good:`세 바퀴로 끌었다. 기울어진 채로.<br><br>느리고 시끄럽다. 그래도 간다.<br>마부는 가는 게 중요하지 모양이 중요하지 않다.`, flag:'draggedCart',
      bad:`끌다가 축이 부러졌다.<br><br>세 바퀴로도 못 가게 됐다.<br>두고 갔다.`, poll:7 }
  ] }
);

epicSlot('temple', 'driver').push(
{ title:'신전 — 말을 매던 자리',
  text:`신전 밖에 고리가 박혀 있다.<br><br>
    말을 매던 고리다. 줄 자국이 깊다.<br>
    오래 매어 뒀다는 뜻이다.<br><br>
    고리가 스물넷 개다.`,
  opts:[
    { l:'① 세어 본다.', dc:11, kind:'gaze', p:600,
      good:`스물넷이다. 자국 깊이가 다르다.<br><br>스물셋은 깊고 하나는 얕다.<br>스물셋은 오래 매어 뒀고 하나는 잠깐 매었다가 갔다.<br><br>간 쪽이 하나다.`, flag:'hitchCount',
      bad:`세는데 하나가 흔들린다.<br><br>줄도 없는데 흔들린다.<br>매인 게 있다는 뜻이다.`, poll:7 },
    { l:'② 고리를 만져 본다.', dc:12, p:650,
      doom:{ title:'매는 자리', what:'고리가 손을 감았습니다', dc:13, sec:65,
        text:`자국이 깊은 고리에 손을 넣어 봤다.<br><br>손목이 들어간다. 맞는다.<br>말 목에 맞춰 만든 게 아니라 사람 손목에 맞춰 만든 것이다.<br><br>빼려는데 조인다. 고리가 아니라 줄이 있다.<br>보이지 않는 줄이.`,
        dieText:`마부는 매는 사람이다.<br><br>매는 사람이 매이면 풀어 줄 사람이 없다.<br>고리 자국이 하나 더 깊어졌다.` },
      good:`손끝만 대 보고 뺐다.<br><br>맞는 크기다. 사람 손목에 맞다.<br>말 매는 고리가 아니었다.<br><br>안 넣었다. 넣었으면 어떻게 됐을지는 짐작이 간다.`, flag:'wristHitch' }
  ] }
);

epicSlot('forest', 'driver').push(
{ title:'검은 숲 — 수레가 못 가는 곳',
  text:`나무가 빽빽해 수레가 안 들어간다.<br><br>
    마부에게 수레가 못 가는 곳은 못 가는 곳이다.<br>
    지고 가면 되지만, 그럼 마부가 아니다.<br><br>
    길을 내면 된다.`,
  opts:[
    { l:'① 길을 낸다.', dc:14, kind:'break', p:800,
      good:`가지를 치고 밀며 갔다. 오래 걸렸다.<br><br>한 번 지나가니 길이 된다. 길은 원래 그렇게 생긴다.<br>돌아 나올 때 훨씬 빨랐다.<br><br>마부가 남기는 건 바퀴 자국뿐이다.`, flag:'cutRoad',
      bad:`치는 족족 도로 선다.<br><br>가지가 아물듯이 돌아온다.<br>세 번 하고 그만뒀다.`, poll:8 },
    { l:'② 수레를 두고 간다.', dc:11, p:550,
      good:`숲 입구에 세워 두고 걸어 들어갔다.<br><br>걸어 다니는 마부는 이상하다. 이상해도 간다.<br>나와 보니 수레가 그대로 있었다.<br><br>그대로 있는 게 반가웠다.`, flag:'parkedCart',
      bad:`세워 두고 왔더니 자리가 다르다.<br><br>조금 옮겨져 있다. 바퀴 자국이 있다.<br>누가 끌었다가 도로 두고 갔다.`, poll:7 }
  ] }
);

epicSlot('lake', 'driver').push(
{ title:'거울 호수 — 물가의 바퀴 자국',
  text:`물가에 바퀴 자국이 있다.<br><br>
    물 쪽으로 들어간다. 나오는 자국이 없다.<br>
    마부가 물로 수레를 몬 것이다.<br><br>
    몰 이유가 있었거나, 못 세웠거나.`,
  opts:[
    { l:'① 자국 깊이를 본다.', dc:12, kind:'sense', p:650,
      good:`깊다. 짐을 잔뜩 실었다.<br><br>실은 채로 물로 들어갔다.<br>짐을 버리면 가벼워지는데 안 버렸다.<br><br>마부는 짐을 안 버린다. 그래서 그렇게 됐다.`, flag:'sunkCart',
      bad:`깊이를 재는데 자국이 사라진다.<br><br>물이 닿은 자리부터 지워진다.<br>다 지워지고 나니 아무 일도 없었던 것 같다.`, poll:7 },
    { l:'② 물에 들어가 본다.', dc:14, p:800,
      doom:{ title:'물속 자국', what:'물속으로 들어갔습니다', dc:14, sec:70,
        text:`자국을 따라 들어갔다. 발목, 무릎, 허리.<br><br>바닥이 단단하다. 바퀴 자국이 그대로 있다.<br>따라가면 수레가 있을 것이다.<br><br>보인다. 저 앞에. 짐을 실은 채로.<br>수레 앞에 누가 서 있다. 끌채를 잡고.`,
        dieText:`마부는 수레를 두고 가지 못한다.<br><br>물속에 있는 수레도 수레다.<br>끌 사람이 하나 더 생겼다.` },
      good:`발목까지 들어가 보고 나왔다.<br><br>바닥에 바퀴 자국이 이어진다. 계속.<br>따라가면 수레가 나올 것이다.<br><br>안 따라갔다. 물속 수레는 수레가 아니다.`, flag:'sawUnderTrack' }
  ] }
);

epicSlot('grave', 'driver').push(
{ title:'묘지 — 실어 온 것',
  text:`묘지 입구에 바퀴 자국이 있다.<br><br>
    깊게 들어와 얕게 나갔다. 무거운 걸 싣고 와서 내려놓고 갔다.<br>
    스물셋 번쯤 오간 자국이다.<br><br>
    마부가 한 일이다.`,
  opts:[
    { l:'① 자국을 세어 본다.', dc:12, kind:'gaze', p:700,
      good:`겹친 자국을 세어 봤다. 스물셋.<br><br>스물셋 번 싣고 와서 스물셋 번 내려놓았다.<br>마지막 자국은 들어온 것만 있고 나간 게 없다.<br><br>마지막에 온 마부는 안 나갔다.`, flag:'lastDriver',
      bad:`세다 보니 자국이 겹친다.<br><br>같은 자국인지 다른 자국인지 구분이 안 간다.<br>스물셋인지 스물넷인지 모르겠다.`, poll:8 },
    { l:'② 마지막 수레를 찾는다.', dc:13, kind:'sense', p:750,
      good:`자국을 따라 묘지 안쪽으로 갔다.<br><br>수레가 있다. 비어 있다. 끌채가 땅에 닿아 있다.<br>내려놓은 자세 그대로.<br><br>끌던 사람은 안 보인다. 자국도 없다.`, flag:'emptyCart',
      bad:`따라가는데 자국이 봉분으로 들어간다.<br><br>수레째로 들어간 것이다.<br>거기서 끊긴다.`, poll:8 }
  ] }
);
;

// ---------- epic-boost-8.js ----------
// ==========================================
// ★ Qtrew-???-■■■ — 보강 8 · 마법사 · 서기 · 묘지기
// index.html 에서 epic-boost-7.js 다음에 불러온다
// ==========================================

// ==========================================
// ✨ 마법사 — 10장면
// ==========================================
epicSlot('gate', 'mage').push(
{ title:'성문 — 새겨진 문장',
  text:`아치 안쪽에 글자가 새겨져 있다.<br><br>
    대부분 깎여 나갔고 두 글자만 읽힌다.<br>
    <span style="color:#d4af37;">"영웅"</span><br><br>
    마법사는 깎여 나간 쪽을 읽는 법을 배운다.<br>
    깎인 자리에도 결이 남는다.`,
  opts:[
    { l:'① 결을 읽는다.', dc:13, kind:'gaze', p:750,
      good:`손끝으로 결을 더듬었다.<br><br>깎인 자리에 획이 남아 있다. 읽어 보니 앞뒤가 나온다.<br><span style="color:#d4af37;">"■■이 영웅을 ■■하던 시절의 ■■■"</span><br><br>"묻던"으로 읽힌다. 다르게 읽을 수도 있는데 그렇게 읽혔다.`, flag:'readCarving',
      bad:`더듬는데 결이 바뀐다.<br><br>읽을 때마다 다른 글자가 된다.<br>세 번 읽고 손을 뗐다.`, poll:8 },
    { l:'② 깎아 낸 사람을 짐작한다.', dc:12, kind:'sense', p:650,
      good:`정 자국이 있다. 안쪽에서 바깥으로 쳤다.<br><br>성 안에서 나와 깎은 것이다.<br>밖에서 온 사람이 지운 게 아니라 안에 있던 사람이 지웠다.<br><br>읽히면 곤란한 문장이었던 모양이다.`, flag:'insideErased',
      bad:`자국을 보다가 손이 미끄러졌다.<br><br>새 자국이 하나 생겼다.<br>이쪽도 지운 사람이 됐다.`, poll:7 }
  ] }
);

epicSlot('market', 'mage').push(
{ title:'장터 — 팔리는 주문',
  text:`좌판에 종이가 있다.<br><br>
    주문을 적어 파는 것이다. 값이 싸다.<br>
    싼 주문은 대개 가짜거나, 대가가 나중에 붙는다.<br><br>
    한 장을 펴 보니 진짜다.`,
  opts:[
    { l:'① 어떤 주문인지 읽는다.', dc:13, kind:'gaze', p:750,
      good:`읽었다. 부르는 주문이다.<br><br>이름을 넣으면 부른다. 탑 벽 문장과 같은 문법이다.<br>같은 데서 나온 것이다.<br><br>사지 않았다. 부르는 주문은 싸게 사면 안 된다.`, flag:'callScroll',
      bad:`읽는데 눈이 따라간다.<br><br>읽고 있는 게 아니라 읽히고 있다.<br>덮었다. 손에 잉크가 묻었다.`, poll:8 },
    { l:'② 한 장 산다.', dc:14, p:800,
      doom:{ title:'산 주문', what:'대가를 치르고 있습니다', dc:14, sec:70,
        text:`샀다. 값이 싸다.<br><br>주인이 고개를 든다. 얼굴이 있다. 웃고 있다.<br><span style="color:#d4af37;">"대가는 나중에 받습니다."</span><br><br>나중이 지금이 됐다.<br>종이가 손에서 타들어 간다. 불이 아니라 안으로 말려든다.<br>손째로.`,
        dieText:`마법사는 싼 주문을 안 산다.<br><br>주문에 값이 싸다는 건 사는 쪽이 대가라는 뜻이다.<br>제일 먼저 배우는 것이었다.` },
      good:`사려다 값을 다시 물었다.<br><br>주인이 대가를 나중에 받는다고 했다.<br>나중에 받는 거래는 안 한다. 마법사는 그렇게 배운다.<br><br>도로 놓고 나왔다.`, flag:'refusedScroll' }
  ] }
);

epicSlot('forest', 'mage').push(
{ title:'검은 숲 — 기울기의 이유',
  text:`나무가 한쪽으로 기울어 있다.<br><br>
    바람도 없고 빛도 없는데 기운다.<br>
    마법사는 기울기가 힘의 방향이라는 걸 안다.<br><br>
    힘이 어디서 오는지 보면 된다.`,
  opts:[
    { l:'① 기울기의 중심을 잡는다.', mini:'scale', miniOpt:{ p:800, target:26, pool:[4,5,8,9,11,13] },
      good:`나무마다 기운 각도를 재서 맞춰 봤다.<br><br>한 점으로 모인다. 숲 가운데 둥근 자리.<br>거기서 미는 게 아니라 당기고 있다.<br><br>당기는 쪽이 중심이다.`, flag:'pullCenter',
      bad:`각도가 안 맞는다.<br><br>재는 동안 기울기가 바뀐다.<br>중심이 움직이고 있다.` },
    { l:'② 기울기를 되돌려 본다.', dc:15, p:850,
      doom:{ title:'되돌린 것', what:'나무가 이쪽으로 기울고 있습니다', dc:14, sec:70,
        text:`가까운 나무 하나를 밀어 바로 세웠다.<br><br>세우자 옆 나무가 더 기운다. 힘이 옮겨 간 것이다.<br>옮겨 간 힘이 다시 옮겨 간다. 이쪽으로.<br><br>나무 여럿이 이쪽을 향해 기운다.<br>바로 선 나무는 하나뿐이고 나머지가 전부 기울었다.`,
        dieText:`기울어 있는 데는 이유가 있다.<br><br>바로 세우면 이유가 다른 데로 간다.<br>다른 데가 이쪽이었다.` },
      good:`밀다가 손을 뗐다.<br><br>미는 만큼 옆이 기운다. 힘의 총량이 정해져 있는 구조다.<br>하나를 세우면 하나가 더 기운다.<br><br>세우지 않는 게 맞다.`, flag:'leftLeaning' }
  ] }
);

epicSlot('grave', 'mage').push(
{ title:'묘지 — 백지에 남은 것',
  text:`비석이 백지다.<br><br>
    마법사는 지워진 글자를 읽는다. 지운 것도 흔적이다.<br>
    손을 대면 결이 남아 있다.<br><br>
    다만 여기 것은 결이 없다.`,
  opts:[
    { l:'① 결이 없는 이유를 본다.', dc:14, kind:'gaze', p:800,
      good:`결이 없다는 건 지운 게 아니라는 뜻이다.<br><br>새긴 적이 없다.<br>이름을 안 새긴 게 아니라 이름이 없어서 못 새겼다.<br><br>이름 없이 묻힌 게 아니라, 이름을 두고 온 것들이다.`, flag:'neverCarved',
      bad:`손을 대자 결이 생긴다.<br><br>없던 결이 손 아래에서 생긴다.<br>글자가 되어 간다. 읽기 전에 손을 뗐다.`, poll:9 },
    { l:'② 이름을 되돌리는 문장을 쓴다.', dc:16, p:900,
      doom:{ title:'되돌린 이름', what:'이름이 몰려오고 있습니다', dc:15, sec:75,
        text:`탑 벽에서 읽은 문법으로 문장을 썼다.<br><br>두고 온 것을 되돌리는 문장이다.<br>쓰자 비석이 하나씩 따뜻해진다. 스물셋 개가.<br><br>이름이 돌아온다. 돌아올 자리를 찾아서.<br>자리가 모자란다. 스물셋 개의 이름이 하나를 향해 온다.`,
        dieText:`이름은 하나씩만 있는 것이다.<br><br>스물셋 개를 한꺼번에 받으면 원래 것이 밀려난다.<br>밀려난 이름을 부를 사람이 없다.` },
      good:`쓰려다 붓을 놓았다.<br><br>스물셋 개를 한꺼번에 되돌리면 어디로 가는지 모른다.<br>모르는 걸 하는 건 마법사가 아니라 도박사다.<br><br>안 썼다.`, flag:'didntUndo' }
  ] }
);

epicSlot('road', 'mage').push(
{ title:'끊긴 길 — 없어진 구간',
  text:`길 중간이 없다.<br><br>
    무너진 게 아니다. 단면이 깨끗하다.<br>
    마법사는 잘린 것과 지워진 것을 구분한다.<br><br>
    이건 지워졌다.`,
  opts:[
    { l:'① 지워진 자리를 읽는다.', dc:14, kind:'gaze', p:800,
      good:`단면에 손을 댔다. 결이 있다.<br><br>여기 길이 있었다는 결이. 지운 쪽이 급했던 모양이다.<br>덜 지워진 부분이 남았다.<br><br>읽어 보니 길이 아니라 문장이었다. 길 모양으로 적힌 문장.`, flag:'erasedRoad',
      bad:`손을 대자 단면이 넓어진다.<br><br>지워지는 중이었다. 아직도.<br>손을 뗐다. 손끝이 조금 흐려졌다.`, poll:9 },
    { l:'② 안개를 걷어 본다.', dc:15, p:850,
      doom:{ title:'걷은 안개', what:'아래가 드러났습니다', dc:14, sec:70,
        text:`손을 저어 안개를 밀었다.<br><br>걷힌다. 아래가 보인다.<br>아래에 아무것도 없다. 바닥이 아니라 없음이다.<br><br>없음을 오래 보면 안 된다. 마법사가 제일 먼저 배우는 것이다.<br>보고 있다. 발이 안 떨어진다.`,
        dieText:`안개는 덮어 두라고 있는 것이었다.<br><br>덮인 것을 걷으면 덮여 있던 이유를 알게 된다.<br>알면 못 돌아온다.` },
      good:`조금 걷다가 그만뒀다.<br><br>안개 아래가 어두운 게 아니라 아무것도 없다.<br>덮여 있는 데는 이유가 있다.<br><br>손을 거뒀다. 안개가 도로 덮였다.`, flag:'leftFog' }
  ] }
);

// ==========================================
// 🖋 서기 — 10장면
// ==========================================
epicSlot('gate', 'scribe').push(
{ title:'성문 — 첫 줄',
  text:`석상이 말한다.<br><br>
    <span style="color:#d4af37;">"들어온 자는 여럿, 나간 자는 하나."</span><br><br>
    서기는 들은 것을 적는다. 그게 일이다.<br>
    적을 데가 없어서 손등에 적었다.`,
  opts:[
    { l:'① 적는다.', dc:11, p:600,
      good:`손등에 적었다. 짧게.<br><br>적고 나니 기억이 또렷해진다. 적으면 그렇게 된다.<br>서기가 적는 이유는 잊지 않으려는 게 아니라 또렷해지려는 것이다.<br><br>여기서는 또렷한 게 중요하다.`, flag:'firstLine',
      bad:`적는데 글자가 손등에 배어든다.<br><br>안으로 들어간다. 문질러도 안 나온다.<br>손등 아래에서 읽힌다.`, poll:8 },
    { l:'② 누가 나갔는지 묻고 적는다.', dc:13, kind:'bond', p:700,
      good:`물었다. 석상이 대답한다.<br><span style="color:#d4af37;">"이름이 없었소."</span><br><br>적었다. 이름 없는 자가 나갔다고.<br>나가려면 이름이 없어야 한다는 뜻으로도 읽힌다.<br><br>두 가지로 읽히게 적어 뒀다. 서기가 하는 일이다.`, flag:'namelessOne',
      bad:`묻자 석상이 이쪽 이름을 묻는다.<br><br>안 말했다.<br>안 말했는데 석상이 고개를 끄덕였다.`, poll:8 }
  ] }
);

epicSlot('market', 'scribe').push(
{ title:'장터 — 장부를 파는 좌판',
  text:`좌판에 장부가 쌓여 있다.<br><br>
    쓴 것도 있고 백지도 있다.<br>
    서기에게 백지 장부는 값나가는 물건이다.<br><br>
    쓴 것 중 하나가 눈에 걸린다.`,
  opts:[
    { l:'① 쓴 장부를 읽는다.', dc:12, kind:'gaze', p:700,
      good:`펴 봤다. 거래 기록이다.<br><br>맨 뒤에 사람 이름이 적혀 있다. 스물셋.<br>값은 안 적혀 있다.<br><br>값이 없는 건 이미 팔린 것이라고 상인들이 말한다.`, flag:'soldNames',
      bad:`읽는데 줄이 늘어난다.<br><br>읽는 속도보다 빠르다.<br>덮었다. 덮으니 멈췄다.`, poll:7 },
    { l:'② 백지를 산다.', dc:11, p:600,
      good:`백지 장부를 하나 샀다. 값은 안 받았다.<br><br>서기에게는 안 받는 모양이다.<br>적을 것이 생기면 쓸 것이다.<br><br>여기서는 적을 게 많다.`, flag:'blankLedger',
      bad:`백지를 폈는데 글자가 있다.<br><br>희미하게. 전에 적힌 것이 배어 나온 것이다.<br>읽을 수는 없다.`, poll:6 }
  ] }
);

epicSlot('village', 'scribe').push(
{ title:'빈 마을 — 기록이 없는 곳',
  text:`마을에 적힌 것이 없다.<br><br>
    문패도, 장부도, 이름표도 없다.<br>
    사람이 살던 곳에 적힌 게 하나도 없는 건 이상하다.<br><br>
    적지 않은 게 아니라 없앤 것 같다.`,
  opts:[
    { l:'① 적힌 것이 있던 자리를 찾는다.', dc:13, kind:'gaze', p:750,
      good:`문 위에 자국이 있다. 문패를 떼어 낸 자국.<br><br>집집마다 있다. 스물셋 개.<br>같은 날 한꺼번에 뗐다.<br><br>적힌 것을 없애면 없던 일이 된다. 서기는 그걸 제일 잘 안다.`, flag:'removedSigns',
      bad:`자국을 보다 보니 새 자국이 생긴다.<br><br>보는 자리마다 생긴다.<br>보는 게 만드는 것이 되고 있었다.`, poll:8 },
    { l:'② 문패를 새로 써서 붙인다.', dc:14, kind:'bond', p:800,
      doom:{ title:'붙인 문패', what:'집이 사람을 부르고 있습니다', dc:14, sec:70,
        text:`종이에 적어 문 위에 붙였다. 아무 이름이나.<br><br>붙이자 집 안에서 소리가 난다. 밥상 차리는 소리.<br>이름이 붙으면 사는 사람이 있는 것이 된다.<br><br>사는 사람이 있으면 들어가야 한다.<br>문이 열린다. 안에서.`,
        dieText:`적힌 것은 일어난 일이 된다.<br><br>서기가 평생 믿어 온 것이고, 여기서는 그게 그대로 작동한다.<br>스물셋 집에 스물넷째 이름이 붙었다.` },
      good:`쓰다가 붙이지 않았다.<br><br>이름을 붙이면 사는 사람이 생긴다.<br>없는 사람을 만드는 건 서기의 일이 아니다.<br><br>적은 종이는 품에 넣었다.`, flag:'unpostedName' }
  ] }
);

epicSlot('ruin', 'scribe').push(
{ title:'폐허 — 천장의 줄',
  text:`천장 무늬가 스물넷 줄이다.<br><br>
    서기 눈에는 기록으로 보인다. 줄마다 한 항목.<br>
    맨 윗줄이 비어 있다.<br><br>
    기록에서 맨 위는 가장 최근이다.`,
  opts:[
    { l:'① 아래부터 읽는다.', dc:13, kind:'gaze', p:750,
      good:`아래가 가장 오래된 것이다.<br><br>스물셋 줄에 스물셋 항목. 읽어 보니 사람 이름이다.<br>위로 갈수록 새 이름이다.<br><br>맨 위가 비었다는 건 아직 안 적혔다는 뜻이다.`, flag:'ceilingList',
      bad:`읽다 보니 줄이 섞인다.<br><br>순서가 바뀐다. 오래된 게 위로 온다.<br>읽는 순서를 잃었다.`, poll:8 },
    { l:'② 빈 줄을 기록에 남긴다.', dc:12, p:700,
      good:`장부에 옮겨 적었다. 스물셋 항목과 빈 한 줄.<br><br>빈 줄도 적었다. 비어 있다고 적어 두는 것도 기록이다.<br>비어 있다는 사실이 남으면 채우려는 쪽이 주춤한다.<br><br>서기가 할 수 있는 일이 그 정도다.`, flag:'recordedGap',
      bad:`적는데 빈 줄이 안 적힌다.<br><br>비어 있는 걸 적으려니 적을 게 없다.<br>세 번 시도하고 넘어갔다.`, poll:6 }
  ] }
);

epicSlot('road', 'scribe').push(
{ title:'끊긴 길 — 지워진 기록',
  text:`길 단면에 층이 보인다.<br><br>
    흙이 층층이 쌓인 자리. 서기는 층을 기록으로 읽는다.<br>
    한 층씩이 한 시절이다.<br><br>
    중간에 층이 하나 빠져 있다.`,
  opts:[
    { l:'① 빠진 층을 본다.', dc:13, kind:'gaze', p:750,
      good:`위층과 아래층 사이가 붙어 있다.<br><br>한 시절이 통째로 없다. 쌓이지 않은 게 아니라 걷어 낸 것이다.<br>그 시절에 있었던 일을 없애려고.<br><br>없앤 흔적은 남는다. 그게 서기의 위안이다.`, flag:'missingLayer',
      bad:`보는데 층이 더 없어진다.<br><br>위층이 사라진다. 보는 앞에서.<br>지금 지워지고 있는 중이었다.`, poll:9 },
    { l:'② 동료에게 확인시킨다.', co:'witness',
      coOpt:{ ask:'단면에 이상한 것이 있습니다. 같이 봐 주십시오.', sec:60, p:950,
        text:`혼자 본 것은 주장이고 둘이 본 것은 기록이다.`,
        doneText:`동료가 와서 같이 봤다.<br><br>층이 빠진 자리를 둘 다 짚었다. 같은 자리를 짚었다.<br>같은 것을 봤다는 뜻이다.<br><br>장부에 두 이름을 적었다. 이제 이건 일어난 일이다.`,
        failText:`혼자 봤다.<br><br>적어 두긴 했는데 주장으로 남는다.<br>주장은 나중에 뒤집힌다.` },
      good:`기록이 됐다.`, bad:`주장으로 남았다.` }
  ] }
);

// ==========================================
// ⚰ 묘지기 — 10장면
// ==========================================
epicSlot('gate', 'keeper').push(
{ title:'성문 — 들어온 수',
  text:`석상이 말한다.<br><br>
    <span style="color:#d4af37;">"들어온 자는 여럿, 나간 자는 하나."</span><br><br>
    묘지기는 수를 듣고 그냥 못 넘어간다.<br>
    여럿이 몇인지 물어야 한다.`,
  opts:[
    { l:'① 몇이냐고 묻는다.', dc:12, kind:'bond', p:700,
      good:`물었다. 석상이 대답한다.<br><span style="color:#d4af37;">"스물넷."</span><br><br>스물넷이 들어와서 하나가 나갔다.<br>스물셋이 남았다는 뜻이다.<br><br>묘지 비석이 스물셋인 이유를 알겠다.`, flag:'twentyFourIn',
      bad:`묻자 석상이 되묻는다.<br><br><span style="color:#d4af37;">"세어 보시오."</span><br>세라는 건 여기서 위험한 말이다.`, poll:8 },
    { l:'② 받침의 이름을 센다.', dc:11, kind:'gaze', p:650,
      good:`스물넷이다. 하나만 지워져 있다.<br><br>지워진 자리가 깨끗하다. 방금 지운 것처럼.<br>나간 하나가 지워진 것이다.<br><br>이름을 지우면 나갈 수 있는 모양이다.`, flag:'erasedToLeave',
      bad:`세는데 지워진 게 늘어난다.<br><br>스물셋에서 스물둘로.<br>보는 앞에서 하나씩 지워진다.`, poll:9 }
  ] }
);

epicSlot('market', 'keeper').push(
{ title:'장터 — 세는 사람',
  text:`좌판마다 물건이 놓여 있다.<br><br>
    묘지기는 습관적으로 센다. 좌판이 몇인지, 주인이 몇인지.<br>
    좌판은 스물넷인데 주인은 스물셋이다.<br><br>
    빈 좌판이 하나 있다.`,
  opts:[
    { l:'① 빈 좌판을 본다.', dc:12, kind:'gaze', p:700,
      good:`물건이 놓여 있다. 주인만 없다.<br><br>먼지가 안 앉았다. 방금까지 있었다는 뜻이다.<br>좌판에 놓인 것은 백지다. 종이, 천, 비석 조각.<br><br>전부 이름이 들어갈 자리가 비어 있는 것들이다.`, flag:'emptyStall',
      bad:`보는데 좌판 뒤에 누가 서 있다.<br><br>방금까지 없었다.<br>고개를 숙이고 있다. 다른 주인들과 같은 자세로.`, poll:8 },
    { l:'② 그 좌판을 대신 지킨다.', dc:13, kind:'bond', p:750,
      doom:{ title:'대신 선 자리', what:'좌판에서 떠날 수 없습니다', dc:14, sec:70,
        text:`빈 좌판 뒤에 섰다. 잠깐만.<br><br>서 있으니 사람이 온다. 물건을 본다. 값을 묻는다.<br>대답하니 사 간다.<br><br>다음 사람이 온다. 또 온다.<br>떠나려는데 줄이 서 있다. 주인이 자리를 비우면 안 된다.`,
        dieText:`묘지기는 자리를 지키는 사람이다.<br><br>어느 자리든 지키게 되어 있다.<br>좌판이 스물넷이 됐고 주인도 스물넷이 됐다.` },
      good:`잠깐 서 있다 나왔다.<br><br>사람이 오기 전에 나왔다. 오면 못 나간다는 걸 알았다.<br>빈 좌판은 빈 채로 뒀다.<br><br>비어 있는 것을 채우는 게 늘 좋은 건 아니다.`, flag:'leftStallEmpty' }
  ] }
);

epicSlot('temple', 'keeper').push(
{ title:'신전 — 초의 수',
  text:`촛불이 켜져 있다.<br><br>
    세어 보니 스물셋이다. 묘지 비석과 같은 수다.<br>
    초대는 스물넷 개다.<br><br>
    하나가 비어 있다.`,
  opts:[
    { l:'① 빈 초대를 본다.', dc:12, kind:'gaze', p:700,
      good:`밀랍 자국이 있다. 꽂혀 있던 자국.<br><br>빠진 게 아니라 뽑아 간 것이다.<br>누가 초 하나를 가져갔다.<br><br>가져간 초는 지금도 타고 있을 것이다. 여기 초는 안 줄어드니까.`, flag:'takenCandle',
      bad:`보는데 자국이 없어진다.<br><br>원래 없었던 자리가 된다.<br>스물셋 개가 원래 전부였던 것처럼.`, poll:8 },
    { l:'② 하나 꽂아 채운다.', dc:14, p:800,
      doom:{ title:'채운 초', what:'초가 되어 가고 있습니다', dc:14, sec:70,
        text:`가진 초를 꽂았다. 스물넷이 됐다.<br><br>꽂은 초에 불이 붙는다. 저절로.<br>붙는 동안 손끝이 하얘진다.<br><br>밀랍처럼. 여기 초는 꽂으면 여기 것이 된다.<br>꽂은 손도.`,
        dieText:`초는 스물셋이었고 초대는 스물넷이었다.<br><br>비워 둔 자리를 채우면 채운 쪽이 그 자리가 된다.<br>이제 스물넷이다.` },
      good:`꽂으려다 손을 멈췄다.<br><br>여기 초는 안 줄어든다. 안 줄어드는 건 사람이 아니다.<br>꽂으면 안 줄어드는 쪽이 된다.<br><br>안 꽂았다. 스물셋으로 뒀다.`, flag:'keptTwentyThree' }
  ] }
);

epicSlot('lake', 'keeper').push(
{ title:'거울 호수 — 아래로 가는 수',
  text:`물 아래로 불빛이 지나간다.<br><br>
    줄지어. 한 방향으로.<br>
    묘지기는 세는 사람이다. 셌다.<br><br>
    스물셋이다.`,
  opts:[
    { l:'① 어디로 가는지 본다.', dc:13, kind:'sense', p:750,
      good:`불빛이 가는 방향을 따라 물가를 걸었다.<br><br>호수 반대편으로 간다. 거기서 물 밖으로 나온다.<br>나오는 자리가 숲과 묘지 사이다.<br><br>스물셋이 그리로 가고 있다.`, flag:'deepFound', flag2:true,
      bad:`따라가는데 불빛이 멈춘다.<br><br>전부 이쪽을 향해 방향을 튼다.<br>물러났다.`, poll:8 },
    { l:'② 하나 더 있는지 본다.', dc:12, kind:'gaze', p:700,
      good:`오래 봤다. 스물셋이 지나가고 한참 뒤에 하나가 더 온다.<br><br>혼자. 뒤처져서.<br>스물넷째다.<br><br>뒤처진 하나가 있었다.`, flag:'lateOne',
      bad:`세는데 자꾸 수가 바뀐다.<br><br>스물셋, 스물넷, 스물둘.<br>물 아래는 세기 어렵다.`, poll:7 }
  ] }
);

epicSlot('road', 'keeper').push(
{ title:'끊긴 길 — 건너간 수',
  text:`안개 위에 발자국이 있다.<br><br>
    묘지기는 세는 사람이다. 셌다.<br>
    건너간 자국이 스물셋.<br><br>
    돌아온 자국은 없다.`,
  opts:[
    { l:'① 세고 기록해 둔다.', dc:11, p:650,
      good:`길 이쪽 끝 돌에 새겼다. 스물셋.<br><br>다음에 오는 사람이 볼 것이다.<br>스물셋이 건너갔고 안 돌아왔다는 것을.<br><br>세어 두고 알려 두는 게 묘지기의 일이다.`, flag:'countedCrossers',
      bad:`새기는데 숫자가 안 맞는다.<br><br>세 번 세고 세 번 다르다.<br>제일 많은 수로 새겼다.`, poll:7 },
    { l:'② 스물넷째가 되지 않는다.', dc:12, p:700,
      good:`안 건넜다.<br><br>스물셋이 건너갔고 안 돌아왔다. 스물넷째가 될 이유가 없다.<br>세는 사람은 세어지는 쪽이 되면 안 된다.<br><br>돌아섰다. 돌아서는 데 힘이 들었다.`, flag:'stayedThis',
      bad:`돌아서는데 발이 이미 안개에 올라가 있다.<br><br>언제 올렸는지 모르겠다.<br>뒤로 뺐다. 신발이 젖었다.`, poll:8 }
  ] }
);
;

