epicSlot('market', 'thief').push(
{ title:'장터 — 손이 빠른 쪽',
  text:`좌판 사이가 좁다.<br><br>
    부딪히면 손이 닿고, 손이 닿으면 가져올 수 있다.<br>
    도적이 제일 편한 자리다.<br><br>
    다만 여기 주인들은 고개를 안 든다. 안 드는데도 안다.`,
  opts:[
    { l:'① 부딪히며 지난다.', mini:'beat', miniOpt:{ p:750, total:10, gap:600 },
      good:`열 번. 한 번도 안 걸렸다.<br><br>주머니가 묵직하다. 뭘 가져왔는지는 나중에 본다.<br>가져온 것보다 안 걸린 게 중요하다.`, flag:'pickpocket',
      bad:`세 번째에서 손목이 잡혔다.<br><br>주인 손이다. 고개는 여전히 숙인 채로.<br>놓아 준다. 다만 그다음부터 좌판마다 손이 나와 있다.` },
    { l:'② 돌아서 간다.', dc:10, p:400,
      good:`좌판을 피해 가장자리로 돌았다.<br><br>멀다. 다만 아무 일도 없다.<br>도적이 안 훔치고 지나가는 날도 있다.`, flag:'wentAround',
      bad:`돌아가는 길에 아무도 없다.<br><br>없는데 누가 지나간 자국이 있다.<br>방금 생긴 자국이다.`, poll:6 }
  ] },

{ title:'장터 — 좌판 아래',
  text:`좌판마다 아래가 비어 있다.<br><br>
    천이 드리워져 안이 안 보인다.<br>
    도적은 보이지 않는 곳부터 본다.<br><br>
    천 아래에서 숨소리가 난다.`,
  opts:[
    { l:'① 천을 들춘다.', dc:13, kind:'sense', p:650,
      doom:{ title:'좌판 아래', what:'천 아래로 끌려 들어갔습니다', dc:13, sec:65,
        text:`들췄다.<br><br>사람이 웅크리고 있다. 좌판 주인과 같은 옷이다.<br>여기 주인들은 전부 아래에도 하나씩 있다.<br><br>손이 나온다. 발목을 잡는다.<br>천 안쪽이 넓다. 좌판보다 훨씬.`,
        dieText:`좌판이 하나 늘었다.<br><br>주인이 둘인 좌판이다. 위에 하나, 아래에 하나.<br>원래 그랬던 것처럼 보인다.` },
      good:`들췄다. 아무것도 없다.<br><br>숨소리는 계속 난다. 다만 나는 자리가 없다.<br>덮고 물러났다.<br><br>없는 곳에서 나는 소리는 확인하지 않는 게 낫다.`, flag:'underStall' },
    { l:'② 천 아래로 손만 넣는다.', dc:12, p:600,
      good:`손만 넣어 더듬었다.<br><br>상자가 있다. 잠겨 있지 않다.<br>안에서 하나 꺼냈다. 뭔지는 밖에 나와서 봤다.`, flag:'reachedUnder',
      bad:`손을 넣자 잡힌다.<br><br>쥐는 게 아니라 쓰다듬는다.<br>빼는 데 시간이 걸렸다.`, poll:8 }
  ] },

{ title:'장터 — 안 파는 것',
  text:`좌판 하나에 값이 안 붙은 물건이 있다.<br><br>
    다른 것들은 전부 값이 있는데 그것만 없다.<br>
    도적은 값 없는 물건을 좋아한다. 훔쳐도 계산이 안 되니까.<br><br>
    주인이 그 물건만 손으로 덮고 있다.`,
  opts:[
    { l:'① 눈을 돌리게 한다.', dc:13, kind:'evade', p:700,
      good:`옆 좌판 물건을 넘어뜨렸다.<br><br>주인이 그쪽을 본다. 아주 잠깐.<br>그 사이에 집었다.<br><br>손에 쥐니 가볍다. 무게가 없는 것에 가깝다.`, flag:'stoleNoPrice',
      bad:`넘어뜨렸는데 아무도 안 본다.<br><br>주인 손은 그대로 덮여 있다.<br>덮은 쪽이 더 중요한 것이다.`, poll:7 },
    { l:'② 값을 물어본다.', dc:11, p:500,
      good:`얼마냐고 물었다.<br><br>주인이 처음으로 고개를 든다.<br><span style="color:#d4af37;">"이건 안 팔리는 게 아니라 안 사지는 것이오."</span><br><br>무슨 뜻인지는 안 물었다.`, flag:'askedPrice',
      bad:`묻자 주인이 손을 뗀다.<br><br>가져가라는 뜻이다.<br>안 가져갔다.`, poll:6 }
  ] },

{ title:'장터 — 나눠 턴다',
  text:`혼자 털면 한 좌판이다.<br><br>
    둘이면 한쪽이 시선을 끌고 한쪽이 가져온다.<br>
    도적 일은 원래 둘이 하는 것이다.<br><br>
    혼자 하는 도적은 오래 못 한다.`,
  opts:[
    { l:'① 동료에게 시선을 부탁한다.', co:'sync',
      coOpt:{ ask:'잠깐 소란을 일으켜 주십시오. 그 사이에 가져오겠습니다.', sec:60, p:950,
        text:`한쪽이 끌면 한쪽이 가져온다.`,
        doneText:`동료가 좌판 하나를 통째로 넘어뜨렸다.<br><br>과했다. 다만 효과는 확실했다.<br>주인들이 전부 그쪽을 본다.<br><br>그 사이에 세 좌판을 훑었다. 셋 다 성공했다.<br>나눠 가졌다. 나누니 덜 아깝다.`,
        failText:`혼자 했다. 한 좌판에서 하나.<br><br>그것도 금방 들켰다. 놓고 나왔다.<br>혼자 하는 도적은 이래서 오래 못 한다.` },
      good:`셋을 털었다.`, bad:`빈손이다.`, flag:'teamSteal' }
  ] }
);

epicSlot('gate', 'thief').push(
{ title:'성문 — 잠긴 적 없는 문',
  text:`성문에 자물쇠가 없다.<br><br>
    걸쇠 자국도 없다. 처음부터 잠근 적이 없는 문이다.<br>
    도적에게는 이게 더 이상하다.<br><br>
    잠글 필요가 없었다는 뜻이니까.`,
  opts:[
    { l:'① 문틀을 살핀다.', dc:12, kind:'sense', p:600,
      good:`문틀 안쪽에 긁힌 자국이 있다.<br><br>밖에서가 아니라 안에서 긁었다. 손톱이다.<br>나가려던 쪽이 긁은 것이다.<br><br>문은 잠기지 않았는데 못 나갔다.`, flag:'clawedFrame',
      bad:`살피는데 문이 조금 움직인다.<br><br>바람이 없다.<br>손을 뗐다.`, poll:7 },
    { l:'② 걸쇠를 만들어 단다.', dc:13, kind:'break', p:700,
      good:`쇠붙이를 구부려 걸쇠를 만들었다.<br><br>달았다. 잠기지는 않지만 표시는 된다.<br>다음에 지날 때 움직였는지 알 수 있다.<br><br>도적은 문에 표시를 남기는 버릇이 있다.`, flag:'madeLatch',
      bad:`구부린 쇠가 도로 펴진다.<br><br>세 번 하고 그만뒀다.<br>이 문은 걸쇠를 안 받는다.`, poll:6 }
  ] }
);

epicSlot('road', 'thief').push(
{ title:'끊긴 길 — 버려진 짐',
  text:`길가에 짐이 쌓여 있다.<br><br>
    주인이 없다. 도적에게 주인 없는 짐은 물건이 아니라 기회다.<br>
    다만 여기 짐은 너무 가지런하다.<br><br>
    버린 게 아니라 놓아 둔 모양이다.`,
  opts:[
    { l:'① 뒤진다.', dc:12, p:650,
      doom:{ title:'놓아 둔 짐', what:'짐에 손이 붙었습니다', dc:13, sec:65,
        text:`열었다. 옷가지다. 깨끗하다.<br><br>맨 아래에 뭔가 단단한 게 있다.<br>잡았다. 놓아지지 않는다.<br><br>짐이 무거워진다. 끌려간다. 길 끝 쪽으로.<br>주인이 돌아온 것이 아니라, 주인이 되어 가는 것이다.`,
        dieText:`짐이 하나 늘었다.<br><br>가지런하게. 다음에 지나는 도적이 열어 볼 만하게.` },
      good:`위쪽만 들춰 봤다. 옷가지다.<br><br>아래는 안 건드렸다. 가지런한 짐은 아래가 위험하다.<br>배운 적은 없는데 안다.<br><br>덮어 두고 갔다.`, flag:'leftPack' },
    { l:'② 표시만 남기고 간다.', dc:10, p:450,
      good:`짐 위에 돌을 하나 올려 뒀다.<br><br>도적끼리 쓰는 표시다. 건드리지 말라는 뜻.<br>누가 볼지는 모르겠다. 그래도 남겼다.`, flag:'markedPack',
      bad:`올린 돌이 굴러떨어진다.<br><br>세 번 올리고 세 번 떨어졌다.<br>표시를 거부하는 짐이었다.`, poll:5 }
  ] },

{ title:'끊긴 길 — 안개 속의 주머니',
  text:`안개 위에 주머니가 떠 있다.<br><br>
    가라앉지 않는다. 손을 뻗으면 닿는 거리다.<br>
    도적의 손이 먼저 움직인다.<br><br>
    손이 먼저 움직이는 게 늘 좋지는 않다.`,
  opts:[
    { l:'① 잡아당긴다.', dc:14, kind:'luck', p:750,
      doom:{ title:'떠 있던 것', what:'안개 속으로 딸려 갑니다', dc:14, sec:70,
        text:`잡았다. 가볍다.<br><br>당기는데 안 온다. 아래에서 잡고 있다.<br>줄이 있다. 주머니는 미끼였다.<br><br>팔이 안개에 들어갔다. 어깨까지.<br>놓으면 되는데, 손이 안 펴진다. 도적의 손은 늘 그렇다.`,
        dieText:`미끼를 문 것이다.<br><br>도적은 놓는 법을 제일 늦게 배운다.<br>대개는 배우기 전에 끝난다.` },
      good:`잡았다가 곧 놓았다.<br><br>당겨지는 느낌이 왔을 때 놓았다.<br>주머니가 안개 속으로 내려갔다. 소리 없이.<br><br>손에 실오라기가 하나 남았다.`, flag:'letGoPouch' },
    { l:'② 막대기로 건드린다.', dc:11, kind:'sense', p:550,
      good:`나뭇가지로 밀어 봤다.<br><br>주머니가 가라앉는다. 가지도 같이 딸려 들어간다.<br>놓았다.<br><br>가지가 아니라 팔이었으면 어땠을지 생각했다.`, flag:'pokedPouch',
      bad:`가지를 대자 주머니가 이쪽으로 온다.<br><br>밀었는데 왔다.<br>물러났다.`, poll:8 }
  ] }
);

epicSlot('castle', 'thief').push(
{ title:'성 — 값나가는 것만',
  text:`방마다 물건이 있다.<br><br>
    전부 가져갈 수는 없다. 도적은 고르는 눈으로 먹고산다.<br>
    무거운 것보다 작고 비싼 것.<br><br>
    다만 여기 물건은 값을 가늠할 수가 없다.`,
  opts:[
    { l:'① 작은 것만 고른다.', dc:12, p:650,
      good:`손바닥에 들어오는 것만 골랐다. 여섯 개.<br><br>주머니에 넣으니 소리가 안 난다.<br>소리 안 나는 게 좋은 물건이다.<br><br>나와서 보니 다 값나가는 것이었다. 눈이 아직 살아 있다.`, flag:'smallLoot',
      bad:`고르는데 손안에서 무거워진다.<br><br>작은 것이 무겁다. 넣을수록 무겁다.<br>절반을 도로 놓았다.`, poll:7 },
    { l:'② 제일 비싸 보이는 것 하나만.', dc:14, kind:'luck', p:750,
      good:`한참 보고 하나를 골랐다.<br><br>금도 보석도 아니다. 그냥 낡은 상자다.<br>다만 다른 것들이 그 주위를 비켜 놓여 있었다.<br><br>비켜 놓인 것이 제일 비싸다. 도적의 눈이다.`, flag:'oneBest',
      bad:`고른 것을 드니 뒤에서 소리가 난다.<br><br>다른 물건들이 자리를 옮기는 소리다.<br>놓았다. 소리가 멎었다.`, poll:9 }
  ] },

{ title:'성 — 빠져나가는 길',
  text:`들어온 문이 안 보인다.<br><br>
    도적은 들어가기 전에 나갈 길을 정한다.<br>
    정해 뒀는데 없다.<br><br>
    복도가 하나 늘었거나, 하나 줄었다.`,
  opts:[
    { l:'① 세면서 되짚는다.', dc:13, kind:'sense', p:700,
      good:`걸음 수를 세며 되돌아갔다.<br><br>스물셋 걸음. 들어올 때와 같다.<br>같은데 문이 없다. 벽이다.<br><br>벽을 밀었다. 열렸다. 문은 처음부터 벽이었다.`, flag:'wallDoor',
      bad:`세다가 숫자가 섞인다.<br><br>스물넷, 스물둘.<br>세는 걸 그만두니 복도가 더 길어졌다.`, poll:8 },
    { l:'② 창으로 나간다.', dc:14, kind:'evade', p:750,
      doom:{ title:'창밖', what:'창틀에 끼었습니다', dc:13, sec:65,
        text:`창을 열고 몸을 넣었다.<br><br>어깨까지 들어갔다. 허리가 안 나간다.<br>창이 좁아졌다. 들어갈 때는 넓었는데.<br><br>뒤로 빼려는데 뒤도 안 된다.<br>창틀이 조인다. 천천히, 계속.`,
        dieText:`도적은 창으로 드나드는 사람이다.<br><br>여기 창은 드나드는 곳이 아니라 끼우는 곳이었다.` },
      good:`창을 열고 아래를 봤다.<br><br>높다. 다만 아래에 처마가 있다.<br>처마를 짚고 내려왔다.<br><br>내려오면서 창을 닫았다. 도적의 버릇이다.`, flag:'outWindow' }
  ] }
);

epicSlot('forest', 'thief').push(
{ title:'검은 숲 — 숨겨 둔 것',
  text:`나무 아래 흙이 다져져 있다.<br><br>
    누가 묻어 둔 자리다. 도적은 묻은 자리를 안다.<br>
    다진 방식이 서툴다. 급하게 묻었다.<br><br>
    급하게 묻은 것은 대개 값나간다.`,
  opts:[
    { l:'① 판다.', dc:12, p:650,
      good:`손으로 팠다. 얕다.<br><br>천에 싼 것이 나온다. 풀어 보니 주머니다.<br>안에 동전이 들어 있다. 오래된 것들.<br><br>도로 묻지 않았다. 묻은 사람은 안 올 것이다.`, flag:'dugCache',
      bad:`파는데 손에 뭔가 닿는다.<br><br>천이 아니다. 따뜻하다.<br>덮었다.`, poll:8 },
    { l:'② 누가 묻었는지 본다.', dc:13, kind:'sense', p:700,
      good:`주변 발자국을 봤다. 하나뿐이다.<br><br>오는 자국만 있고 가는 자국이 없다.<br>묻고 나서 안 갔다는 뜻이다.<br><br>파지 않았다. 판단이 섰다.`, flag:'noReturn',
      bad:`발자국이 이쪽 것이다.<br><br>크기도 걸음 폭도 같다.<br>묻은 적이 없는데.`, poll:9 }
  ] }
);

epicSlot('temple', 'thief').push(
{ title:'신전 — 초를 센다',
  text:`초가 스물셋이다.<br><br>
    도적은 수를 센다. 수를 알아야 하나를 가져가도 모른다.<br>
    스물셋 중 하나는 표가 안 난다.<br><br>
    다만 이 초들은 안 줄어든다고 들었다.`,
  opts:[
    { l:'① 하나 가져간다.', dc:13, p:700,
      doom:{ title:'가져간 초', what:'초가 손에서 타고 있습니다', dc:13, sec:65,
        text:`하나 뽑아 품에 넣었다.<br><br>불이 안 꺼진다. 품 안에서 계속 탄다.<br>뜨겁지 않다. 다만 옷이 탄다.<br><br>꺼내려는데 손이 밀랍이다.<br>초가 줄지 않는 이유를 알겠다. 대신 다른 게 준다.`,
        dieText:`초는 스물셋 그대로다.<br><br>가져간 하나가 도로 꽂혀 있다.<br>다만 조금 굵어졌다.` },
      good:`하나 뽑았다가 도로 꽂았다.<br><br>손에 쥔 순간 뜨겁지 않은 게 이상해서 꽂았다.<br>뜨겁지 않은 불은 불이 아니다.<br><br>세어 보니 여전히 스물셋이다.`, flag:'putBackCandle' },
    { l:'② 세기만 한다.', dc:10, p:450,
      good:`세 번 셌다. 세 번 다 스물셋이다.<br><br>안 줄어든다는 말은 맞았다.<br>가져가지 않았으니 확인할 수는 없지만.`, flag:'countedCandles',
      bad:`세는데 하나가 더 있다.<br><br>스물넷. 다시 세니 스물셋.<br>또 세니 스물넷.`, poll:7 }
  ] }
);

epicSlot('ruin', 'thief').push(
{ title:'폐허 — 무너진 뒤에 남은 것',
  text:`무너진 자리에 물건이 깔려 있다.<br><br>
    도적은 무너진 곳을 좋아한다. 주인이 확실히 없으니까.<br>
    돌 사이에 금속이 보인다.<br><br>
    빼내려면 돌을 움직여야 한다.`,
  opts:[
    { l:'① 돌을 치운다.', dc:13, kind:'break', p:700,
      doom:{ title:'치운 돌', what:'무너진 것에 깔렸습니다', dc:14, sec:70,
        text:`하나씩 치웠다. 세 개쯤 치우자 금속이 보인다.<br><br>손을 뻗는 순간 위쪽이 움직인다.<br>치운 돌이 받치고 있던 것이었다.<br><br>다리가 눌렸다. 무겁다.<br>금속은 손끝에 닿아 있다. 닿기만 한다.`,
        dieText:`폐허에서 돌을 치우는 건 도적의 일이 아니다.<br><br>도적은 이미 열린 곳으로 들어가는 사람이다.<br>열려고 하면 이렇게 된다.` },
      good:`위쪽부터 확인하고 아래를 치웠다.<br><br>순서가 중요하다. 받치는 돌을 마지막에.<br>빼냈다. 쇠붙이다. 녹이 안 슬었다.<br><br>주머니에 넣고 물러났다.`, flag:'pulledMetal' },
    { l:'② 포기한다.', dc:9, p:350,
      good:`보기만 하고 갔다.<br><br>도적이 포기하는 건 드문 일이다.<br>드문 일을 한 날은 대개 오래 산다.`, flag:'gaveUpRuin',
      bad:`돌아서는데 뒤에서 소리가 난다.<br><br>돌이 저절로 움직이는 소리다.<br>금속이 드러난다. 가져가라는 듯이.`, poll:7 }
  ] }
);

epicSlot('grave', 'thief').push(
{ title:'묘지 — 손대지 않는 것',
  text:`비석 앞에 놓인 것들이 있다.<br><br>
    꽃, 동전, 접힌 종이.<br>
    도적에게도 안 가져가는 것이 있다. 무덤 앞의 것이 그렇다.<br><br>
    배운 게 아니라 그냥 안 가져간다.`,
  opts:[
    { l:'① 안 건드린다.', dc:10, p:500,
      good:`지나쳤다.<br><br>도적이 지키는 규칙은 몇 개 안 된다. 이건 그중 하나다.<br>지키니 마음이 가볍다.<br><br>가벼운 게 드문 곳이다.`, flag:'respectedGrave',
      bad:`지나치는데 동전 하나가 굴러온다.<br><br>발밑에 멎었다. 가져가라는 뜻 같았다.<br>제자리에 도로 놓았다.`, poll:6 },
    { l:'② 접힌 종이만 읽는다.', dc:12, kind:'gaze', p:600,
      good:`펴서 읽었다. 짧다.<br><span style="color:#d4af37;">"먼저 가서 미안하다."</span><br><br>도로 접어 놓았다. 읽은 티가 안 나게.<br>읽는 건 가져가는 게 아니다. 그렇게 치기로 했다.`, flag:'readGraveNote',
      bad:`펴자 글씨가 번진다.<br><br>젖지도 않았는데 번진다.<br>읽을 자격이 없다는 뜻으로 받아들였다.`, poll:7 }
  ] }
);

epicSlot('lake', 'thief').push(
{ title:'거울 호수 — 비친 주머니',
  text:`물에 비친 이쪽 주머니가 불룩하다.<br><br>
    실제 주머니는 비어 있다.<br>
    도적은 이런 걸 그냥 못 넘긴다.<br><br>
    저쪽 주머니에는 뭔가 들어 있다.`,
  opts:[
    { l:'① 비친 주머니에 손을 넣는다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'비친 주머니', what:'저쪽 손이 이쪽을 잡았습니다', dc:14, sec:70,
        text:`물에 손을 넣어 비친 주머니를 더듬었다.<br><br>닿는다. 안에 뭔가 있다. 잡았다.<br>당기는데 저쪽도 당긴다.<br><br>저쪽 손이 이쪽 손목을 잡았다.<br>거울에 비친 도적도 도적이다. 같은 걸 노린다.`,
        dieText:`둘 다 같은 것을 잡고 있었다.<br><br>먼저 놓는 쪽이 지는 게임인데,<br>도적은 놓지 않는다. 둘 다.` },
      good:`손을 대 보고 뺐다.<br><br>차갑다. 비친 것에 손이 닿는다는 게 이상해서 뺐다.<br>이상한 건 안 건드린다.<br><br>주머니는 여전히 저쪽만 불룩하다.`, flag:'mirrorPocket' },
    { l:'② 이쪽 주머니를 확인한다.', dc:11, p:500,
      good:`뒤집어 봤다. 비어 있다.<br><br>비친 쪽이 틀린 것이다. 이쪽이 맞다.<br>그렇게 믿기로 했다.<br><br>믿는 게 도적에게는 드문 일이다.`, flag:'checkedOwn',
      bad:`뒤집는데 뭔가 떨어진다.<br><br>주운 적 없는 물건이다.<br>주머니에 도로 넣었다.`, poll:7 }
  ] }
);

epicSlot('tower', 'thief').push(
{ title:'탑 — 위에 둔 것',
  text:`꼭대기 관측대에 물건이 놓여 있다.<br><br>
    여기까지 올라와서 둔 것이다.<br>
    올라오기 힘든 곳에 두는 건 숨기려는 것이다.<br><br>
    도적은 숨긴 것을 찾는 사람이다.`,
  opts:[
    { l:'① 가져간다.', dc:13, p:700,
      good:`집었다. 작은 상자다. 잠겨 있지 않다.<br><br>안에 종이 한 장. 별자리가 그려져 있다.<br>빠진 자리가 표시돼 있다.<br><br>값나가는 건 아니다. 다만 쓸 데가 있을 것 같다.`, flag:'towerBox',
      bad:`집는 순간 무거워진다.<br><br>드는 것이 아니라 붙잡는 것이 된다.<br>놓았다.`, poll:8 },
    { l:'② 놓인 자리를 본다.', dc:12, kind:'sense', p:600,
      good:`먼지 자국을 봤다.<br><br>여기 놓인 지 오래됐다. 다만 최근에 누가 들었다 놓았다.<br>자국이 조금 어긋나 있다.<br><br>먼저 온 사람이 있었다.`, flag:'movedRecently',
      bad:`자국이 이쪽 손 모양이다.<br><br>들은 적이 없다.<br>손을 펴 대 봤다. 맞는다.`, poll:9 }
  ] }
);

epicSlot('village', 'thief').push(
{ title:'빈 마을 — 아무도 없는 집',
  text:`문이 열려 있다.<br><br>
    도적에게 열린 문은 초대다.<br>
    다만 스물셋 집이 전부 열려 있으면 초대가 아니라 다른 것이다.<br><br>
    닫혀 있던 적이 없는 집들이다.`,
  opts:[
    { l:'① 한 집만 들어간다.', dc:12, p:650,
      good:`한 집만 골라 들어갔다.<br><br>밥상이 있다. 온기가 있다.<br>아무것도 안 가져왔다. 가져올 게 없어서가 아니라,<br>가져오면 안 될 것 같아서.<br><br>나오면서 문을 닫았다. 처음으로 닫힌 문이 하나 생겼다.`, flag:'closedOneDoor',
      bad:`들어가자 문이 닫힌다.<br><br>안에서 닫혔다. 밀어서 열었다.<br>나오니 다시 열려 있다.`, poll:8 },
    { l:'② 전부 들어간다.', dc:15, kind:'evade', p:850,
      doom:{ title:'스물셋 집', what:'마지막 집에서 나오지 못했습니다', dc:14, sec:70,
        text:`하나씩 들어갔다. 스물둘까지는 같았다.<br><br>밥상, 온기, 아무도 없음.<br>스물셋째 집이 다르다.<br><br>누가 앉아 있다. 이쪽을 보고 있다.<br>스물둘 번을 기다린 얼굴이다. 문이 닫힌다.`,
        dieText:`스물셋 집이 스물넷이 될 수는 없다.<br><br>대신 안에 있는 것이 하나 늘었다.<br>다음에 오는 도적이 스물셋째 집에서 볼 것이다.` },
      good:`열여덟 집까지 들어갔다.<br><br>전부 같았다. 열아홉째에서 그만뒀다.<br>같은 것을 열여덟 번 보면 그만두게 된다.<br><br>남은 다섯 집은 안 봤다. 안 본 게 나았을 것이다.`, flag:'eighteenHouses' }
  ] }
);
;

// ---------- epic-thief-2.js ----------
// ==========================================
// ★ 도적 확장 2/3 — 32장면
// index.html 에서 epic-thief-1.js 다음에 불러온다
// ==========================================

epicSlot('market', 'thief').push(
{ title:'장터 — 저울을 속인다',
  text:`좌판에 저울이 있다.<br><br>
    도적이 저울을 보면 속일 생각부터 한다.<br>
    추 하나를 바꾸면 값이 달라진다.<br><br>
    다만 여기 저울은 무게가 아니라 값을 잰다.`,
  opts:[
    { l:'① 추를 바꿔 단다.', mini:'scale', miniOpt:{ p:800, target:19, pool:[2,3,5,6,8,11] },
      good:`맞췄다.<br><br>저울이 이쪽에 유리하게 기운다. 주인이 모른다.<br>모르는 게 아니라 안 보는 것이다.<br><br>값을 후하게 받고 나왔다. 뒤가 찜찜했다.`, flag:'riggedScale',
      bad:`어긋났다.<br><br>저울이 반대로 기운다. 손해 보는 쪽으로.<br>속이려다 속은 셈이다.` },
    { l:'② 추를 훔친다.', dc:12, kind:'hide', p:650,
      good:`제일 작은 추를 집어 주머니에 넣었다.<br><br>가볍다. 추치고는 너무 가볍다.<br>나와서 재 보니 무게가 없다.<br><br>무게 없는 추는 어디에 쓰는지 모르겠다. 챙겨 뒀다.`, flag:'stoleWeight',
      bad:`집는 순간 저울이 울린다.<br><br>종소리 같은 게 났다.<br>내려놓자 멎었다.`, poll:7 }
  ] },

{ title:'장터 — 뒤를 따라오는 것',
  text:`장터를 나서는데 발소리가 따라온다.<br><br>
    도적은 따라오는 소리에 민감하다. 직업병이다.<br>
    멈추면 멎고, 걸으면 난다.<br><br>
    반 박자 늦게.`,
  opts:[
    { l:'① 갑자기 돌아선다.', dc:13, kind:'sense', p:700,
      good:`세 걸음 걷다 홱 돌아섰다.<br><br>아무도 없다. 다만 발자국이 하나 더 있다.<br>이쪽 것 옆에 나란히.<br><br>크기가 같다. 걸음 폭도 같다.`, flag:'sameStride',
      bad:`돌아서는데 아무 소리도 안 난다.<br><br>따라오던 것이 멎은 게 아니라 원래 없었던 것 같다.<br>다시 걸으니 또 난다.`, poll:8 },
    { l:'② 좁은 데로 들어간다.', dc:12, kind:'evade', p:650,
      good:`좌판 사이 틈으로 몸을 밀어 넣었다.<br><br>도적은 좁은 데를 잘 안다.<br>따라오던 소리가 입구에서 멎는다.<br><br>못 들어온다. 그것만 확인하고 나왔다.`, flag:'squeezedThrough',
      bad:`틈에 들어갔는데 앞뒤가 다 막혔다.<br><br>들어올 때는 트여 있었다.<br>옆으로 빠져나왔다. 옷이 찢어졌다.`, poll:8 }
  ] },

{ title:'장터 — 맡아 둔 물건',
  text:`좌판 하나에 이쪽 이름이 적힌 꾸러미가 있다.<br><br>
    맡긴 적이 없다.<br>
    도적은 자기 이름이 적힌 물건을 제일 무서워한다.<br><br>
    이름을 남기지 않는 게 일인데.`,
  opts:[
    { l:'① 찾아간다.', dc:14, kind:'gaze', p:750,
      doom:{ title:'맡긴 적 없는 것', what:'꾸러미가 손을 놓지 않습니다', dc:14, sec:70,
        text:`이름을 대고 받았다.<br><br>주인이 순순히 내준다. 확인도 안 한다.<br>열었다. 안에 이쪽 물건이 들어 있다.<br><br>어제 잃어버린 것, 작년에 버린 것, 아직 안 산 것.<br>손이 안 펴진다. 전부 이쪽 것이라서.`,
        dieText:`맡긴 적 없는 물건이 돌아오는 건<br>돌려줄 사람이 생겼다는 뜻이다.<br><br>좌판에 꾸러미가 하나 늘었다. 이름이 적혀 있다.` },
      good:`이름을 대지 않고 꾸러미만 봤다.<br><br>글씨가 이쪽 필체다. 적은 적이 없는데.<br>안 받았다.<br><br>받지 않으면 이쪽 것이 아니다. 그렇게 치기로 했다.`, flag:'refusedParcel' },
    { l:'② 이름을 지운다.', dc:12, kind:'break', p:650,
      good:`손톱으로 긁어 지웠다.<br><br>지워진다. 생각보다 쉽게.<br>이름이 없어지자 꾸러미가 평범해졌다.<br><br>그래도 안 가져갔다.`, flag:'scratchedName',
      bad:`지우는데 다시 적힌다.<br><br>긁는 속도보다 빠르다.<br>손을 뗐다.`, poll:9 }
  ] }
);

epicSlot('gate', 'thief').push(
{ title:'성문 — 받침돌 아래',
  text:`석상 받침에 틈이 있다.<br><br>
    도적은 틈을 본다. 틈에는 대개 뭔가 끼어 있다.<br>
    손가락이 들어갈 만한 넓이다.<br><br>
    안쪽에서 바람이 나온다.`,
  opts:[
    { l:'① 손가락을 넣는다.', dc:12, p:650,
      doom:{ title:'받침 아래', what:'손가락이 물렸습니다', dc:13, sec:60,
        text:`넣었다. 종이 같은 게 만져진다.<br><br>당기는데 안 나온다. 걸린 게 아니라 잡혔다.<br>틈이 좁아진다.<br><br>돌이 움직이는 게 아니라, 안쪽이 오므라든다.<br>손가락 두 개가 들어가 있다.`,
        dieText:`받침 아래가 왜 비어 있었는지는 안 적혀 있다.<br><br>다만 손가락 자국이 여럿 있었다.<br>세어 볼 걸 그랬다.` },
      good:`손끝만 넣어 보고 뺐다.<br><br>안쪽이 미지근하다. 돌이 미지근할 이유가 없다.<br>넣지 않았다.<br><br>도적은 미지근한 틈에 손을 안 넣는다. 배운 게 아니라 안다.`, flag:'warmGap' },
    { l:'② 막대기로 긁어낸다.', dc:11, p:550,
      good:`가지를 넣어 긁었다.<br><br>종이가 딸려 나온다. 접혀 있다.<br>펴 보니 이름 목록이다. 스물넷.<br><br>맨 아래 하나만 줄이 안 그어져 있다.`, flag:'gateList',
      bad:`가지를 넣자 안에서 물어 부러뜨린다.<br><br>부러진 쪽이 안 나온다.<br>손을 안 넣길 잘했다.`, poll:7 }
  ] }
);

epicSlot('road', 'thief').push(
{ title:'끊긴 길 — 지나간 흔적',
  text:`길에 수레 자국이 있다.<br><br>
    도적은 자국을 읽는다. 무엇이 지나갔고 얼마나 실었는지.<br>
    깊다. 무겁게 실었다.<br><br>
    다만 끊긴 자리까지 가서 멈추지 않았다.`,
  opts:[
    { l:'① 자국을 따라간다.', dc:12, kind:'sense', p:650,
      good:`따라갔다. 끊긴 자리에서 안개로 들어간다.<br><br>멈춘 자국이 없다. 속도를 안 줄였다.<br>몰랐거나, 알고도 갔거나.<br><br>안개 앞에 바퀴 하나가 떨어져 있다.`, flag:'wheelTrack',
      bad:`따라가는데 자국이 이쪽으로 돈다.<br><br>나온 게 아니라 이쪽으로 오는 중이다.<br>귀를 기울였다. 아무 소리도 없다.`, poll:8 },
    { l:'② 바퀴를 챙긴다.', dc:11, p:550,
      good:`쇠테를 벗겨 챙겼다.<br><br>도적은 통째로 안 가져간다. 값나가는 부분만.<br>쇠테는 팔린다. 나무는 안 팔린다.`, flag:'tookRim',
      bad:`벗기는데 바퀴가 돈다.<br><br>세워져 있지도 않은데 돈다.<br>놓고 물러났다.`, poll:7 }
  ] }
);

epicSlot('castle', 'thief').push(
{ title:'성 — 열쇠 구멍',
  text:`방문에 열쇠 구멍이 있다.<br><br>
    도적은 열기 전에 들여다본다. 안을 보고 들어가는 게 순서다.<br>
    눈을 대면 보인다.<br><br>
    다만 저쪽에서도 이쪽이 보인다.`,
  opts:[
    { l:'① 들여다본다.', dc:13, kind:'gaze', p:700,
      doom:{ title:'열쇠 구멍', what:'저쪽에서 보고 있습니다', dc:13, sec:65,
        text:`눈을 댔다.<br><br>어둡다. 아무것도 없다.<br>그러다 어둠 가운데가 밝아진다. 눈이다.<br><br>저쪽도 눈을 대고 있었다. 같은 높이에서.<br>떼려는데 안 떨어진다. 구멍이 좁아진다.`,
        dieText:`열쇠 구멍은 양쪽에서 보는 구멍이다.<br><br>도적은 늘 이쪽에서만 본다고 생각한다.<br>그게 오래 가는 착각이다.` },
      good:`눈을 대기 전에 손가락을 먼저 대 봤다.<br><br>바람이 안 나온다. 막혀 있다는 뜻이다.<br>막힌 구멍은 안 본다.<br><br>그냥 땄다. 안은 비어 있었다.`, flag:'blockedHole' },
    { l:'② 그냥 딴다.', mini:'lock', miniOpt:{ p:750, rounds:3 },
      good:`세 핀을 차례로 눌렀다.<br><br>소리 없이 열렸다. 좋은 자물쇠다.<br>좋은 자물쇠 뒤에는 좋은 게 있다.<br><br>있었다. 상자 하나.`, flag:'pickedRoom',
      bad:`두 번째 핀이 도로 떨어진다.<br><br>안에서 밀고 있다.<br>세 번 하고 그만뒀다.` }
  ] },

{ title:'성 — 값을 매기는 방',
  text:`방 하나에 장부와 저울이 있다.<br><br>
    여기서 값을 매겼다. 성 안 물건 전부를.<br>
    도적에게 장부는 지도와 같다.<br><br>
    어디에 뭐가 있고 얼마인지 다 적혀 있다.`,
  opts:[
    { l:'① 장부를 훑는다.', dc:13, kind:'gaze', p:750,
      good:`빠르게 넘겼다. 도적은 읽는 게 아니라 찾는다.<br><br>제일 비싼 줄을 찾았다. 값이 안 적혀 있다.<br>값 없는 게 제일 비싸다.<br><br>어느 방인지는 적혀 있다. 외웠다.`, flag:'ledgerRoom',
      bad:`넘기는데 줄이 늘어난다.<br><br>읽는 속도보다 빠르다.<br>덮었다.`, poll:8 },
    { l:'② 장부를 가져간다.', dc:14, p:750,
      doom:{ title:'가져간 장부', what:'장부가 이름을 적고 있습니다', dc:14, sec:70,
        text:`품에 넣었다. 무겁다.<br><br>걷는 동안 안에서 종이 넘어가는 소리가 난다.<br>꺼내 보니 새 줄이 적히고 있다.<br><br>이쪽 이름이다. 값 칸이 비어 있다.<br>채워지는 중이다.`,
        dieText:`장부는 값을 매기는 물건이다.<br><br>가져간 사람이 있으면 그 사람 값도 매긴다.<br>한 줄이 채워졌다.` },
      good:`들었다가 도로 놓았다.<br><br>무겁다. 종이치고는 말이 안 되게 무겁다.<br>무거운 건 안 가져간다. 도적의 기본이다.<br><br>대신 한 장만 찢어 왔다.`, flag:'tornPage' }
  ] }
);

epicSlot('forest', 'thief').push(
{ title:'검은 숲 — 나무의 구멍',
  text:`나무 줄기에 구멍이 있다.<br><br>
    짐승이 판 것이 아니다. 가장자리가 매끈하다.<br>
    누가 파서 뭔가 넣어 두는 자리다.<br><br>
    도적은 이런 자리를 안다. 자기도 쓰니까.`,
  opts:[
    { l:'① 꺼낸다.', dc:12, p:650,
      good:`손을 넣었다. 천에 싼 것이 있다.<br><br>꺼내 펴 보니 칼이다. 작다. 잘 갈려 있다.<br>숨겨 둔 사람은 다시 안 왔을 것이다.<br><br>챙겼다. 도적의 물건은 도적이 쓴다.`, flag:'hollowKnife',
      bad:`손을 넣자 안쪽이 오므라든다.<br><br>나무가 아니다.<br>급히 뺐다. 손등이 긁혔다.`, poll:8 },
    { l:'② 이쪽 물건을 넣어 둔다.', dc:11, kind:'hide', p:600,
      good:`반입품 하나를 천에 싸서 넣었다.<br><br>나갈 때 찾아가면 된다. 잃어도 아쉽지 않은 것으로.<br>도적은 늘 둘로 나눠 둔다.<br><br>나무에 표시를 하나 새겼다.`, flag:'stashedOwn',
      bad:`넣는데 구멍이 좁아진다.<br><br>손은 빼냈다. 물건은 못 뺐다.<br>그 물건은 포기했다.`, poll:7 }
  ] }
);

epicSlot('temple', 'thief').push(
{ title:'신전 — 제단 아래의 틈',
  text:`제단 돌 사이가 벌어져 있다.<br><br>
    도적은 제단을 볼 때 위가 아니라 아래를 본다.<br>
    값나가는 건 늘 아래에 있다.<br><br>
    틈으로 빛이 새어 나온다.`,
  opts:[
    { l:'① 벌려서 본다.', dc:13, kind:'break', p:700,
      good:`정을 끼워 조금 벌렸다.<br><br>안쪽에 초가 하나 더 있다. 스물넷째다.<br>이건 꺼져 있다.<br><br>꺼진 초만 여기 있는 이유는 모르겠다. 도로 닫았다.`, flag:'darkCandle',
      bad:`벌리는데 돌이 도로 붙는다.<br><br>정을 끼운 채로 붙는다.<br>정을 잃었다.`, poll:8 },
    { l:'② 틈으로 손을 넣는다.', dc:12, p:650,
      doom:{ title:'제단 아래', what:'팔이 끼었습니다', dc:13, sec:65,
        text:`팔을 넣었다. 어깨까지.<br><br>안이 넓다. 제단보다 넓다.<br>손끝에 뭔가 닿는다. 따뜻하다.<br><br>빼려는데 돌이 내려앉는다.<br>벌어져 있던 게 닫히는 중이다. 처음부터 닫히려던 틈이었다.`,
        dieText:`제단 아래에 손을 넣는 건 도적도 안 하는 일이다.<br><br>안 하는 데는 이유가 있고,<br>이유를 확인하면 늦다.` },
      good:`손끝만 넣었다가 뺐다.<br><br>안이 따뜻하다. 돌 안이 따뜻할 이유가 없다.<br>안 넣었다.<br><br>도적은 따뜻한 틈에 손을 안 넣는다.`, flag:'warmAltar' }
  ] }
);

epicSlot('ruin', 'thief').push(
{ title:'폐허 — 천장의 자국',
  text:`회랑 천장에 스물넷 줄이 있다.<br><br>
    맨 윗줄이 비어 있다.<br>
    도적은 비어 있는 자리를 본다. 채울 수 있으니까.<br><br>
    다만 채우려면 올라가야 한다.`,
  opts:[
    { l:'① 기둥을 타고 올라간다.', dc:13, kind:'evade', p:700,
      good:`기둥을 타고 올라 천장에 손이 닿았다.<br><br>줄이 새겨진 게 아니라 긁힌 것이다. 손톱으로.<br>스물셋 줄 전부.<br><br>맨 윗줄 자리에 손을 대 봤다. 아직 비어 있다.<br>긁지 않고 내려왔다.`, flag:'ceilingMarks' },
    { l:'② 아래에서 세기만 한다.', dc:10, p:450,
      good:`올려다보고 세었다. 스물넷 자리에 스물셋 줄.<br><br>세고 나서 물러났다.<br>도적은 세는 것과 채우는 것을 구분한다.`, flag:'countedRows',
      bad:`세는데 목이 아프다.<br><br>오래 올려다봤다. 생각보다 오래.<br>고개를 내리니 줄이 하나 더 있었다.`, poll:8 }
  ] }
);

epicSlot('grave', 'thief').push(
{ title:'묘지 — 관리소 안',
  text:`관리소 안에 도구가 가지런하다.<br><br>
    삽, 낫, 붓. 쓰던 사람 자리에.<br>
    도적은 가지런한 걸 보면 주인이 곧 온다고 읽는다.<br><br>
    그런데 먼지가 앉아 있다.`,
  opts:[
    { l:'① 도구를 하나 가져간다.', dc:12, p:650,
      doom:{ title:'가져간 도구', what:'자리를 넘겨받았습니다', dc:14, sec:70,
        text:`붓을 하나 집었다. 제일 작은 것으로.<br><br>손에 맞는다. 너무 맞는다.<br>쥐는 법을 아는 손처럼 저절로 잡힌다.<br><br>내려놓으려는데 안 놓인다.<br>앞사람이 쥐던 방식으로 쥐고 있다. 이제 이쪽이 앞사람이다.`,
        dieText:`가지런한 도구는 쓸 사람을 기다린다.<br><br>집는 순간 쓸 사람이 된다.<br>먼지가 앉은 이유를 알겠다. 오래 기다렸다.` },
      good:`집었다가 도로 놓았다.<br><br>손에 너무 맞는 게 이상해서 놓았다.<br>이상한 건 안 가져간다.<br><br>먼지 자국이 흐트러졌다. 손으로 다시 덮었다.`, flag:'putBackTool' },
    { l:'② 장부만 본다.', dc:12, kind:'gaze', p:650,
      good:`벽에 걸린 장부를 넘겼다.<br><br>손질한 날짜가 적혀 있다. 빠짐없이.<br>마지막 날짜가 오늘이다.<br><br>먼지는 앉았는데 날짜는 오늘이다.`, flag:'shedLedger',
      bad:`넘기는데 다음 장이 오늘 이후다.<br><br>내일, 모레, 그다음.<br>전부 적혀 있다.`, poll:9 }
  ] }
);

epicSlot('lake', 'thief').push(
{ title:'거울 호수 — 물가에 놓인 것',
  text:`물가에 신발이 가지런히 놓여 있다.<br><br>
    벗어 놓은 것이다. 도적은 벗어 놓은 신발을 안 가져간다.<br>
    주인이 근처에 있다는 뜻이니까.<br><br>
    근처를 둘러봐도 아무도 없다.`,
  opts:[
    { l:'① 신발을 본다.', dc:12, kind:'sense', p:650,
      good:`크기를 봤다. 이쪽 것과 같다.<br><br>안쪽이 젖어 있다. 신은 채로 물에 들어갔다 나온 것이다.<br>나왔는데 신발만 여기 있다.<br><br>안 건드렸다.`, flag:'wetShoes',
      bad:`보다 보니 신발이 이쪽을 향해 놓여 있다.<br><br>아까는 물 쪽이었다.<br>물러났다.`, poll:8 },
    { l:'② 신어 본다.', dc:14, p:750,
      doom:{ title:'신은 신발', what:'물 쪽으로 걷고 있습니다', dc:14, sec:70,
        text:`발을 넣었다. 맞는다.<br><br>젖은 게 따뜻하다. 방금까지 누가 신고 있었다.<br>한 걸음 뗐다. 물 쪽이다.<br><br>돌리려는데 발이 안 돌아간다.<br>신발이 길을 안다. 가던 길이 있었다.`,
        dieText:`물가에 신발이 가지런히 놓였다.<br><br>안쪽이 아직 따뜻하다.<br>다음에 오는 사람이 신어 볼 것이다.` },
      good:`발을 대 보고 뺐다.<br><br>맞는 게 이상해서 뺐다.<br>남의 신발이 맞으면 그건 남의 것이 아니다.<br><br>도적은 그런 걸 안 신는다.`, flag:'didntWear' }
  ] }
);

epicSlot('tower', 'thief').push(
{ title:'탑 — 계단 아래에 낀 것',
  text:`계단 틈에 뭔가 끼어 있다.<br><br>
    떨어뜨린 것이다. 올라가던 사람이.<br>
    도적은 떨어진 것부터 줍는다. 주인이 안 찾으니까.<br><br>
    다만 주인이 아직 위에 있을 수도 있다.`,
  opts:[
    { l:'① 빼낸다.', dc:11, p:550,
      good:`손가락으로 집어 뺐다. 반지다.<br><br>안쪽에 글자가 새겨져 있다. 이름 같다.<br>읽을 수 없는 글자다.<br><br>주머니에 넣었다. 읽을 수 없으면 주인도 없는 셈이다.`, flag:'stairRing',
      bad:`빼내는데 더 깊이 들어간다.<br><br>밀어 넣은 게 아니라 안쪽이 당긴다.<br>손을 뗐다.`, poll:7 },
    { l:'② 위를 먼저 본다.', dc:12, kind:'sense', p:600,
      good:`고개를 들어 위를 봤다.<br><br>계단이 굽어서 안 보인다. 다만 소리가 난다.<br>내려오는 소리가 아니라 올라가는 소리다.<br><br>주운 뒤에 올라가기로 했다. 순서가 중요하다.`, flag:'lookedUp',
      bad:`올려다보는데 위에서도 내려다본다.<br><br>얼굴은 안 보인다. 그림자만 움직인다.<br>주우려던 걸 그만뒀다.`, poll:8 }
  ] }
);

epicSlot('village', 'thief').push(
{ title:'빈 마을 — 밥상 위',
  text:`밥상이 차려져 있다.<br><br>
    수저가 놓여 있고 김이 오른다.<br>
    도적은 밥상을 안 건드린다. 먹는 것에 손대면 표가 나니까.<br><br>
    다만 수저가 은이다.`,
  opts:[
    { l:'① 수저를 가져간다.', dc:13, p:700,
      doom:{ title:'가져간 수저', what:'앉게 됐습니다', dc:14, sec:70,
        text:`은수저를 챙겼다. 스물셋 집에서 하나씩.<br><br>마지막 집에서 집는 순간, 손이 상 위에 놓인다.<br>수저를 쥔 채로. 앉는 자세로.<br><br>밥에서 김이 오른다. 아직 따뜻하다.<br>먹으면 안 되는데 손이 움직인다.`,
        dieText:`차려진 상에는 먹을 사람이 있다.<br><br>스물셋 집에 스물셋이 앉아 있었고,<br>수저를 가져간 쪽이 스물넷째가 됐다.` },
      good:`세 집에서만 가져왔다.<br><br>더 가면 안 될 것 같아서 멈췄다.<br>도적은 멈추는 지점을 안다. 아는 도적만 오래 한다.<br><br>주머니에서 부딪는 소리가 났다. 천으로 쌌다.`, flag:'threeSpoons' },
    { l:'② 김을 확인한다.', dc:12, kind:'sense', p:650,
      good:`손을 대 봤다. 따뜻하다.<br><br>다만 김이 위로 안 간다. 옆으로 퍼진다.<br>바람이 없는데.<br><br>먹는 것이 아니라 보여 주는 것이다. 안 건드렸다.`, flag:'sidewaysSteam',
      bad:`손을 대자 김이 손을 감는다.<br><br>따뜻한데 붙는다.<br>털었다. 잘 안 털렸다.`, poll:8 }
  ] }
);
;

// ---------- epic-thief-3.js ----------
// ==========================================
// ★ 도적 확장 3/3 — 동료 5 · 미니게임 5
// index.html 에서 epic-thief-2.js 다음에 불러온다
// ==========================================

epicSlot('castle', 'thief').push(
{ title:'성 — 두 사람이 필요한 자물쇠',
  text:`문에 자물쇠가 둘이다.<br><br>
    떨어져 있다. 한 사람이 둘 다 닿을 수 없는 거리다.<br>
    동시에 돌려야 열린다.<br><br>
    도적 둘을 상정하고 만든 문이다.`,
  opts:[
    { l:'① 동료와 동시에 돌린다.', co:'sync',
      coOpt:{ ask:'자물쇠가 둘입니다. 반대쪽을 맡아 주십시오.', sec:60, p:1000,
        text:`혼자서는 못 연다.`,
        doneText:`셋을 세고 같이 돌렸다.<br><br>딸깍. 한 소리로 났다.<br>따로 났으면 안 열렸을 것이다.<br><br>안쪽은 좁은 방이다. 상자 하나가 놓여 있다.<br>둘이 열었으니 둘이 나눴다.`,
        failText:`한쪽만 돌렸다.<br><br>돌아가다 멎는다. 반대쪽이 안 돌았으니까.<br>손을 떼자 원래대로 돌아갔다.` },
      good:`열었다.`, bad:`못 열었다.`, flag:'twinLock' },
    { l:'② 한쪽만 부순다.', dc:14, kind:'break', p:750,
      doom:{ title:'부순 자물쇠', what:'문이 반대로 열렸습니다', dc:14, sec:65,
        text:`한쪽을 정으로 쳐서 부쉈다.<br><br>문이 열린다. 다만 이쪽으로 열린다.<br>밀어 여는 문인데 당겨진다.<br><br>안에 있던 것이 나오는 중이다.<br>둘이 동시에 돌려야 하는 문은, 둘이 있어야 막을 수 있는 문이기도 하다.`,
        dieText:`자물쇠가 둘인 문은 안쪽이 위험한 문이다.<br><br>혼자 연 도적은 혼자 감당한다.` },
      good:`부쉈다. 문이 삐걱이며 조금 열린다.<br><br>손가락 하나 들어갈 틈이다. 그 이상은 안 열린다.<br>들여다봤다. 안이 비어 있다.<br><br>비어 있는데 자물쇠가 둘이었다.`, flag:'brokeOneLock' }
  ] },

{ title:'성 — 높은 창',
  text:`창이 높다.<br><br>
    혼자서는 안 닿는다. 도적은 이럴 때 받침을 찾는다.<br>
    받칠 만한 게 없다.<br><br>
    사람은 있다.`,
  opts:[
    { l:'① 동료를 밟고 올라간다.', co:'handoff',
      coOpt:{ ask:'창이 높습니다. 어깨를 빌려 주십시오.', sec:55, p:900,
        text:`밟고 올라가면 닿는다.`,
        doneText:`어깨를 밟고 올라갔다.<br><br>창턱에 손이 닿는다. 몸을 끌어올렸다.<br>안쪽에서 문을 열어 줬다.<br><br>밟힌 쪽이 어깨를 문지른다. 미안하다고는 안 했다.<br>도적끼리는 그런 말을 안 한다.`,
        failText:`혼자 뛰어 봤다. 안 닿는다.<br><br>세 번 뛰고 그만뒀다.<br>창은 그대로 높다.` },
      good:`올라갔다.`, bad:`못 올라갔다.`, flag:'boostedUp' }
  ] }
);

epicSlot('market', 'thief').push(
{ title:'장터 — 맞바꾼다',
  text:`가져온 것 중에 못 쓰는 게 있다.<br><br>
    남이 보면 값나가는 것일 수도 있다.<br>
    도적끼리는 바꾼다. 팔지 않고.<br><br>
    파는 순간 기록이 남으니까.`,
  opts:[
    { l:'① 동료와 바꾼다.', co:'handoff',
      coOpt:{ ask:'쓸모없는 게 하나 있습니다. 바꾸시겠습니까.', sec:60, p:900,
        text:`서로 안 쓰는 것이 서로에게는 쓸모가 있다.`,
        doneText:`꺼내 보였다. 저쪽도 꺼냈다.<br><br>둘 다 상대 것이 더 나아 보였다.<br>바꿨다. 바꾸고 나니 둘 다 자기 것이 나았던 것 같다.<br><br>그래도 안 물렀다. 도적끼리 무르는 법은 없다.`,
        failText:`꺼내 들고 한참 서 있었다.<br><br>바꿔 줄 사람이 없다.<br>도로 넣었다.` },
      good:`바꿨다.`, bad:`그대로다.`, flag:'swapped' },
    { l:'② 그냥 판다.', dc:11, p:500,
      good:`좌판에 넘겼다. 값을 후하게 쳐 준다.<br><br>후한 게 이상하다. 다만 받았다.<br>받고 나서 주인 얼굴을 봤다. 고개를 숙이고 있었다.`, flag:'soldJunk',
      bad:`넘기려는데 주인이 안 받는다.<br><br>손을 젓는다. 못 판다는 뜻이다.<br>도로 넣었다.`, poll:7 }
  ] },

{ title:'장터 — 셈이 맞는가',
  text:`좌판 주인이 거스름돈을 센다.<br><br>
    세는 게 느리다. 일부러 느린 것 같기도 하다.<br>
    도적은 같이 센다. 속으로.<br><br>
    한 푼이라도 어긋나면 안다.`,
  opts:[
    { l:'① 같이 센다.', mini:'beat', miniOpt:{ p:750, total:10, gap:820 },
      good:`열 번. 박자를 놓치지 않았다.<br><br>세 푼이 모자란다. 주인 손이 세 번 멈췄었다.<br>말없이 손을 내밀었다.<br><br>주인이 세 푼을 더 놓는다. 고개는 계속 숙인 채로.`, flag:'countedChange',
      bad:`중간에 놓쳤다.<br><br>다시 세려는데 이미 다 셌다고 한다.<br>몇 푼이 어디로 갔는지 모르겠다.` },
    { l:'② 세지 않고 받는다.', dc:10, p:450,
      good:`그냥 받아 넣었다.<br><br>세면 시간이 걸리고, 시간이 걸리면 얼굴이 기억된다.<br>도적은 셈보다 시간을 아낀다.`, flag:'tookQuick',
      bad:`받아서 나오는데 손이 무겁다.<br><br>세어 보니 받은 것보다 많다.<br>많은 것도 이상하다.`, poll:7 }
  ] }
);

epicSlot('ruin', 'thief').push(
{ title:'폐허 — 들어 올려야 하는 것',
  text:`석판이 하나 헐겁다.<br><br>
    혼자 들면 기울고, 기울면 아래가 무너진다.<br>
    양쪽에서 같이 들어야 수평으로 뜬다.<br><br>
    도적 일에도 두 사람이 필요한 게 있다.`,
  opts:[
    { l:'① 동료와 양쪽에서 든다.', co:'sync',
      coOpt:{ ask:'석판을 들어야 합니다. 반대쪽을 잡아 주십시오.', sec:60, p:1000,
        text:`한쪽만 들면 기운다.`,
        doneText:`하나 둘에 같이 들었다.<br><br>수평으로 떴다. 아래가 안 무너졌다.<br>밑에 상자가 있다. 둘이 같이 봤다.<br><br>안에 기록이 있다. 이름과 날짜.<br>한 장씩 나눠 가졌다.`,
        failText:`혼자 들었다. 기울었다.<br><br>아래가 주저앉는 소리가 났다.<br>손을 떼고 물러났다. 먼지가 오래 가라앉지 않았다.` },
      good:`들어 올렸다.`, bad:`무너뜨렸다.`, flag:'liftedSlab' },
    { l:'② 두드려 빈 곳을 찾는다.', mini:'beat', miniOpt:{ p:750, total:12, gap:700 },
      good:`열두 번 두드렸다.<br><br>세 번째와 아홉 번째가 비었다.<br>세 번째 아래는 흙이고, 아홉 번째 아래는 공간이다.<br><br>도적은 소리로 아래를 읽는다. 배운 것 중에 제일 쓸모 있다.`, flag:'tappedFloor',
      bad:`박자가 흐트러졌다.<br><br>어디가 비었는지 모르겠다.<br>아래에서 같은 박자로 두드린다.` }
  ] }
);

epicSlot('gate', 'thief').push(
{ title:'성문 — 둘이 넘는다',
  text:`아치가 무너져 반쯤 막혔다.<br><br>
    틈이 있다. 좁다. 몸을 빼면서 지나야 한다.<br>
    혼자 끼면 아무도 못 뺀다.<br><br>
    도적은 끼어 본 적이 있는 사람이다.`,
  opts:[
    { l:'① 동료가 뒤에서 민다.', co:'call',
      coOpt:{ ask:'틈이 좁습니다. 뒤에서 밀어 주십시오.', sec:55, p:900,
        text:`혼자 들어가면 끼었을 때 못 나온다.`,
        doneText:`먼저 들어갔다. 어깨가 걸렸다.<br><br>뒤에서 민다. 세게.<br>긁히면서 빠져나갔다. 옷이 찢어졌다.<br><br>반대쪽에서 손을 넣어 저쪽도 당겼다.<br>둘 다 지나왔다. 둘 다 긁혔다.`,
        failText:`혼자 들어갔다. 반쯤 들어가서 멈췄다.<br><br>뒤로 물러났다. 옷깃이 걸려 찢어졌다.<br>다른 길로 돌았다.` },
      good:`지나왔다.`, bad:`돌아갔다.`, flag:'squeezedPair' }
  ] }
);

epicSlot('tower', 'thief').push(
{ title:'탑 — 열리지 않는 상자',
  text:`관측대에 상자가 하나 더 있다.<br><br>
    잠겨 있다. 자물쇠가 아니라 짜맞춤이다.<br>
    밀고 돌리고 당기는 순서가 있다.<br><br>
    도적이 제일 싫어하는 종류다. 순서를 모르면 못 연다.`,
  opts:[
    { l:'① 순서를 맞춰 본다.', mini:'star', miniOpt:{ p:800, n:6, sec:17 },
      good:`여섯 번. 순서가 맞았다.<br><br>마지막에 소리가 났다. 안에서 무언가 풀리는 소리.<br>뚜껑이 들린다.<br><br>안에 종이 한 장. 별자리와 빠진 자리가 그려져 있다.`, flag:'puzzleBox',
      bad:`순서가 틀렸다.<br><br>상자가 한 번 떨린다. 안에서 다시 잠기는 소리.<br>처음보다 단단해졌다.` },
    { l:'② 부순다.', dc:14, kind:'break', p:750,
      good:`모서리를 쳐서 벌렸다.<br><br>도적답지 않은 방법이다. 다만 열렸다.<br>안에 종이가 있다. 찢어졌다. 절반만 읽힌다.<br><br>부수면 이렇게 된다. 알면서도 부순다.`, flag:'smashedBox',
      bad:`쳤는데 안 깨진다.<br><br>손목만 울렸다. 상자가 더 단단해 보인다.<br>세 번 치고 그만뒀다.`, poll:8 }
  ] }
);

epicSlot('forest', 'thief').push(
{ title:'검은 숲 — 덫을 피해 간다',
  text:`덫이 놓여 있다.<br><br>
    밀렵꾼이 놓은 것이다. 도적은 덫을 잘 본다.<br>
    보는 것과 피하는 것은 다르다.<br><br>
    발을 놓을 자리가 정해져 있다.`,
  opts:[
    { l:'① 자리를 짚어 가며 지난다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`일곱 자리. 순서대로 밟았다.<br><br>한 번도 안 울렸다.<br>지나와서 돌아보니 덫이 그대로다.<br><br>건드리지 않고 지나는 게 제일 좋다.`, flag:'wovePast',
      bad:`네 번째에서 어긋났다.<br><br>덫이 닫히는 소리가 났다. 발은 빼냈다.<br>소리는 이미 났다.` },
    { l:'② 덫을 훔친다.', dc:13, kind:'hide', p:700,
      good:`잠가서 하나 챙겼다.<br><br>도적은 덫도 훔친다. 쇠는 팔리니까.<br>나머지는 그대로 뒀다.<br><br>하나만 가져가면 놓은 사람도 모른다.`, flag:'stoleTrap',
      bad:`잠그는데 손이 미끄러졌다.<br><br>닫혔다. 손가락은 아슬하게 피했다.<br>놓고 물러났다.`, poll:8 }
  ] }
);

epicSlot('grave', 'thief').push(
{ title:'묘지 — 둘이 파야 하는 것',
  text:`봉분 하나가 크다.<br><br>
    혼자 파면 한나절이고, 파는 동안 뒤를 못 본다.<br>
    도적은 뒤를 못 보는 시간을 제일 싫어한다.<br><br>
    둘이면 하나가 파고 하나가 본다.`,
  opts:[
    { l:'① 동료에게 망을 맡긴다.', co:'standin',
      coOpt:{ ask:'파는 동안 뒤를 봐 주십시오.', sec:60, p:950,
        text:`파는 쪽은 뒤를 못 본다.`,
        doneText:`동료가 등 뒤에 섰다.<br><br>파는 내내 두 번 소리를 냈다. 두 번 다 멈췄다.<br>멈춘 덕에 두 번 안 들켰다.<br><br>나온 것은 별것 아니었다. 다만 안 들킨 게 남았다.<br>몫은 반씩 나눴다.`,
        failText:`혼자 팠다.<br><br>파는 내내 뒤가 신경 쓰였다. 세 번 돌아봤다.<br>세 번 다 아무것도 없었다. 그게 더 신경 쓰였다.<br><br>얕게 파고 덮었다.` },
      good:`파냈다.`, bad:`덮었다.`, flag:'gravePair' }
  ] }
);

epicSlot('village', 'thief').push(
{ title:'빈 마을 — 무게를 맞춘다',
  text:`집 하나에 저울이 있다.<br><br>
    양쪽에 물건이 올라가 있다. 기울어 있다.<br>
    맞추면 뭔가 열린다는 표시가 있다.<br><br>
    도적은 이런 장치를 여러 번 봤다.`,
  opts:[
    { l:'① 무게를 맞춘다.', mini:'scale', miniOpt:{ p:800, target:22, pool:[3,4,6,7,9,12] },
      good:`수평이 됐다.<br><br>바닥에서 소리가 난다. 마루 한 장이 들린다.<br>아래에 자루가 있다. 무겁다.<br><br>열어 보니 동전이다. 오래된 것들. 챙겼다.`, flag:'balancedFloor',
      bad:`기울었다.<br><br>마루가 반쯤 들렸다가 도로 닫힌다.<br>손가락이 낄 뻔했다.` },
    { l:'② 저울을 통째로 가져간다.', dc:12, p:650,
      good:`들었다. 무겁다. 다만 들린다.<br><br>가져가다 생각을 바꿨다. 도로 놓았다.<br>무거운 건 안 가져간다.<br><br>대신 추 하나만 챙겼다.`, flag:'tookOneWeight',
      bad:`드는 순간 양쪽 물건이 쏟아진다.<br><br>소리가 크다. 집 밖까지 갔을 것이다.<br>놓고 나왔다.`, poll:8 }
  ] }
);

epicSlot('lake', 'thief').push(
{ title:'거울 호수 — 둘이 봐야 보이는 것',
  text:`수면에 글자가 있다.<br><br>
    한쪽에서 보면 절반만 읽힌다.<br>
    반대편에서 동시에 봐야 전부 읽힌다.<br><br>
    혼자 양쪽에 설 수는 없다.`,
  opts:[
    { l:'① 동료를 반대편에 세운다.', co:'witness',
      coOpt:{ ask:'호수 반대편에서 같이 읽어 주십시오.', sec:65, p:1000,
        text:`양쪽에서 봐야 전부 읽힌다.`,
        doneText:`동료가 건너편에 섰다.<br><br>둘이 동시에 내려다봤다. 글자가 이어진다.<br><span style="color:#d4af37;">"가져간 것은 돌아온다. 늦게, 다른 모양으로."</span><br><br>둘 다 읽었다. 둘 다 아무 말도 안 했다.<br>도적에게는 반갑지 않은 문장이다.`,
        failText:`혼자 읽었다. 절반만 읽힌다.<br><br><span style="color:#888;">"가져간 것은..."</span><br>뒤가 없다. 뒤가 중요한 문장인데.` },
      good:`전부 읽었다.`, bad:`절반만 읽었다.`, flag:'readBothSides' }
  ] }
);

epicSlot('road', 'thief').push(
{ title:'끊긴 길 — 줄을 잇는다',
  text:`끊긴 자리에 줄을 걸 수 있다.<br><br>
    한쪽 끝을 던져 반대편에 걸어야 한다.<br>
    도적은 줄을 잘 쓴다. 다만 던지는 건 다른 일이다.<br><br>
    겨눠서 던져야 걸린다.`,
  opts:[
    { l:'① 겨눠 던진다.', mini:'aim', miniOpt:{ p:800, shots:3, need:2 },
      good:`두 번 만에 걸렸다.<br><br>당겨 보니 단단하다. 매듭이 물었다.<br>줄을 타고 건넜다.<br><br>건너서 줄을 풀어 챙겼다. 도적은 줄을 두고 가지 않는다.`, flag:'ropeAcross',
      bad:`세 번 다 빗나갔다.<br><br>줄이 안개로 떨어진다. 당겨도 안 온다.<br>줄을 잃었다.` },
    { l:'② 발자국만 밟고 건넌다.', dc:13, kind:'evade', p:700,
      good:`앞서 간 자국을 정확히 밟았다.<br><br>안 빠진다. 다져진 자리다.<br>건너서 돌아보니 자국이 둘이 됐다.<br><br>다음 사람이 더 쉬울 것이다.`, flag:'steppedPrints',
      bad:`한 걸음 어긋났다.<br><br>무릎까지 빠졌다. 빼내는 데 힘이 들었다.<br>신발 한 짝이 안 나왔다.`, poll:9 }
  ] }
);

epicSlot('temple', 'thief').push(
{ title:'신전 — 아무것도 안 가져간 날',
  text:`나가려는데 손이 비어 있다.<br><br>
    신전에서 아무것도 안 가져왔다.<br>
    도적에게는 드문 일이다.<br><br>
    드문 일을 한 날은 기억해 둔다.`,
  opts:[
    { l:'① 그대로 나간다.', dc:10, p:500,
      good:`빈손으로 나왔다.<br><br>문턱을 넘을 때 촛불이 한 번 흔들렸다.<br>바람은 없었다.<br><br>배웅받은 것 같기도 하다. 기분 탓일 것이다.`, flag:'emptyHanded' },
    { l:'② 뭐라도 두고 간다.', dc:12, kind:'bond', p:650,
      good:`주머니에서 하나 꺼내 제단에 놓았다.<br><br>가져온 것이 아니라 두고 가는 것이다. 처음이다.<br>놓고 나서 한참 서 있었다.<br><br>나올 때 초가 하나 더 밝았다. 세어 보지는 않았다.`, flag:'leftOffering',
      bad:`놓으려는데 손이 안 펴진다.<br><br>도적의 손은 놓는 법을 늦게 배운다.<br>결국 도로 넣고 나왔다.`, poll:7 }
  ] }
);
;

