epicSlot('market', 'jester').push(
{ title:'장터 — 물건을 돌린다',
  text:`좌판에서 공 세 개를 빌렸다.<br><br>
    빌렸다고 하기에는 말없이 가져왔다.<br>
    광대는 던지고 받는 것으로 밥을 먹는다.<br><br>
    셋을 동시에 공중에 두려면 박자가 맞아야 한다.`,
  opts:[
    { l:'① 돌린다.', mini:'beat', miniOpt:{ p:800, total:12, gap:620 },
      good:`열두 번. 하나도 안 떨어뜨렸다.<br><br>손보다 눈이 먼저 간다. 그게 요령이다.<br>다 돌리고 나서 좌판에 도로 놓았다.<br><br>주인이 하나를 밀어 준다. 가지라는 뜻이었다.`, flag:'juggled',
      bad:`여덟 번째에서 하나가 떨어졌다.<br><br>굴러간다. 좌판 아래로.<br>줍지 않았다. 주우려면 천을 들춰야 해서.` },
    { l:'② 하나만 높이 던진다.', dc:12, kind:'sense', p:650,
      good:`하나를 위로 던졌다. 높이.<br><br>안 떨어진다. 한참 있다 떨어진다.<br>세어 보니 여덟까지 셌다.<br><br>여기는 위가 높다. 보이는 것보다.`, flag:'highThrow',
      bad:`던진 것이 안 돌아온다.<br><br>올려다봐도 안 보인다.<br>공이 하나 줄었다.`, poll:7 }
  ] },

{ title:'장터 — 흉내를 되돌려 준다',
  text:`좌판 주인이 이쪽을 따라 한다.<br><br>
    전에도 그랬다. 이번엔 더 정확하다.<br>
    광대는 흉내를 내는 쪽이지 당하는 쪽이 아니다.<br><br>
    되돌려 줄 방법이 있다.`,
  opts:[
    { l:'① 일부러 틀린 동작을 한다.', dc:13, kind:'evade', p:700,
      good:`팔을 들다 말았다. 어정쩡하게.<br><br>저쪽이 똑같이 어정쩡해진다.<br>틀린 것을 정확히 틀린다.<br><br>웃음이 났다. 웃으니 저쪽도 웃는다. 그건 못 따라 했다.`, flag:'fakeMove',
      bad:`틀리게 하려는데 몸이 제대로 한다.<br><br>평생 한 동작이라 그렇다.<br>저쪽이 정확히 따라 했다.`, poll:7 },
    { l:'② 아무 동작도 안 한다.', dc:11, p:550,
      good:`가만히 섰다. 저쪽도 섰다.<br><br>오래 섰다. 먼저 움직인 건 저쪽이었다.<br>흉내 내는 쪽은 오래 못 참는다.<br><br>그걸 확인하고 나니 무섭지 않았다.`, flag:'stillLonger',
      bad:`가만히 섰는데 저쪽이 움직인다.<br><br>안 한 동작을 한다.<br>흉내가 아니었다.`, poll:8 }
  ] }
);

epicSlot('castle', 'jester').push(
{ title:'성 — 앉아 있던 자리',
  text:`맨 앞줄 가운데 의자가 눌려 있다.<br><br>
    오래 앉아 있던 자국이다.<br>
    광대는 객석을 잘 안다. 누가 어디 앉는지도.<br><br>
    가운데 앞줄은 제일 잘 보는 자리다.`,
  opts:[
    { l:'① 앉아 본다.', dc:13, p:700,
      doom:{ title:'앉은 자리', what:'일어설 수 없습니다', dc:14, sec:70,
        text:`앉았다. 무대가 잘 보인다.<br><br>여기서 보면 다 보이겠다 싶다. 실수도, 숨긴 것도.<br>편하다. 오래 앉을 만하다.<br><br>일어서려는데 다리가 안 펴진다.<br>보는 쪽이 되면 서는 법을 잊는다.`,
        dieText:`의자 스물셋이 스물넷이 됐다.<br><br>맨 앞줄 가운데가 채워졌고,<br>무대는 여전히 비어 있다.` },
      good:`앉았다가 곧 일어섰다.<br><br>무대가 잘 보인다. 잘 보이는 게 불편했다.<br>광대는 보는 쪽이 아니라 보이는 쪽이다.<br><br>일어서서 무대로 갔다.`, flag:'satBriefly' },
    { l:'② 의자를 무대 쪽으로 돌린다.', dc:12, kind:'break', p:650,
      good:`스물셋 개를 전부 돌려 놓았다. 등을 무대로.<br><br>객석이 아니게 됐다. 그냥 의자들이 됐다.<br>공연할 이유도 없어졌다.<br><br>그게 나았다. 여기서는.`, flag:'turnedSeats',
      bad:`돌리는데 도로 돌아온다.<br><br>스물셋 개가 천천히 제자리로.<br>세 개 돌리고 그만뒀다.`, poll:8 }
  ] },

{ title:'성 — 창고의 옷',
  text:`방 하나에 옷이 걸려 있다.<br><br>
    광대 옷이다. 색이 바랬고 방울이 달려 있다.<br>
    스물셋 벌이 나란히.<br><br>
    전부 다른 사람 치수다.`,
  opts:[
    { l:'① 치수를 맞춰 본다.', dc:12, kind:'sense', p:650,
      good:`하나씩 대 봤다. 스물둘은 안 맞는다.<br><br>스물셋째가 맞는다. 딱 맞는다.<br>이쪽 치수로 만든 옷이 여기 있다.<br><br>안 입었다. 입으면 안 될 것 같아서.`, flag:'fittingSuit',
      bad:`대 보는데 전부 맞는다.<br><br>스물셋 벌이 다 맞는다. 치수가 다른데.<br>손을 뗐다.`, poll:9 },
    { l:'② 방울만 떼어 온다.', dc:11, p:550,
      good:`옷마다 하나씩 떼었다. 스물셋 개.<br><br>주머니에 넣으니 소리가 크다. 천으로 쌌다.<br>쓸 데가 있을 것이다.<br><br>묘지 같은 데에.`, flag:'collectedBells',
      bad:`떼는데 옷이 흔들린다.<br><br>스물셋 벌이 동시에. 바람은 없다.<br>몇 개만 떼고 나왔다.`, poll:8 }
  ] }
);

epicSlot('temple', 'jester').push(
{ title:'신전 — 웃음이 새어 나온다',
  text:`참고 있는데 새어 나온다.<br><br>
    조용할수록 심하다. 광대의 병이다.<br>
    참으면 참을수록 커진다.<br><br>
    한 번 터지면 못 멈춘다.`,
  opts:[
    { l:'① 밖으로 나가서 웃는다.', dc:12, kind:'evade', p:650,
      good:`서둘러 나왔다. 문턱을 넘자마자 터졌다.<br><br>한참 웃었다. 이유는 없다.<br>다 웃고 나니 개운했다.<br><br>안에서 웃지 않은 게 중요했다.`, flag:'laughedOutside',
      bad:`나가려는데 문이 멀다.<br><br>걸음마다 웃음이 커진다.<br>절반쯤에서 터졌다.`, poll:8 },
    { l:'② 그냥 웃는다.', dc:14, p:750,
      doom:{ title:'터진 웃음', what:'웃음이 멎지 않습니다', dc:14, sec:70,
        text:`터졌다. 크게.<br><br>신전이 울린다. 촛불이 전부 한쪽으로 기운다.<br>멈추려는데 안 멈춘다.<br><br>숨이 안 쉬어진다. 웃는데 숨이 안 쉬어진다.<br>스물셋 개의 촛불이 하나씩 꺼진다. 웃을 때마다.`,
        dieText:`광대는 웃기는 사람이지 웃는 사람이 아니다.<br><br>구분을 잃으면 멈추는 법도 잃는다.<br>초가 다 꺼졌다.` },
      good:`웃었다. 한 번, 짧게.<br><br>손으로 입을 막고 한 번만.<br>촛불이 한 번 흔들리고 멎었다.<br><br>한 번은 봐 주는 모양이다.`, flag:'laughedOnce' }
  ] }
);

epicSlot('grave', 'jester').push(
{ title:'묘지 — 방울을 단다',
  text:`가져온 방울이 스물셋 개다.<br><br>
    비석도 스물셋이다.<br>
    광대가 여기서 할 수 있는 게 그것뿐이다.<br><br>
    하나씩 놓아 주는 것.`,
  opts:[
    { l:'① 하나씩 놓는다.', dc:12, kind:'bond', p:700,
      good:`비석마다 하나씩 놓았다. 스물셋 개.<br><br>다 놓고 물러서니 동시에 울린다.<br>바람이 없는데 한 번.<br><br>그게 대답이라고 생각하기로 했다.`, flag:'bellsPlaced',
      bad:`놓는데 하나가 모자란다.<br><br>세어 보니 스물둘이다. 어디서 떨어뜨렸다.<br>마지막 비석만 비었다.`, poll:8 },
    { l:'② 다 걸어 두고 흔든다.', dc:13, p:700,
      doom:{ title:'울린 방울', what:'전부 일어났습니다', dc:14, sec:70,
        text:`비석마다 걸고 줄로 이었다.<br><br>줄을 당겼다. 스물셋 개가 한 번에 울린다.<br>크다. 생각보다 훨씬.<br><br>울림이 안 멎는다. 흙이 들썩인다.<br>방울 소리는 부르는 소리다. 몰랐던 것이 아니다. 잊고 있었다.`,
        dieText:`광대의 방울은 사람을 모으는 물건이다.<br><br>모을 것이 사람인지 아닌지는 안 따진다.<br>스물셋이 모였다.` },
      good:`걸어만 두고 안 흔들었다.<br><br>흔들면 소리가 난다. 소리는 부른다.<br>부르면 온다.<br><br>걸어 둔 채로 물러났다.`, flag:'hungSilent' }
  ] }
);

epicSlot('forest', 'jester').push(
{ title:'검은 숲 — 길을 잃은 척',
  text:`광대는 길 잃는 연기를 잘한다.<br><br>
    두리번거리고 같은 자리를 돌고 머리를 긁는다.<br>
    관객이 웃는다.<br><br>
    지금은 관객이 없고, 연기도 아니다.`,
  opts:[
    { l:'① 연기처럼 해 본다.', dc:12, p:650,
      good:`평소 하던 대로 했다. 크게 두리번거리고 머리를 긁었다.<br><br>하다 보니 진짜로 어느 쪽인지 알겠다.<br>몸이 기억하는 방향이 있었다.<br><br>연기가 진짜를 끌어냈다.`, flag:'actedLost',
      bad:`하다 보니 진짜로 헤맨다.<br><br>연기와 구분이 안 간다.<br>그만뒀다.`, poll:8 },
    { l:'② 나무에 표시를 남긴다.', dc:11, p:550,
      good:`나무마다 방울 무늬를 그렸다. 숯으로.<br><br>광대가 쓰는 표시다. 다른 광대가 보면 안다.<br>다른 광대가 올 일은 없겠지만.<br><br>그래도 그렸다.`, flag:'jesterMark',
      bad:`그린 것이 지워진다.<br><br>나무가 받지 않는다.<br>세 그루 하고 그만뒀다.`, poll:6 }
  ] }
);

epicSlot('lake', 'jester').push(
{ title:'거울 호수 — 물 위에서',
  text:`수면이 잔잔하다.<br><br>
    거울처럼. 딛고 설 수 있을 것 같기도 하다.<br>
    광대는 그런 생각을 실제로 해 보는 사람이다.<br><br>
    그래서 오래 못 사는 직업이다.`,
  opts:[
    { l:'① 발을 올려 본다.', dc:14, kind:'evade', p:800,
      doom:{ title:'물 위', what:'비친 쪽으로 끌려갑니다', dc:14, sec:70,
        text:`발끝을 댔다. 안 들어간다.<br><br>딛힌다. 진짜로 딛힌다.<br>한 걸음 나갔다. 비친 것도 한 걸음 왔다.<br><br>마주 보는 자세다. 가까워진다.<br>물 위에서는 만날 수밖에 없다. 물러설 데가 없으니까.`,
        dieText:`거울 위를 걷는 건 만나러 가는 것이다.<br><br>둘이 겹치면 하나가 남는다.<br>남은 쪽이 물가로 걸어 나왔다.` },
      good:`발끝을 댔다가 뗐다.<br><br>딛히는 게 이상해서 뗐다.<br>딛히면 안 되는 것이 딛히면 그건 함정이다.<br><br>줄 위에서 배운 것 중 하나다.`, flag:'testedWater' },
    { l:'② 수면에 재주를 보여 준다.', dc:12, kind:'bond', p:650,
      good:`물가에서 재주를 넘었다. 비친 쪽도 넘는다.<br><br>같이 넘으니 둘이 하는 공연 같다.<br>혼자 하는 것보다 나았다.<br><br>인사도 같이 했다.`, flag:'mirrorShow',
      bad:`넘는데 저쪽이 안 넘는다.<br><br>서서 보고 있다. 관객처럼.<br>그만뒀다.`, poll:8 }
  ] }
);

epicSlot('tower', 'jester').push(
{ title:'탑 — 아래를 안 본다',
  text:`꼭대기다.<br><br>
    광대는 높은 데서 아래를 안 본다. 배운 대로다.<br>
    보면 다리가 떨리고, 떨리면 떨어진다.<br><br>
    그런데 아래에서 소리가 난다.`,
  opts:[
    { l:'① 안 본다.', dc:12, kind:'evade', p:650,
      good:`고개를 안 돌렸다.<br><br>소리가 계속 난다. 이름을 부르는 것 같기도 하다.<br>안 봤다. 보면 지는 거라고 배웠다.<br><br>내려갈 때까지 한 번도 안 봤다.`, flag:'neverLooked',
      bad:`참다가 한 번 봤다.<br><br>아무도 없다. 다만 아래가 아까보다 가깝다.<br>다시 안 봤다.`, poll:8 },
    { l:'② 소리에 대답한다.', dc:13, kind:'bond', p:700,
      good:`아래를 안 보고 대답했다. 크게.<br><br><span style="color:#d4af37;">"올라와서 말하시오!"</span><br><br>소리가 멎는다. 올라오지는 않았다.<br>대답만으로 물러나는 것도 있다.`, flag:'answeredDown',
      bad:`대답하자 소리가 가까워진다.<br><br>아래가 아니라 옆에서 난다.<br>입을 다물었다.`, poll:9 }
  ] }
);

epicSlot('ruin', 'jester').push(
{ title:'폐허 — 무너지는 중에 하는 공연',
  text:`기둥이 흔들린다.<br><br>
    무너질 것 같다. 광대는 이럴 때 도망가지 않는다.<br>
    도망가는 것도 공연의 일부이기 때문이다.<br><br>
    다만 지금은 관객이 없다.`,
  opts:[
    { l:'① 넘어지는 척하며 빠져나간다.', dc:13, kind:'evade', p:700,
      good:`일부러 크게 넘어지면서 굴렀다.<br><br>구르는 방향이 출구 쪽이다. 계산한 것이다.<br>광대가 넘어지는 건 늘 계산이다.<br><br>기둥이 뒤에서 내려앉았다. 먼지 사이로 나왔다.`, flag:'rolledOut',
      bad:`구르다 벽에 부딪혔다.<br><br>계산이 틀렸다. 드문 일이다.<br>어깨가 아프다.`, poll:8 },
    { l:'② 기둥을 받친다.', dc:14, kind:'break', p:750,
      good:`어깨로 받쳤다. 무겁다.<br><br>버티는 동안 다른 길을 찾았다.<br>찾고 나서 놓았다. 뒤에서 무너졌다.<br><br>받치는 재주는 없는데 버텼다.`, flag:'heldPillar',
      bad:`받치다 밀렸다.<br><br>무게가 사람 하나로는 안 된다.<br>물러났다.`, poll:9 }
  ] }
);

epicSlot('village', 'jester').push(
{ title:'빈 마을 — 한 번 더 그린다',
  text:`벽 그림 앞이다.<br><br>
    전에 하나 더 그렸거나, 모자를 키웠거나.<br>
    다시 보니 그림이 늘어 있다.<br><br>
    그린 적 없는 것이 하나 더 있다.`,
  opts:[
    { l:'① 늘어난 것을 본다.', dc:13, kind:'gaze', p:700,
      good:`여섯 번째다. 다른 손으로 그렸다.<br><br>선이 서툴다. 아이 손이다.<br>모자 쓴 사람 옆에 붙어 있다.<br><br>그린 사람이 아직 있다는 뜻이다. 어딘가에.`, flag:'sixthFigure',
      bad:`여섯 번째가 이쪽을 보고 있다.<br><br>다른 다섯은 옆을 본다.<br>손을 뗐다.`, poll:9 },
    { l:'② 그림에 대고 공연한다.', dc:12, kind:'bond', p:650,
      good:`벽 앞에서 재주를 넘었다. 세 번.<br><br>그림은 그림이다. 안 움직인다.<br>그래도 했다. 끝나고 인사했다.<br><br>돌아설 때 등 뒤에서 숯 가루가 떨어지는 소리가 났다.`, flag:'showForWall',
      bad:`넘는 동안 그림이 커진다.<br><br>벽 전체가 된다.<br>그만두고 나왔다.`, poll:8 }
  ] }
);

epicSlot('road', 'jester').push(
{ title:'끊긴 길 — 모자를 건넨다',
  text:`길 끝에 누가 서 있다.<br><br>
    멀어서 얼굴은 안 보인다. 안개 저편이다.<br>
    광대는 처음 보는 사람에게 모자를 벗는다.<br><br>
    벗는 게 인사다.`,
  opts:[
    { l:'① 모자를 벗어 인사한다.', dc:12, kind:'bond', p:650,
      good:`모자를 벗고 허리를 굽혔다.<br><br>저쪽도 굽힌다. 같은 각도로.<br>인사가 오간 것이다.<br><br>고개를 드니 없다. 인사만 하고 갔다.`, flag:'bowedAcross',
      bad:`벗었는데 저쪽은 안 벗는다.<br><br>가만히 보고만 있다.<br>도로 썼다.`, poll:8 },
    { l:'② 모자를 던져 준다.', dc:13, p:700,
      doom:{ title:'던진 모자', what:'모자를 따라가고 있습니다', dc:13, sec:65,
        text:`모자를 던졌다. 안개를 넘어간다.<br><br>저쪽이 받는다. 쓴다. 잘 어울린다.<br>그리고 손짓한다. 오라는 뜻이다.<br><br>모자 없는 광대는 광대가 아니다.<br>찾으러 가야 한다. 발이 이미 움직이고 있다.`,
        dieText:`광대는 모자를 두고 가지 않는다.<br><br>모자가 있는 쪽으로 간다.<br>안개 저편에 광대가 하나 서 있다. 모자를 쓰고.` },
      good:`던지려다 손을 내렸다.<br><br>모자는 광대의 전부다. 던질 것이 아니다.<br>대신 손을 흔들었다.<br><br>저쪽도 흔들었다. 그걸로 끝냈다.`, flag:'keptHat' }
  ] }
);
;

