epicSlot('market', 'jester').push(
{ title:'장터 — 둘이 주고받는다',
  text:`공을 셋 이상 돌리려면 손이 모자란다.<br><br>
    둘이 마주 서서 주고받으면 여섯도 된다.<br>
    광대 공연은 원래 둘이 하는 것이 많다.<br><br>
    혼자 하는 쪽이 나중에 생긴 형태다.`,
  opts:[
    { l:'① 동료와 주고받는다.', co:'sync',
      coOpt:{ ask:'공을 주고받아 주십시오. 던지면 받으시면 됩니다.', sec:60, p:1000,
        text:`혼자서는 셋이 한계다.`,
        doneText:`마주 섰다. 하나씩 던지기 시작했다.<br><br>처음엔 어긋났다. 세 번쯤 떨어뜨리고 박자가 맞았다.<br>여섯 개가 둘 사이를 돈다.<br><br>좌판 주인들이 고개를 들었다. 스물셋 개가 동시에.<br>모자에 뭔가 들어 있었다. 둘이 나눴다.`,
        failText:`혼자 셋을 돌렸다.<br><br>셋은 셋이다. 나쁘지 않지만 여섯은 아니다.<br>모자는 비어 있었다.` },
      good:`여섯을 돌렸다.`, bad:`셋에서 멈췄다.`, flag:'duoJuggle' },
    { l:'② 값을 맞춰 물건을 빌린다.', mini:'scale', miniOpt:{ p:750, target:18, pool:[2,3,5,6,8,10] },
      good:`저울에 값을 맞춰 올렸다.<br><br>주인이 공 세 개를 밀어 준다. 빌려주는 것이다.<br>값을 치르니 빌리는 게 된다.<br><br>훔치는 것보다 마음이 편했다.`, flag:'borrowedBalls',
      bad:`기울었다.<br><br>주인이 손을 거둔다. 못 빌린다는 뜻이다.<br>다른 데서 구하기로 했다.` }
  ] }
);

epicSlot('castle', 'jester').push(
{ title:'성 — 둘이 서는 무대',
  text:`무대가 넓다.<br><br>
    혼자 서면 허전하다. 둘이면 채워진다.<br>
    광대 공연은 대개 둘이 한다.<br><br>
    한쪽이 웃기고 한쪽이 당한다.`,
  opts:[
    { l:'① 동료와 함께 선다.', co:'call',
      coOpt:{ ask:'무대가 있습니다. 같이 서 주십시오. 웃기는 건 제가 합니다.', sec:60, p:1000,
        text:`혼자 서는 무대는 허전하다.`,
        doneText:`둘이 섰다. 저쪽은 뭘 해야 할지 모른다.<br><br>그게 좋았다. 모르는 쪽이 있어야 웃긴다.<br>밀고 당기고 넘어뜨렸다. 저쪽은 영문을 모른다.<br><br>박수 소리가 났다. 한 사람 분이 아니었다.<br>세어 보지는 않았다.`,
        failText:`혼자 섰다.<br><br>혼자 하는 공연은 혼자 웃겨야 한다.<br>객석은 비어 있다. 끝까지 했다.` },
      good:`둘이 했다.`, bad:`혼자 했다.`, flag:'duoStage' },
    { l:'② 분장을 서로 해 준다.', co:'handoff',
      coOpt:{ ask:'분이 있습니다. 서로 발라 줍시다.', sec:55, p:900,
        text:`제 얼굴은 자기가 못 본다.`,
        doneText:`서로 발라 줬다.<br><br>남이 발라 주니 이상하다. 눈을 감고 있어야 한다.<br>다 되고 거울을 봤다. 낯선 얼굴이다.<br><br>둘 다 웃었다. 지워질 분이라는 걸 확인하고 나서.`,
        failText:`혼자 발랐다. 거울을 보며.<br><br>한쪽 눈가가 비뚤어졌다. 고칠 수 없었다.<br>보이지 않는 쪽이라서.` },
      good:`발라 줬다.`, bad:`혼자 발랐다.`, flag:'paintedEach' }
  ] }
);

epicSlot('ruin', 'jester').push(
{ title:'폐허 — 받쳐 주는 쪽',
  text:`천장이 낮은 자리가 있다.<br><br>
    지나가려면 한 사람이 들어 올려야 한다.<br>
    들어 올리는 쪽은 못 지나간다.<br><br>
    광대는 받쳐 주는 쪽을 자주 맡는다.`,
  opts:[
    { l:'① 동료에게 받쳐 달라고 한다.', co:'handoff',
      coOpt:{ ask:'천장이 낮습니다. 들어 주시면 제가 지나가서 다른 길을 찾겠습니다.', sec:60, p:950,
        text:`한쪽이 들면 한쪽이 지나간다.`,
        doneText:`동료가 어깨로 받쳤다.<br><br>기어서 지났다. 먼지가 많았다.<br>반대편에서 돌아 나와 다른 문을 열었다.<br><br>받친 쪽이 손을 털었다. 별말은 없었다.<br>광대는 받쳐 주는 쪽을 자주 맡아 봐서 안다.`,
        failText:`혼자 밀어 봤다. 안 들린다.<br><br>돌아서 다른 길로 갔다. 멀었다.` },
      good:`지나갔다.`, bad:`돌아갔다.`, flag:'liftedCeiling' },
    { l:'② 무대 자국을 순서대로 밟는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`여섯 자국. 순서대로 밟았다.<br><br>순서가 맞자 동작이 이어진다. 하나의 연기가 된다.<br>누가 여기서 했던 것이다.<br><br>마지막 자국에서 인사 자세가 나왔다. 저절로.`, flag:'traceDance',
      bad:`순서가 엉켰다.<br><br>동작이 안 이어진다. 그냥 밟고 다닌 게 됐다.<br>자국이 흐려졌다.` }
  ] }
);

epicSlot('road', 'jester').push(
{ title:'끊긴 길 — 줄을 잡아 준다',
  text:`줄을 걸면 건널 수 있다.<br><br>
    다만 한쪽을 사람이 잡고 있어야 팽팽해진다.<br>
    묶으면 느슨해지고, 느슨하면 못 탄다.<br><br>
    광대는 줄을 잡아 주는 사람이 필요하다.`,
  opts:[
    { l:'① 동료에게 줄을 맡긴다.', co:'sync',
      coOpt:{ ask:'줄 한쪽을 잡아 주십시오. 놓지만 마시면 됩니다.', sec:60, p:1000,
        text:`잡아 주는 사람이 있어야 탄다.`,
        doneText:`동료가 줄 끝을 잡고 버텼다.<br><br>발을 올렸다. 팽팽하다. 사람이 잡은 줄은 다르다.<br>묶인 줄보다 살아 있다.<br><br>건넜다. 건너서 돌아보니 아직 잡고 있었다.<br>놓으라고 손짓했다. 그제야 놓았다.`,
        failText:`줄을 바위에 묶고 탔다.<br><br>느슨하다. 세 걸음에서 내려왔다.<br>다른 길을 찾았다.` },
      good:`건넜다.`, bad:`못 건넜다.`, flag:'heldRope' },
    { l:'② 줄을 겨눠 던진다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`두 번 만에 걸렸다.<br><br>고리가 저쪽 말뚝에 물렸다.<br>당겨 보니 버틴다.<br><br>광대는 던지는 걸 잘한다. 받는 것도.`, flag:'threwRope',
      bad:`세 번 다 빗나갔다.<br><br>줄이 안개로 떨어진다. 당겨도 안 온다.<br>줄을 잃었다.` }
  ] }
);

epicSlot('village', 'jester').push(
{ title:'빈 마을 — 둘이 하는 놀이',
  text:`마당에 금이 그어져 있다.<br><br>
    아이들이 하던 놀이 자국이다.<br>
    둘이 해야 하는 놀이다. 혼자는 안 된다.<br><br>
    광대는 규칙을 안다. 어디서 배웠는지는 모르겠다.`,
  opts:[
    { l:'① 동료와 한 판 한다.', co:'sync',
      coOpt:{ ask:'금이 그어져 있습니다. 한 판 하시겠습니까.', sec:60, p:950,
        text:`둘이 해야 하는 놀이다.`,
        doneText:`규칙을 설명하고 시작했다.<br><br>저쪽이 계속 졌다. 일부러 져 준 것 같기도 하다.<br>세 판 하고 그만뒀다.<br><br>그만두고 나니 마당이 조금 밝아 보였다.<br>기분 탓일 것이다.`,
        failText:`혼자 금 위를 왔다 갔다 했다.<br><br>놀이가 안 된다. 그냥 걷는 게 됐다.<br>그만뒀다.` },
      good:`세 판 했다.`, bad:`혼자 걸었다.`, flag:'playedGame' },
    { l:'② 굴렁쇠로 마을을 돈다.', mini:'beat', miniOpt:{ p:750, total:12, gap:700 },
      good:`열두 번. 안 넘어졌다.<br><br>골목마다 바퀴 소리가 울렸다.<br>스물셋 집을 다 돌았다.<br><br>돌고 나니 문이 두 개 열려 있었다. 안 열렸던 것들이.`, flag:'hoopCircuit',
      bad:`중간에 넘어졌다.<br><br>굴렁쇠가 혼자 굴러간다.<br>따라가지 않았다.` }
  ] }
);

epicSlot('lake', 'jester').push(
{ title:'거울 호수 — 둘이 보면 셋',
  text:`둘이 물가에 서면 비친 것도 둘이다.<br><br>
    합쳐서 넷이어야 하는데 셋으로 보인다.<br>
    광대는 수를 세는 눈이 있다. 관객 수를 세야 하니까.<br><br>
    하나가 모자란다.`,
  opts:[
    { l:'① 동료와 함께 센다.', co:'witness',
      coOpt:{ ask:'물에 비친 것을 같이 세어 주십시오.', sec:60, p:1000,
        text:`혼자 세면 틀린다.`,
        doneText:`둘이 동시에 세었다.<br><br>이쪽은 셋이라 하고 저쪽도 셋이라 한다.<br>서 있는 사람은 둘인데 비친 것이 하나.<br><br>누구 것이 안 비치는지는 서로 안 물었다.<br>물러났다. 둘 다 아무 말 없이.`,
        failText:`혼자 세었다. 하나뿐이다.<br><br>당연한데 한참 봤다.<br>비친 것이 웃고 있었다.` },
      good:`셋이었다.`, bad:`하나였다.`, flag:'countedThree' }
  ] }
);

epicSlot('temple', 'jester').push(
{ title:'신전 — 참는 것을 나눈다',
  text:`둘이 서 있으면 더 참기 어렵다.<br><br>
    한쪽이 웃으면 한쪽도 터진다. 광대끼리는 특히.<br>
    여기서 웃으면 안 된다는 건 둘 다 안다.<br><br>
    아는 것과 참는 것은 다르다.`,
  opts:[
    { l:'① 등을 돌리고 선다.', co:'sync',
      coOpt:{ ask:'마주 보면 터집니다. 등을 돌리고 서 주십시오.', sec:55, p:900,
        text:`마주 보면 진다.`,
        doneText:`등을 맞대고 섰다.<br><br>어깨가 떨리는 게 전해진다. 저쪽도 참고 있다.<br>참는 게 전해지는 것도 웃긴 일인데, 참았다.<br><br>둘 다 안 웃었다. 나와서 크게 웃었다.<br>밖에서 웃는 건 괜찮다.`,
        failText:`혼자 참았다.<br><br>참는 건 혼자가 나을 때도 있다.<br>입을 막고 서 있었다.` },
      good:`둘 다 참았다.`, bad:`혼자 참았다.`, flag:'backToBack' },
    { l:'② 촛불 밝기로 순서를 잡는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`일곱 개를 밝기 순으로 짚었다.<br><br>순서가 맞자 촛불이 한 방향으로 기운다.<br>제단 뒤쪽이다.<br><br>기운 쪽을 봤다. 마른 꽃이 놓여 있었다.`, flag:'candleOrder',
      bad:`순서가 엉켰다.<br><br>촛불이 제각각 흔들린다.<br>하나가 꺼질 뻔했다.` }
  ] }
);

epicSlot('grave', 'jester').push(
{ title:'묘지 — 둘이 하는 마지막 공연',
  text:`혼자 하는 것보다 둘이 낫다.<br><br>
    관객이 안 웃을 때는 특히.<br>
    서로 웃겨 주면 최소한 하나는 웃는다.<br><br>
    광대 둘이면 관객이 없어도 공연이 된다.`,
  opts:[
    { l:'① 동료와 같이 한다.', co:'call',
      coOpt:{ ask:'여기서 한 판 합시다. 관객은 없습니다만.', sec:60, p:1000,
        text:`둘이면 서로가 관객이다.`,
        doneText:`둘이 섰다. 비석 스물셋 앞에서.<br><br>주고받고 넘어지고 일으켜 세웠다.<br>저쪽이 먼저 웃었다. 이쪽도 웃었다.<br><br>웃음소리가 묘지에 울렸다. 이상하지 않았다.<br>끝나고 둘이 같이 인사했다.`,
        failText:`혼자 했다.<br><br>아무도 안 웃었다. 이쪽도 안 웃었다.<br>인사하고 나왔다.` },
      good:`둘이 웃었다.`, bad:`아무도 안 웃었다.`, flag:'duoGraveShow' }
  ] }
);

epicSlot('tower', 'jester').push(
{ title:'탑 — 올려 주고 내려 준다',
  text:`창틀이 높다.<br><br>
    혼자 올라가면 내려올 때 문제가 된다.<br>
    둘이면 한쪽이 받아 준다.<br><br>
    광대는 받아 주는 일에 익숙하다.`,
  opts:[
    { l:'① 동료가 아래에서 받는다.', co:'standin',
      coOpt:{ ask:'창틀에 올라갑니다. 아래에서 받아 주십시오.', sec:55, p:950,
        text:`받아 줄 사람이 있으면 뛸 수 있다.`,
        doneText:`창틀에 올라 밖을 봤다. 멀리까지 보인다.<br><br>보고 나서 뛰어내렸다. 받아 준다.<br>둘 다 넘어졌다. 웃었다.<br><br>본 것을 말해 줬다. 숲과 묘지 사이에 뭔가 있다고.`, 
        failText:`혼자 올라갔다. 내려올 때가 문제였다.<br><br>매달려서 발끝으로 더듬다 떨어졌다.<br>발목이 시큰하다.` },
      good:`보고 내려왔다.`, bad:`떨어졌다.`, flag:'caughtDown' },
    { l:'② 기울기를 재어 균형을 잡는다.', mini:'scale', miniOpt:{ p:800, target:24, pool:[3,5,7,8,10,13] },
      good:`돌을 놓아 가며 균형을 맞췄다.<br><br>맞자 탑이 한 뼘 바로 선다. 걷기가 편해졌다.<br>광대는 균형을 재는 눈이 있다.<br><br>줄 위에서 평생 잰 것이 여기서 쓰였다.`, flag:'towerBalance',
      bad:`어긋났다.<br><br>탑이 한 뼘 더 기운다.<br>손댄 것이 잘못이었다.` }
  ] }
);

epicSlot('forest', 'jester').push(
{ title:'검은 숲 — 소리로 찾는다',
  text:`흩어지면 찾기 어렵다.<br><br>
    광대는 소리를 낼 줄 안다. 방울이든 목청이든.<br>
    다만 여기서는 소리가 먹힌다.<br><br>
    먹히지 않게 내는 법이 있다.`,
  opts:[
    { l:'① 동료와 박자를 맞춰 낸다.', co:'sync',
      coOpt:{ ask:'방울을 같은 박자로 울립시다. 그래야 먹히지 않습니다.', sec:60, p:950,
        text:`한 번은 먹히지만 겹치면 남는다.`,
        doneText:`셋을 세고 동시에 울렸다.<br><br>겹친 소리는 안 먹힌다. 나무가 한 박자 늦게 반응한다.<br>그 틈에 서로 위치를 알았다.<br><br>세 번 하고 합류했다. 겹치는 소리는 남는다.`,
        failText:`혼자 울렸다. 먹혔다.<br><br>세 번 울려도 같았다.<br>표식을 남기며 걷기로 했다.` },
      good:`합류했다.`, bad:`혼자 걸었다.`, flag:'bellSignal' }
  ] }
);

epicSlot('gate', 'jester').push(
{ title:'성문 — 둘이 넘긴다',
  text:`아치가 반쯤 막혔다.<br><br>
    짐을 들고는 못 지난다. 몸만 겨우 빠진다.<br>
    한쪽이 먼저 지나고 짐을 받으면 된다.<br><br>
    광대는 던지고 받는 일을 잘한다.`,
  opts:[
    { l:'① 동료와 짐을 넘긴다.', co:'handoff',
      coOpt:{ ask:'먼저 지나가시면 짐을 넘겨 드리겠습니다.', sec:55, p:900,
        text:`몸만 지나고 짐은 넘긴다.`,
        doneText:`저쪽이 먼저 빠져나갔다.<br><br>틈으로 짐을 하나씩 넘겼다. 마지막은 던졌다.<br>받았다. 한 번도 안 떨어뜨렸다.<br><br>이쪽도 빠져나갔다. 옷만 좀 긁혔다.`,
        failText:`짐을 진 채로 밀어 넣었다.<br><br>어깨가 걸렸다. 물러나서 짐을 두고 지났다.<br>두고 온 짐은 못 찾았다.` },
      good:`전부 넘겼다.`, bad:`두고 왔다.`, flag:'passedGear' }
  ] }
);
;

// ---------- epic-jester-4.js ----------
// ==========================================
// ★ 광대 확장 4/4
// index.html 에서 epic-jester-3.js 다음에 불러온다
// ==========================================

epicSlot('market', 'jester').push(
{ title:'장터 — 값을 깎는다',
  text:`광대는 흥정을 잘한다.<br><br>
    웃기면서 깎는다. 웃으면 값이 내려간다.<br>
    다만 여기 주인들은 안 웃는다.<br><br>
    안 웃는 상대에게 쓰는 방법은 따로 있다.`,
  opts:[
    { l:'① 오래 버틴다.', dc:12, p:650,
      good:`값을 부르고 가만히 있었다.<br><br>주인이 먼저 움직인다. 손을 조금 내민다.<br>흥정은 먼저 말하는 쪽이 진다.<br><br>깎였다. 절반 가까이.`, flag:'outwaited',
      bad:`버티는데 이쪽이 먼저 지친다.<br><br>주인은 고개를 숙인 채 그대로다.<br>부른 값 그대로 냈다.`, poll:6 },
    { l:'② 재주를 보여 주고 깎는다.', dc:13, kind:'bond', p:700,
      good:`공 세 개를 돌려 보였다.<br><br>주인이 고개를 든다. 얼굴이 있다.<br>값을 반으로 깎아 준다.<br><br>웃지는 않았다. 다만 봤다. 그걸로 충분했다.`, flag:'tradedTrick',
      bad:`돌리는데 하나가 떨어진다.<br><br>주인이 고개를 도로 숙인다.<br>값은 그대로였다.`, poll:7 }
  ] },

{ title:'장터 — 잃어버린 방울',
  text:`옷에서 방울 하나가 없어졌다.<br><br>
    세어 보니 열하나다. 열둘이었는데.<br>
    광대는 방울 수를 안다. 소리로 안다.<br><br>
    소리가 하나 빈다.`,
  opts:[
    { l:'① 되짚어 찾는다.', dc:12, kind:'sense', p:650,
      good:`왔던 길을 되짚었다.<br><br>좌판 아래에 떨어져 있다. 주웠다.<br>주우려고 천을 들췄는데 아무것도 없었다.<br><br>달고 나니 소리가 맞는다.`, flag:'foundBell',
      bad:`되짚는데 어디서 잃었는지 모르겠다.<br><br>열한 개로 걷기로 했다.<br>소리가 계속 빈다.`, poll:7 },
    { l:'② 하나 더 만든다.', dc:11, p:550,
      good:`쇠붙이를 주워 구부렸다. 소리가 난다.<br><br>원래 것과 소리가 다르다. 그래도 열둘이 됐다.<br>다른 소리가 섞인 채로 걸었다.<br><br>섞인 것도 나쁘지 않았다.`, flag:'madeBell',
      bad:`구부린 것이 소리가 안 난다.<br><br>모양만 방울이다.<br>달지 않았다.`, poll:6 }
  ] }
);

epicSlot('castle', 'jester').push(
{ title:'성 — 대본',
  text:`무대 뒤에 종이가 있다.<br><br>
    대본이다. 광대는 대본을 안 쓴다. 즉흥이 일이다.<br>
    그런데 여기 대본에는 이쪽 이름이 적혀 있다.<br><br>
    배역 이름이 아니라 진짜 이름이.`,
  opts:[
    { l:'① 읽는다.', dc:14, kind:'gaze', p:750,
      doom:{ title:'적힌 대본', what:'대사를 하게 됐습니다', dc:14, sec:70,
        text:`펴서 읽었다.<br><br>이쪽이 할 말이 적혀 있다. 아직 안 한 말들이.<br>읽는 동안 입이 따라 움직인다.<br><br>다음 장을 넘겼다. 마지막 대사가 있다.<br>읽고 나면 끝난다는 뜻이다. 손이 멈추지 않는다.`,
        dieText:`광대는 즉흥으로 사는 사람이다.<br><br>적힌 대로 하면 광대가 아니라 배우다.<br>배우는 대본이 끝나면 퇴장한다.` },
      good:`첫 장만 보고 덮었다.<br><br>이름이 적힌 대본은 안 읽는다. 어디서 배운 건 아니다.<br>덮고 나니 손이 떨렸다.<br><br>무대에 올라가 즉흥으로 했다. 그게 광대다.`, flag:'closedScript' },
    { l:'② 불태운다.', dc:13, kind:'break', p:700,
      good:`촛불에 대고 태웠다.<br><br>잘 탄다. 종이치고도 잘 탄다.<br>재가 되고 나니 이름도 없어졌다.<br><br>적힌 것이 없으면 정해진 것도 없다.`, flag:'burnedScript',
      bad:`태우는데 불이 안 붙는다.<br><br>촛불에 대고 있어도 그대로다.<br>도로 놓았다.`, poll:8 }
  ] }
);

epicSlot('grave', 'jester').push(
{ title:'묘지 — 이름을 부르며',
  text:`비석에 이름이 없다.<br><br>
    광대는 공연 전에 관객 이름을 부른다. 아는 사람이 있으면.<br>
    부를 이름이 없다.<br><br>
    그러면 지어서 부르는 수밖에 없다.`,
  opts:[
    { l:'① 지어서 부른다.', dc:13, kind:'bond', p:750,
      good:`아무 이름이나 붙여 불렀다. 스물셋 개.<br><br>부르면서 하나씩 재주를 넘었다.<br>이름이 맞았을 리 없다. 다만 불렸다는 게 중요하다.<br><br>마지막 비석 앞에서 목이 쉬었다.`, flag:'namedThem',
      bad:`부르는데 이름이 안 떠오른다.<br><br>열 개쯤에서 바닥났다.<br>나머지는 그냥 섰다.`, poll:8 },
    { l:'② 이쪽 이름을 말한다.', dc:12, p:650,
      doom:{ title:'말한 이름', what:'이름이 불리고 있습니다', dc:14, sec:70,
        text:`이쪽 이름을 댔다. 소개하는 셈으로.<br><br>비석 스물셋이 동시에 그 이름을 부른다.<br>소리가 아니라 울림으로.<br><br>부르는 쪽과 불리는 쪽이 바뀌었다.<br>불리면 대답해야 한다. 광대는 대답을 잘한다.`,
        dieText:`무대에서는 이름을 대는 것이 시작이다.<br><br>여기서는 끝이었다.<br>비석이 스물넷이 됐다. 이름이 있는 것이 하나.` },
      good:`대려다 말았다.<br><br>여기서 이름을 대면 안 된다는 걸 알 것 같았다.<br>대신 모자를 벗어 보였다.<br><br>그게 인사다. 이름 없이도 인사는 된다.`, flag:'hatInstead' }
  ] }
);

epicSlot('village', 'jester').push(
{ title:'빈 마을 — 아무도 안 보는 공연',
  text:`마당 한가운데 섰다.<br><br>
    스물셋 집이 마당을 둘러싸고 있다.<br>
    문이 전부 열려 있다.<br><br>
    보는 사람이 없는데 무대 같다.`,
  opts:[
    { l:'① 끝까지 한다.', dc:13, kind:'bond', p:750,
      good:`아는 걸 다 했다. 순서대로.<br><br>중간에 문 하나가 조금 더 열렸다.<br>보고 있다는 뜻이다. 그래서 더 했다.<br><br>끝나고 인사했다. 문이 닫혔다. 천천히.`, flag:'villageShow',
      bad:`하다 보니 집들이 가까워진다.<br><br>마당이 좁아지는 것 같다.<br>중간에 그만뒀다.`, poll:8 },
    { l:'② 문 하나씩 닫으며 돈다.', dc:12, p:650,
      good:`한 바퀴 돌며 문을 닫았다. 스물셋 개.<br><br>닫으니 마당이 넓어졌다.<br>열린 문이 보는 눈이었던 것이다.<br><br>닫고 나서야 편히 섰다.`, flag:'closedDoors',
      bad:`닫으면 다시 열린다.<br><br>뒤에서 열리는 소리가 난다.<br>열 개쯤 하고 그만뒀다.`, poll:8 }
  ] }
);

epicSlot('forest', 'jester').push(
{ title:'검은 숲 — 웃음을 먹는 나무',
  text:`나무에 귀를 댔다.<br><br>
    안에서 소리가 난다. 웃음소리다.<br>
    먹힌 웃음이 여기 쌓여 있다.<br><br>
    누구 웃음인지는 안다. 들어 본 적 있는 소리다.`,
  opts:[
    { l:'① 더 듣는다.', dc:13, kind:'gaze', p:700,
      doom:{ title:'쌓인 웃음', what:'웃음에 섞이고 있습니다', dc:14, sec:70,
        text:`귀를 대고 있었다.<br><br>여럿이다. 스물셋쯤. 전부 다른 소리.<br>그중 하나가 이쪽 소리다. 낸 적이 없는데.<br><br>듣다 보니 따라 웃게 된다.<br>따라 웃으면 섞인다. 섞이면 하나가 더 늘어난다.`,
        dieText:`나무 안에 웃음이 스물넷이 됐다.<br><br>다음에 귀를 대는 광대가 들을 것이다.<br>자기 소리를.` },
      good:`한참 듣다가 귀를 뗐다.<br><br>여럿이다. 그중 하나가 익숙하다.<br>익숙한 게 무서워서 뗐다.<br><br>나무에서 물러났다. 뒤는 안 돌아봤다.`, flag:'heardLaughs' },
    { l:'② 웃음을 하나 돌려받는다.', dc:14, kind:'bond', p:750,
      good:`손을 대고 말했다. 돌려 달라고.<br><br>나무가 한 번 떤다. 뭔가 빠져나온다.<br>목이 트인다. 아까보다 편하다.<br><br>먹힌 것을 하나 되찾았다. 어느 것인지는 모르겠다.`, flag:'tookBackLaugh',
      bad:`손을 대고 기다렸다.<br><br>아무 일도 안 일어난다.<br>먹힌 건 안 돌려주는 모양이다.`, poll:7 }
  ] }
);

epicSlot('temple', 'jester').push(
{ title:'신전 — 재주를 바친다',
  text:`제단 위에 아무것도 없다.<br><br>
    바칠 것이 없다. 광대는 가진 게 없는 직업이다.<br>
    있는 건 재주뿐이다.<br><br>
    재주를 바친다는 말은 들어 본 적이 없다.`,
  opts:[
    { l:'① 제단 앞에서 재주를 넘는다.', dc:13, kind:'bond', p:750,
      good:`제일 잘하는 것을 한 번 넘었다.<br><br>바치는 셈으로. 촛불이 전부 한 번 기운다.<br>받았다는 뜻으로 받아들였다.<br><br>넘고 나니 그 재주가 안 떠오른다.<br>바친 게 맞는 모양이다.`, flag:'offeredTrick',
      bad:`넘는데 몸이 안 따라 준다.<br><br>평생 한 동작인데 처음 하는 것 같다.<br>중간에 그만뒀다.`, poll:8 },
    { l:'② 모자를 올려놓는다.', dc:12, p:650,
      good:`제단에 모자를 놓았다.<br><br>가진 것 중 제일 값나가는 것이다. 광대에게는.<br>놓고 물러섰다.<br><br>나올 때 도로 집었다. 두고 가면 광대가 아니게 되니까.`, flag:'hatOnAltar',
      bad:`놓으려는데 손이 안 펴진다.<br><br>모자는 못 놓는다.<br>다른 걸 놓았다.`, poll:7 }
  ] }
);

epicSlot('tower', 'jester').push(
{ title:'탑 — 꼭대기에서 부른다',
  text:`높은 데서 부르면 멀리 간다.<br><br>
    광대는 목청이 크다. 장터에서 사람을 모아야 하니까.<br>
    여기서 부르면 어디까지 갈지 모른다.<br><br>
    모으고 싶은 게 무엇인지도 모른다.`,
  opts:[
    { l:'① 동료를 부른다.', co:'call',
      coOpt:{ ask:'탑 위입니다. 여기서 부르겠습니다. 들리면 오십시오.', sec:60, p:950,
        text:`높은 데서 부르면 멀리 간다.`,
        doneText:`이름을 불렀다. 크게.<br><br>한참 뒤에 아래에서 대답이 왔다.<br>계단 소리가 올라온다. 한 사람 분이다.<br><br>올라왔다. 숨을 헐떡였다.<br>부르면 온다는 걸 확인한 게 컸다.`,
                failText:`불렀다. 대답이 없다.<br><br>세 번 불렀다. 세 번 다 메아리만 왔다.<br>메아리가 이쪽 목소리가 아니었다.` },
      good:`올라왔다.`, bad:`대답이 없었다.`, flag:'calledFromTop' },
    { l:'② 아무 말이나 외친다.', dc:12, p:650,
      good:`아무 말이나 크게 외쳤다. 장터에서 하던 호객 말이다.<br><br>말이 퍼진다. 멀리까지.<br>어디선가 개 짖는 소리가 났다. 개는 없는데.<br><br>그만뒀다. 한 번으로 충분했다.`, flag:'shoutedNonsense',
      bad:`외친 말이 돌아온다.<br><br>같은 말인데 다른 목소리다.<br>입을 다물었다.`, poll:8 }
  ] }
);

epicSlot('ruin', 'jester').push(
{ title:'폐허 — 관객석의 먼지',
  text:`단 아래에 자리가 있다.<br><br>
    돌을 깎아 만든 객석이다. 먼지가 두껍다.<br>
    광대는 객석 먼지를 보면 마지막 공연이 언제였는지 안다.<br><br>
    한 자리만 먼지가 없다.`,
  opts:[
    { l:'① 그 자리를 본다.', dc:12, kind:'sense', p:650,
      good:`가운데 앞줄이다. 성에서 본 자리와 같은 위치.<br><br>먼지가 없는 건 누가 앉았다는 뜻이다. 최근에.<br>온기는 없다.<br><br>앉지 않았다. 무대로 올라갔다.`, flag:'cleanSeat',
      bad:`보는데 먼지 없는 자리가 늘어난다.<br><br>하나씩, 앞줄부터.<br>돌아섰다.`, poll:9 },
    { l:'② 먼지를 전부 턴다.', dc:11, p:550,
      good:`소매로 쓸어 냈다. 스물셋 자리.<br><br>털고 나니 객석 같아 보인다.<br>이제 앉을 수만 있으면 된다.<br><br>앉을 사람은 없지만, 자리는 준비됐다.`, flag:'dustedSeats',
      bad:`털면 도로 앉는다.<br><br>먼지가 아니라 다른 것이다.<br>손을 털었다. 잘 안 털렸다.`, poll:8 }
  ] }
);

epicSlot('lake', 'jester').push(
{ title:'거울 호수 — 웃음이 비친다',
  text:`물에 비친 얼굴이 웃고 있다.<br><br>
    이번엔 이쪽도 웃고 있다.<br>
    언제부터 웃고 있었는지 모르겠다.<br><br>
    광대는 웃는 얼굴로 오래 있는 데 익숙하다. 그게 문제다.`,
  opts:[
    { l:'① 웃음을 거둔다.', dc:13, kind:'evade', p:700,
      good:`입꼬리를 내렸다. 힘을 줘서.<br><br>안 내려간다. 두 번 세 번 해서 내렸다.<br>비친 쪽은 계속 웃는다.<br><br>이제 다르다. 다른 게 맞다.`, flag:'stoppedSmile',
      bad:`내리려는데 더 올라간다.<br><br>손으로 눌러 내렸다.<br>손을 떼니 도로 올라갔다.`, poll:9 },
    { l:'② 얼굴을 만져 본다.', dc:12, kind:'sense', p:650,
      good:`손으로 뺨을 만졌다.<br><br>분이 묻어 나온다. 바른 적이 없는데.<br>물에 씻었다. 잘 씻긴다.<br><br>씻기는 걸 확인하고 나니 마음이 놓였다.`, flag:'washedFace',
      bad:`만지는데 얼굴이 단단하다.<br><br>살이 아니다. 문질러도 안 변한다.<br>손을 뗐다.`, poll:9 }
  ] }
);

epicSlot('road', 'jester').push(
{ title:'끊긴 길 — 건너편의 박수',
  text:`안개 저편에서 소리가 난다.<br><br>
    박수 소리다. 하나가 아니라 여럿.<br>
    광대가 제일 듣고 싶어 하는 소리다.<br><br>
    듣고 싶은 소리가 나는 쪽은 대개 위험하다.`,
  opts:[
    { l:'① 인사만 하고 간다.', dc:12, p:650,
      good:`모자를 벗고 안개 쪽으로 인사했다.<br><br>박수가 커진다. 그리고 멎는다.<br>인사로 끝냈다. 공연은 인사로 끝난다.<br><br>돌아서서 갔다. 안 돌아봤다.`, flag:'bowedToFog' },
    { l:'② 건너가서 한 번 더 한다.', dc:15, kind:'luck', p:850,
      doom:{ title:'건너간 무대', what:'앙코르가 끝나지 않습니다', dc:15, sec:75,
        text:`건넜다. 저쪽에 객석이 있다. 가득 차 있다.<br><br>했다. 박수가 터진다. 살면서 들어 본 중 제일 크다.<br>한 번 더 하라고 한다. 했다. 또 하라고 한다.<br><br>다리가 후들거린다. 그만하고 싶다.<br>박수가 안 멎는다. 광대는 박수 앞에서 못 내려온다.`,
        dieText:`광대가 제일 바라던 것이 제일 위험했다.<br><br>객석이 스물셋이었고, 이제 무대에 하나가 있다.<br>안 내려온다.` },
      good:`발을 올렸다가 내렸다.<br><br>박수 소리가 너무 좋다. 그게 걸렸다.<br>좋은 게 걸릴 때는 안 가는 게 맞다.<br><br>손만 흔들고 돌아섰다. 박수가 멎었다.`, flag:'refusedApplause' }
  ] }
);
;

