// ==========================================
// ★ 밀정 확장 1/4
// index.html 에서 epic-jester-4.js 다음에 불러온다
// ==========================================

epicSlot('castle', 'spy').push(
{ title:'성 — 두 벌의 옷',
  text:`옷장에 옷이 걸려 있다.<br><br>
    두 종류다. 한쪽은 이쪽 진영 것, 한쪽은 저쪽 것.<br>
    밀정은 둘 다 입을 줄 안다.<br><br>
    입는 순서가 있다. 안에 하나, 겉에 하나.`,
  opts:[
    { l:'① 겹쳐 입는다.', dc:13, kind:'hide', p:700,
      good:`안쪽에 저쪽 것을 입고 겉에 이쪽 것을 입었다.<br><br>필요하면 벗으면 된다. 벗는 게 갈아입는 것보다 빠르다.<br>밀정이 제일 먼저 배우는 것이다.<br><br>겹쳐 입으니 무겁다. 무거운 게 안전하다.`, flag:'doubleCoat',
      bad:`겹쳐 입는데 안쪽이 안 맞는다.<br><br>이쪽 치수가 아니다. 억지로 입으니 움직이기 어렵다.<br>한 벌만 입었다.`, poll:7 },
    { l:'② 어느 쪽이 많은지 센다.', dc:12, kind:'gaze', p:650,
      good:`세어 봤다. 이쪽 것 열둘, 저쪽 것 열하나.<br><br>합쳐서 스물셋이다.<br>한 벌 차이는 우연이 아니다. 하나가 옮겨 갔거나 옮겨 왔다.<br><br>걸린 순서도 봤다. 번갈아 걸려 있었다.`, flag:'countedCoats',
      bad:`세는데 수가 안 맞는다.<br><br>볼 때마다 다르다. 이쪽이 많았다 저쪽이 많았다.<br>그만 셌다.`, poll:8 }
  ] },

{ title:'성 — 두 번 적힌 장부',
  text:`장부가 둘이다.<br><br>
    같은 날짜, 같은 항목. 다만 숫자가 다르다.<br>
    밀정은 이런 걸 찾는 사람이다.<br><br>
    어느 쪽이 진짜인지는 세 번째 장부를 봐야 안다.`,
  opts:[
    { l:'① 차이를 대조한다.', dc:13, kind:'gaze', p:750,
      good:`나란히 놓고 훑었다.<br><br>스물셋 줄이 같고 한 줄이 다르다.<br>다른 줄은 사람 수다. 한쪽은 스물넷, 한쪽은 스물셋.<br><br>하나가 지워진 게 아니라 하나가 추가된 것이다.`, flag:'twoLedgers',
      bad:`대조하는데 숫자가 바뀐다.<br><br>본 자리로 돌아가면 달라져 있다.<br>덮었다.`, poll:8 },
    { l:'② 세 번째를 찾는다.', dc:14, kind:'sense', p:800,
      doom:{ title:'세 번째 장부', what:'이름이 대조되고 있습니다', dc:14, sec:70,
        text:`서랍 안쪽에 하나 더 있다.<br><br>펴 보니 이름만 적혀 있다. 스물넷.<br>스물셋에 줄이 그어져 있고 하나가 남았다.<br><br>남은 이름을 봤다. 이쪽 것이다.<br>줄이 그어지는 중이다. 천천히, 저절로.`,
        dieText:`밀정은 대조하는 사람이다.<br><br>대조당하는 쪽이 되면 할 수 있는 게 없다.<br>스물넷째 줄이 그어졌다.` },
      good:`서랍을 열다 손을 멈췄다.<br><br>안쪽에 하나 더 있는 게 보인다. 꺼내지 않았다.<br>세 번째를 보면 이쪽도 적힌다.<br><br>밀정이 오래 사는 방법은 덜 보는 것이다.`, flag:'leftThird' }
  ] }
);

epicSlot('gate', 'spy').push(
{ title:'성문 — 드나든 수',
  text:`아치 안쪽에 금이 그어져 있다.<br><br>
    드나든 수를 센 것이다. 밀정은 이런 금을 남긴다.<br>
    들어간 금과 나간 금을 다르게 긋는다.<br><br>
    들어간 금이 스물넷, 나간 금이 하나다.`,
  opts:[
    { l:'① 이쪽 금을 긋는다.', dc:11, p:550,
      good:`들어간 쪽에 하나 그었다.<br><br>스물다섯이 됐다.<br>나갈 때 나간 쪽에 그으면 된다. 그을 수 있으면.<br><br>손톱으로 그었다. 연장은 안 쓴다.`, flag:'markedEntry',
      bad:`긋는데 돌이 안 파인다.<br><br>손톱이 먼저 부러졌다.<br>금은 못 그었다.`, poll:7 },
    { l:'② 나간 금을 살핀다.', dc:12, kind:'sense', p:650,
      good:`하나뿐인 나간 금을 봤다.<br><br>다른 금보다 깊다. 여러 번 덧그었다.<br>확인시키려는 것처럼.<br><br>나간 사람이 스스로 그은 게 아닐 수도 있다.`, flag:'deepExit',
      bad:`살피는데 금이 하나 더 생긴다.<br><br>나간 쪽에. 방금.<br>주변에 아무도 없었다.`, poll:8 }
  ] }
);

epicSlot('tower', 'spy').push(
{ title:'탑 — 위에서 세는 것',
  text:`꼭대기에서 아래가 보인다.<br><br>
    밀정은 높은 데서 수를 센다. 어디에 몇이 있는지.<br>
    마을에 스물셋, 묘지에 스물셋, 장터에 스물셋.<br><br>
    같은 수가 세 번 나오면 우연이 아니다.`,
  opts:[
    { l:'① 겹치는 자리를 찾는다.', dc:14, kind:'gaze', p:800,
      good:`세 곳을 번갈아 봤다.<br><br>배치가 같다. 집도 비석도 좌판도 같은 모양으로 놓였다.<br>세 곳이 같은 도면으로 만들어졌다.<br><br>도면의 가운데가 어디인지 보니, 숲과 묘지 사이다.`, flag:'deepFound', flag2:true,
      bad:`보다 보니 세 곳이 겹쳐 보인다.<br><br>어느 것이 어느 곳인지 모르겠다.<br>눈을 감았다.`, poll:9 },
    { l:'② 기록만 남긴다.', dc:11, p:550,
      good:`보이는 대로 적었다. 위치와 수.<br><br>적는 것은 밀정의 일이다. 판단은 다른 사람이 한다.<br>적어 두면 언젠가 쓰인다.<br><br>세 장 적었다.`, flag:'wroteFromTop',
      bad:`적는데 손이 떨린다.<br><br>높은 데서 오래 봐서 그런 것 같다.<br>절반만 적었다.`, poll:6 }
  ] }
);

epicSlot('forest', 'spy').push(
{ title:'검은 숲 — 지나간 쪽',
  text:`나무에 표식이 있다.<br><br>
    밀정이 쓰는 방식이다. 어느 방향으로 갔는지 남기는 것.<br>
    다만 방향이 두 개다.<br><br>
    둘 다 최근 것이다.`,
  opts:[
    { l:'① 어느 쪽이 나중인지 본다.', dc:13, kind:'sense', p:700,
      good:`껍질 색을 봤다. 오른쪽 것이 더 밝다.<br><br>나중에 그은 것이다. 방향을 바꿨다는 뜻이다.<br>바꾼 이유가 있을 것이다.<br><br>먼저 그은 쪽으로 갔다.`, flag:'laterMark',
      bad:`둘 다 같은 색이다.<br><br>동시에 그었다는 뜻인데, 한 사람이 동시에 두 방향으로 갈 수는 없다.<br>둘이었거나, 하나가 둘이 됐거나.`, poll:8 },
    { l:'② 세 번째를 그린다.', dc:12, p:650,
      good:`둘 사이에 하나 더 그었다. 가운데 방향으로.<br><br>다음에 오는 밀정이 헷갈릴 것이다.<br>헷갈리는 게 목적이다. 뒤따라오는 쪽이 있으니까.<br><br>그어 놓고 원래 방향으로 갔다.`, flag:'falseMark',
      bad:`긋는데 나무가 물렁하다.<br><br>손가락이 들어간다. 자국이 안 남는다.<br>그만뒀다.`, poll:7 }
  ] }
);

epicSlot('lake', 'spy').push(
{ title:'거울 호수 — 반대로 읽는다',
  text:`물가 바위에 글자가 있다.<br><br>
    거꾸로 새겨져 있다. 물에 비춰야 읽힌다.<br>
    밀정이 쓰는 방식이다. 번거롭지만 확실하다.<br><br>
    다만 이번 것은 비춰도 안 읽힌다.`,
  opts:[
    { l:'① 다른 각도에서 본다.', dc:13, kind:'gaze', p:700,
      good:`엎드려서 낮은 각도로 봤다.<br><br>글자가 잡힌다. 두 겹으로 새겨져 있었다.<br>위에서 보면 섞이고 낮게 보면 갈린다.<br><br><span style="color:#d4af37;">"둘 다 속이고 있다."</span>`, flag:'lowAngle',
      bad:`각도를 바꿀수록 글자가 늘어난다.<br><br>세 겹, 네 겹.<br>읽는 걸 그만뒀다.`, poll:8 },
    { l:'② 탁본을 뜬다.', dc:12, p:650,
      good:`종이를 대고 숯으로 문질렀다.<br><br>뜬 것을 뒤집어 보니 읽힌다.<br>비추지 않아도 되는 방법이 있었다.<br><br>탁본을 접어 넣었다. 나중에 읽을 것이다.`, flag:'rubbing',
      bad:`문지르는데 종이가 젖는다.<br><br>물가라서가 아니다. 바위가 젖어 있다.<br>글자가 번졌다.`, poll:7 }
  ] }
);

epicSlot('temple', 'spy').push(
{ title:'신전 — 양쪽이 두고 간 것',
  text:`제단 아래에 물건이 있다.<br><br>
    둘이다. 하나는 이쪽 진영 표식, 하나는 저쪽 것.<br>
    같은 자리에 두고 갔다.<br><br>
    같은 것을 빌러 온 것이다.`,
  opts:[
    { l:'① 둘 다 확인한다.', dc:12, kind:'gaze', p:650,
      good:`꺼내 펴 봤다. 둘 다 종이다.<br><br>적힌 내용이 같다. 필체만 다르다.<br><span style="color:#d4af37;">"끝내 주십시오."</span><br><br>무엇을 끝내라는 건지는 안 적혀 있다.<br>도로 넣었다. 둘 다 원래 자리에.`, flag:'bothPrayers',
      bad:`꺼내는데 하나가 부스러진다.<br><br>오래된 쪽이다. 만지니 가루가 됐다.<br>하나만 남았다.`, poll:7 },
    { l:'② 이쪽 것을 하나 더 놓는다.', dc:12, kind:'bond', p:650,
      good:`종이에 적어 같이 두었다.<br><br>무엇을 적었는지는 나중에 잊었다.<br>셋이 됐다.<br><br>세 번째가 있으면 누가 봐도 두 편이 아니게 된다.`, flag:'thirdPrayer',
      bad:`적으려는데 붓이 없다.<br><br>손가락으로 쓰니 안 남는다.<br>빈 종이만 놓고 나왔다.`, poll:6 }
  ] }
);

epicSlot('village', 'spy').push(
{ title:'빈 마을 — 집집의 방향',
  text:`집 스물셋이 전부 같은 방향을 본다.<br><br>
    마당도 문도 창도 한쪽이다.<br>
    밀정은 배치를 읽는다. 배치에는 의도가 있다.<br><br>
    보는 쪽은 숲과 묘지 사이다.`,
  opts:[
    { l:'① 한 집만 다른지 확인한다.', dc:13, kind:'sense', p:750,
      good:`한 바퀴 돌며 확인했다.<br><br>스물둘은 같고 하나가 다르다. 등지고 있다.<br>등진 집만 문이 닫혀 있다.<br><br>닫힌 문은 안 열었다. 위치만 외웠다.`, flag:'oneFacing',
      bad:`세는데 방향이 바뀐다.<br><br>돌아보면 다른 쪽을 보고 있다.<br>집이 움직이는 게 아니라 이쪽이 도는 것 같다.`, poll:9 },
    { l:'② 보는 쪽으로 가 본다.', dc:12, p:650,
      good:`마을 밖으로 걸었다. 집들이 보는 방향으로.<br><br>백 걸음쯤 가니 풀이 눌려 있다. 길처럼.<br>스물셋이 오간 자국이다.<br><br>더 안 갔다. 위치만 적었다.`, flag:'wornPath',
      bad:`걷는데 마을이 멀어지지 않는다.<br><br>돌아보면 같은 거리다.<br>되돌아왔다.`, poll:8 }
  ] }
);

epicSlot('grave', 'spy').push(
{ title:'묘지 — 지워진 이름들',
  text:`비석이 백지다.<br><br>
    밀정은 이름이 없는 무덤을 여럿 안다. 동업자 것이다.<br>
    이름을 지우는 건 일의 일부다.<br><br>
    다만 여기는 지운 게 아니다. 새긴 적이 없다.`,
  opts:[
    { l:'① 새긴 적 없는 이유를 생각한다.', dc:13, kind:'gaze', p:700,
      good:`돌을 만져 봤다. 매끈하다.<br><br>정을 댄 적이 없다. 이름을 안 새긴 게 아니라 새길 수 없었다.<br>이름이 없는 것들이었다.<br><br>밀정은 이름이 둘이라 하나도 안 남는다. 여기는 아예 없었다.`, flag:'neverNamed',
      bad:`만지자 손끝에 글자가 걸린다.<br><br>안 보이는데 만져진다.<br>손을 뗐다.`, poll:9 },
    { l:'② 이쪽 가명을 하나 새긴다.', dc:12, kind:'bond', p:700,
      good:`쓰던 가명 하나를 새겼다.<br><br>본명이 아니니 상관없다. 밀정에게 가명은 옷이다.<br>벗어 둘 수 있다.<br><br>새기고 나니 그 가명은 다시 못 쓰게 됐다.`, flag:'buriedAlias',
      bad:`새기는데 손이 본명을 쓴다.<br><br>세 글자에서 멈췄다. 긁어 지웠다.<br>지운 자국이 남았다.`, poll:9 }
  ] }
);

epicSlot('ruin', 'spy').push(
{ title:'폐허 — 두 번 무너진 곳',
  text:`무너진 방식이 둘이다.<br><br>
    한쪽은 오래됐고 한쪽은 최근이다.<br>
    밀정은 무너진 순서를 읽는다.<br><br>
    최근 것이 오래된 것 위에 있다. 당연한데, 한 군데만 반대다.`,
  opts:[
    { l:'① 반대인 자리를 본다.', dc:14, kind:'sense', p:800,
      good:`오래된 돌이 위에 있다.<br><br>누가 들어 올려 다시 쌓았다는 뜻이다.<br>아래에 뭔가를 덮으려고.<br><br>들추지 않았다. 덮은 사람이 있으면 이유가 있다.`, flag:'restacked',
      bad:`보다 보니 순서가 바뀐다.<br><br>위아래가 뒤집힌다. 볼 때마다.<br>눈을 뗐다.`, poll:9 },
    { l:'② 들춰 본다.', dc:13, kind:'break', p:700,
      doom:{ title:'덮어 둔 것', what:'덮인 것이 드러났습니다', dc:14, sec:70,
        text:`위쪽 돌을 치웠다. 세 개쯤.<br><br>아래에 옷이 있다. 개켜져 있다.<br>밀정 옷이다. 이쪽이 입은 것과 같은.<br><br>안에 사람이 있다. 아직 형태가 남아 있다.<br>일어나 앉는다. 옷이 같으면 구분이 안 간다.`,
        dieText:`덮어 둔 데는 이유가 있다.<br><br>덮은 쪽도 밀정이었다.<br>돌이 다시 쌓였다. 이번에는 둘을 덮었다.` },
      good:`한 개만 들추고 도로 놓았다.<br><br>천이 보인다. 옷감이다. 그 이상은 안 봤다.<br>밀정은 덜 보는 쪽이 오래 산다.<br><br>쌓인 대로 두고 갔다.`, flag:'coveredAgain' }
  ] }
);

epicSlot('market', 'spy').push(
{ title:'장터 — 팔리는 소문',
  text:`좌판 사이에 말이 오간다.<br><br>
    소리는 안 나는데 오간다. 손짓과 눈짓으로.<br>
    밀정은 말 없는 대화를 읽는다.<br><br>
    같은 손짓이 좌판마다 반복된다.`,
  opts:[
    { l:'① 손짓을 외운다.', dc:13, kind:'gaze', p:750,
      good:`세 가지다. 손바닥을 펴고, 주먹을 쥐고, 두 손가락을 든다.<br><br>순서가 있다. 펴고 쥐고 들면 한 문장이 된다.<br>무슨 뜻인지는 모르겠다. 외웠다.<br><br>외워 두면 언젠가 맞춰진다.`, flag:'learnedSigns',
      bad:`외우는데 순서가 바뀐다.<br><br>좌판마다 다르게 한다.<br>세 번 보고 그만뒀다.`, poll:7 },
    { l:'② 따라 해 본다.', dc:14, kind:'bond', p:800,
      doom:{ title:'따라 한 손짓', what:'대답을 요구받고 있습니다', dc:14, sec:70,
        text:`순서대로 해 봤다. 펴고 쥐고 둘.<br><br>스물셋 개의 고개가 동시에 든다.<br>같은 손짓이 돌아온다. 스물셋 번.<br><br>다음 문장을 기다리는 것이다.<br>모르는 언어로 먼저 말을 걸었다. 물러날 수가 없다.`,
        dieText:`밀정은 남의 말을 읽는 사람이지 쓰는 사람이 아니다.<br><br>쓰려면 끝까지 쓸 줄 알아야 한다.<br>좌판이 하나 늘었다.` },
      good:`첫 동작만 해 봤다. 손바닥을 폈다.<br><br>가까운 좌판 하나가 고개를 든다. 하나만.<br>거기서 멈췄다.<br><br>모르는 말은 한 마디만 해 보는 게 맞다.`, flag:'triedOneSign' }
  ] }
);

epicSlot('road', 'spy').push(
{ title:'끊긴 길 — 양쪽의 표식',
  text:`끊긴 자리 양쪽에 표식이 있다.<br><br>
    이쪽 것과 저쪽 것. 마주 보고 그려져 있다.<br>
    밀정 둘이 양쪽에 서서 그은 것이다.<br><br>
    끊긴 길을 사이에 두고.`,
  opts:[
    { l:'① 둘을 맞춰 읽는다.', dc:13, kind:'gaze', p:750,
      good:`양쪽을 번갈아 봤다.<br><br>합치면 한 문장이 된다. 각자 절반씩 그었다.<br><span style="color:#d4af37;">"건너지 말 것. 건너간 쪽은 안 돌아옴."</span><br><br>둘이 합의해서 남긴 것이다. 적이었을 텐데.`, flag:'jointWarning',
      bad:`맞추는데 절반이 안 읽힌다.<br><br>저쪽 것이 흐리다. 지워지는 중이다.<br>읽은 절반만 적었다.`, poll:8 },
    { l:'② 이쪽 절반을 지운다.', dc:12, p:650,
      good:`문지르려다 그만뒀다.<br><br>둘이 합의한 것을 혼자 지우는 건 아니다.<br>대신 덧그렸다. 더 진하게.<br><br>다음 사람이 잘 보게.`, flag:'reinforced',
      bad:`지우려는데 손이 안 움직인다.<br><br>지우면 안 된다는 걸 몸이 아는 것 같다.<br>손을 내렸다.`, poll:7 }
  ] }
);
;

