epicSlot('castle', 'spy').push(
{ title:'성 — 신호를 맞춘다',
  text:`복도가 길다.<br><br>
    한쪽 끝에서 다른 쪽이 안 보인다.<br>
    밀정은 신호를 정해 두고 움직인다.<br><br>
    두드리는 박자로 주고받는다.`,
  opts:[
    { l:'① 동료와 신호를 정한다.', co:'sync',
      coOpt:{ ask:'신호를 맞춥시다. 세 번은 안전, 두 번은 멈춤입니다.', sec:60, p:1000,
        text:`정해 두지 않으면 못 움직인다.`,
        doneText:`복도 양 끝에 섰다.<br><br>세 번 두드렸다. 저쪽에서 세 번 돌아온다.<br>움직였다. 가운데서 두 번이 왔다. 멈췄다.<br><br>멈춘 자리 앞으로 뭔가 지나갔다.<br>지나가고 나서 다시 세 번이 왔다.`,
        failText:`혼자 움직였다.<br><br>가운데쯤에서 멈출 뻔했다. 아무도 알려 주지 않아서 늦었다.<br>벽에 붙어 지나갔다.` },
      good:`지나갔다.`, bad:`늦었다.`, flag:'tapSignal' },
    { l:'② 박자를 외워 둔다.', mini:'beat', miniOpt:{ p:750, total:10, gap:720 },
      good:`열 번. 박자를 놓치지 않았다.<br><br>벽 너머에서 같은 박자가 돌아온다.<br>누가 쓰는 신호인지는 모르겠다. 다만 통한다.<br><br>통하는 것만 확인하고 물러났다.`, flag:'knockCode',
      bad:`중간에 어긋났다.<br><br>돌아오는 박자가 빨라진다. 재촉하는 것 같다.<br>두드리기를 멈췄다.` }
  ] },

{ title:'성 — 문서를 나눠 읽는다',
  text:`서류가 많다.<br><br>
    혼자 읽으면 시간이 걸린다. 시간이 걸리면 들킨다.<br>
    둘이 나눠 읽고 합치면 빠르다.<br><br>
    밀정이 둘일 때 제일 잘하는 일이다.`,
  opts:[
    { l:'① 동료와 나눠 읽는다.', co:'handoff',
      coOpt:{ ask:'서류를 반씩 읽읍시다. 다 읽고 맞춰 봅시다.', sec:60, p:950,
        text:`둘이면 절반씩이다.`,
        doneText:`반씩 나눠 훑었다.<br><br>맞춰 보니 이어진다. 한 사람 분으로는 안 보이던 것이 보인다.<br>날짜, 인원, 그리고 한 줄.<br><br><span style="color:#d4af37;">"스물넷 중 하나는 세지 말 것."</span><br><br>둘 다 읽었다. 둘 다 말을 안 했다.`,
                failText:`혼자 읽었다. 절반쯤에서 그만뒀다.<br><br>오래 있으면 안 된다.<br>읽은 데까지만 외웠다.` },
      good:`전부 읽었다.`, bad:`절반만 읽었다.`, flag:'splitRead' },
    { l:'② 서랍 자물쇠를 딴다.', mini:'lock', miniOpt:{ p:750, rounds:3, hard:1 },
      good:`세 핀을 차례로 눌렀다.<br><br>안쪽에 봉투가 있다. 봉인이 두 개다.<br>이쪽 진영 것과 저쪽 것.<br><br>둘 다 뜯지 않았다. 뜯으면 표가 난다.`, flag:'sealedEnvelope',
      bad:`마지막 핀이 안 눌린다.<br><br>안에서 잠그는 구조다.<br>포기했다.` }
  ] }
);

epicSlot('market', 'spy').push(
{ title:'장터 — 눈을 나눈다',
  text:`좌판이 많다.<br><br>
    혼자 보면 놓친다. 둘이 반대 방향을 보면 안 놓친다.<br>
    밀정은 시야를 나눠 쓴다.<br><br>
    등을 맞대는 것이 제일 확실하다.`,
  opts:[
    { l:'① 동료와 등을 맞댄다.', co:'sync',
      coOpt:{ ask:'등을 맞대고 반대쪽을 봐 주십시오.', sec:60, p:1000,
        text:`혼자서는 반만 본다.`,
        doneText:`등을 맞대고 섰다.<br><br>이쪽이 북쪽, 저쪽이 남쪽을 봤다.<br>저쪽이 낮게 말했다. 좌판 하나가 사람이 둘이라고.<br><br>이쪽에서는 안 보이던 것이다.<br>보이는 쪽이 다르면 보이는 것도 다르다.`,
        failText:`혼자 돌아가며 봤다.<br><br>고개를 돌리는 사이에 뭔가 바뀐다.<br>바뀐 걸 알겠는데 뭐가 바뀌었는지는 모르겠다.` },
      good:`전부 봤다.`, bad:`반만 봤다.`, flag:'backSight' },
    { l:'② 값의 차이를 잰다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`같은 물건을 좌판 둘에서 재 봤다.<br><br>무게는 같은데 값이 다르다. 정확히 두 배.<br>한쪽이 다른 쪽을 속이고 있다.<br><br>어느 쪽이 속이는지는 세 번째 좌판을 봐야 안다.`, flag:'priceGap',
      bad:`저울이 안 맞는다.<br><br>재는 쪽마다 다르다.<br>비교를 포기했다.` }
  ] }
);

epicSlot('road', 'spy').push(
{ title:'끊긴 길 — 한쪽이 남는다',
  text:`건너려면 줄이 필요하다.<br><br>
    한쪽이 잡고 한쪽이 건넌다. 건넌 쪽은 돌아올 수 없다.<br>
    밀정은 이런 선택에 익숙하다.<br><br>
    누가 남을지 정해야 한다.`,
  opts:[
    { l:'① 동료와 정한다.', co:'standin',
      coOpt:{ ask:'한쪽이 줄을 잡아야 합니다. 누가 남을지 정합시다.', sec:60, p:1000,
        text:`한쪽은 남아야 한다.`,
        doneText:`저쪽이 잡겠다고 했다.<br><br>이유는 안 물었다. 밀정끼리는 안 묻는다.<br>건넜다. 건너서 돌아보니 아직 잡고 있다.<br><br>손을 들었다. 저쪽도 들었다.<br>줄을 놓는 소리가 났다. 뒤는 안 봤다.`,
                failText:`혼자 건너려 했다.<br><br>줄이 느슨하다. 두 걸음에서 내려왔다.<br>다른 길을 찾았다.` },
      good:`건넜다.`, bad:`못 건넜다.`, flag:'oneStayed' },
    { l:'② 표식 순서를 읽는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`길가 표식 여섯을 순서대로 짚었다.<br><br>이어 읽으니 문장이 된다.<br><span style="color:#d4af37;">"건넌 쪽을 세지 말 것."</span><br><br>어디서 본 문장이다. 서류에도 비슷한 게 있었다.`, flag:'roadPhrase',
      bad:`순서가 엉켰다.<br><br>엉킨 대로 읽으니 다른 문장이 된다.<br>읽고 나서 머리가 아팠다.` }
  ] }
);

epicSlot('village', 'spy').push(
{ title:'빈 마을 — 둘이 도는 편이 빠르다',
  text:`집이 스물셋이다.<br><br>
    혼자 다 보려면 오래 걸린다. 오래 걸리면 표가 난다.<br>
    둘이 반대 방향으로 돌면 절반이다.<br><br>
    가운데서 만나면 된다.`,
  opts:[
    { l:'① 반대 방향으로 돈다.', co:'sync',
      coOpt:{ ask:'반대쪽부터 돌아 주십시오. 가운데서 만납시다.', sec:60, p:1000,
        text:`둘이 반대로 돌면 절반이다.`,
        doneText:`갈라져서 돌았다.<br><br>가운데서 만났다. 저쪽이 열둘, 이쪽이 열하나를 봤다.<br>합쳐서 스물셋이다.<br><br>다만 둘 다 문이 닫힌 집을 봤다고 한다.<br>하나뿐인데 둘이 봤다.`,
                failText:`혼자 돌았다. 여덟 집에서 그만뒀다.<br><br>같은 광경을 여덟 번 보면 그만두게 된다.<br>나머지는 안 봤다.` },
      good:`전부 봤다.`, bad:`여덟 집만 봤다.`, flag:'splitRound' },
    { l:'② 문패 자국을 순서대로 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`떼어 낸 자국을 오래된 순서로 짚었다.<br><br>일곱 번. 순서가 맞자 배치가 보인다.<br>먼저 뗀 집부터 마을 바깥쪽이다.<br><br>안쪽에서 바깥으로 번졌다는 뜻이다.`, flag:'plateOrder',
      bad:`순서를 못 잡겠다.<br><br>자국 깊이가 다 같다. 한꺼번에 뗀 것이다.<br>순서가 없었다.` }
  ] }
);

epicSlot('forest', 'spy').push(
{ title:'검은 숲 — 갈라져서 본다',
  text:`숲이 넓다.<br><br>
    혼자 훑으면 못 본다. 둘이 갈라지면 두 배다.<br>
    다만 갈라지면 서로를 못 본다.<br><br>
    밀정은 갈라지는 데 익숙하고, 그래서 자주 잃는다.`,
  opts:[
    { l:'① 동료와 갈라진다.', co:'call',
      coOpt:{ ask:'갈라져서 봅시다. 표식을 남기며 가십시오.', sec:60, p:950,
        text:`갈라지면 두 배를 본다.`,
        doneText:`갈라졌다. 표식을 남기며 갔다.<br><br>한참 뒤에 저쪽 표식을 만났다. 이쪽으로 오고 있었다.<br>원을 그린 것이다. 둘 다.<br><br>만나서 합쳤다. 본 것을 맞춰 보니 같은 곳을 두 번 본 셈이었다.<br>숲이 그렇게 되어 있었다.`,
                failText:`혼자 갔다.<br><br>표식을 남기며 갔는데 앞에 이미 표식이 있다.<br>이쪽 것이다. 원을 그렸다.` },
      good:`합쳤다.`, bad:`돌았다.`, flag:'splitForest' },
    { l:'② 발소리를 겹쳐 간다.', mini:'beat', miniOpt:{ p:750, total:12, gap:700 },
      good:`열두 걸음. 앞선 소리에 맞춰 디뎠다.<br><br>겹치니 하나로 들린다.<br>앞선 것이 멈췄다. 이쪽도 멈췄다.<br><br>한참 있다 다시 걸었다. 안 들킨 모양이다.`, flag:'matchedSteps',
      bad:`반 박자 어긋났다.<br><br>앞선 것이 멈춘다. 이쪽 소리만 하나 더 났다.<br>천천히 돌아선다.` }
  ] }
);

epicSlot('temple', 'spy').push(
{ title:'신전 — 둘이 증언한다',
  text:`제단 아래에서 본 것이 있다.<br><br>
    혼자 본 것은 보고가 안 된다. 밀정 규정이다.<br>
    둘이 봐야 기록이 된다.<br><br>
    여기서 규정을 따지는 게 우습지만, 그래도.`,
  opts:[
    { l:'① 동료에게 보인다.', co:'witness',
      coOpt:{ ask:'제단 아래에 뭔가 있습니다. 같이 봐 주십시오.', sec:60, p:1000,
        text:`혼자 본 것은 보고가 안 된다.`,
        doneText:`같이 들여다봤다.<br><br>둘 다 봤다. 종이 두 장, 같은 문장, 다른 필체.<br>저쪽이 낮게 말했다. 필체 하나가 눈에 익다고.<br><br>어디서 봤냐고는 안 물었다.<br>기록에 두 이름을 적었다. 이제 일어난 일이 됐다.`,
                failText:`혼자 봤다.<br><br>본 것은 분명한데 적을 수가 없다.<br>기억해 두는 수밖에 없다. 기억은 바뀐다.` },
      good:`기록이 됐다.`, bad:`기억만 남았다.`, flag:'twoWitnessed' },
    { l:'② 촛불 순서로 자리를 읽는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`밝기 순서로 짚었다. 여섯 번.<br><br>순서가 맞자 초들이 한 방향으로 기운다.<br>제단 뒤쪽이다. 벽에 금이 있다.<br><br>금 안쪽이 비어 있다. 두드려 보니 그렇다.`, flag:'wallGap',
      bad:`순서가 틀렸다.<br><br>초가 제각각 흔들린다.<br>하나가 꺼질 뻔했다.` }
  ] }
);

epicSlot('grave', 'spy').push(
{ title:'묘지 — 서로 새겨 준다',
  text:`가명을 새기려는데 손이 안 간다.<br><br>
    제 이름을 제가 새기면 무덤이 된다.<br>
    남이 새기면 기록이 된다.<br><br>
    밀정끼리 쓰는 규칙이다.`,
  opts:[
    { l:'① 동료와 서로 새긴다.', co:'witness',
      coOpt:{ ask:'서로의 가명을 새깁시다. 본명은 묻지 맙시다.', sec:60, p:1000,
        text:`제 이름을 제가 새기면 무덤이 된다.`,
        doneText:`서로 새겼다.<br><br>이쪽이 저쪽 가명을, 저쪽이 이쪽 가명을.<br>둘 다 본명은 안 물었다.<br><br>새기고 나서 나란히 섰다. 비석이 둘 늘었다.<br>둘 다 무덤이 아니라 기록이다.`,
                failText:`혼자 새겼다.<br><br>새기고 나서 한참 봤다.<br>무덤처럼 보였다.` },
      good:`기록이 됐다.`, bad:`무덤이 됐다.`, flag:'carvedEach' }
  ] }
);

epicSlot('tower', 'spy').push(
{ title:'탑 — 각도를 맞춘다',
  text:`관측대에 도구가 있다.<br><br>
    각도를 재는 것이다. 밀정도 이런 걸 쓴다.<br>
    거리와 방향을 알아야 보고가 된다.<br><br>
    균형을 맞춰야 정확하다.`,
  opts:[
    { l:'① 균형을 맞춘다.', mini:'scale', miniOpt:{ p:800, target:23, pool:[3,4,6,8,10,12] },
      good:`추를 맞춰 수평을 잡았다.<br><br>맞자 눈금이 읽힌다. 숲과 묘지 사이, 거리 팔백.<br>세 곳에서 재면 한 점이 나온다.<br><br>한 점을 적었다. 정확하다.`, flag:'triangulated',
      bad:`기울었다.<br><br>눈금이 안 맞는다. 재는 족족 다른 값이다.<br>적지 않았다.` },
    { l:'② 동료를 불러 대조한다.', co:'witness',
      coOpt:{ ask:'잰 값을 대조해 주십시오. 혼자 잰 것은 못 믿습니다.', sec:60, p:950,
        text:`혼자 잰 값은 틀릴 수 있다.`,
        doneText:`저쪽이 올라와 다시 쟀다.<br><br>같은 값이 나왔다. 두 번 같은 값이면 맞는 것이다.<br>둘 다 적었다.<br><br>적고 나서 아래를 봤다. 잰 자리에 아무것도 없다.<br>아무것도 없는데 거리가 나온다.`,
                failText:`혼자 쟀다. 값이 나왔다.<br><br>맞는지는 모르겠다. 적기는 적었다.<br>못 믿을 값이다.` },
      good:`대조했다.`, bad:`혼자 쟀다.`, flag:'checkedAngle' }
  ] }
);

epicSlot('lake', 'spy').push(
{ title:'거울 호수 — 양쪽에서 읽는다',
  text:`바위 글자가 양면이다.<br><br>
    한쪽에서 보면 절반, 반대쪽에서 보면 나머지 절반.<br>
    혼자 양쪽에 설 수는 없다.<br><br>
    밀정은 늘 한쪽에만 설 수 있다.`,
  opts:[
    { l:'① 동료를 반대편에 세운다.', co:'witness',
      coOpt:{ ask:'바위 반대편에서 읽어 주십시오. 동시에 읽읍시다.', sec:65, p:1000,
        text:`양쪽에서 봐야 전부 읽힌다.`,
        doneText:`동시에 읽었다. 한 줄씩 번갈아.<br><br>이어진다.<br><span style="color:#d4af37;">"양쪽 다 속이는 자가 한 명 있다. 이름은 새기지 않았다."</span><br><br>다 읽고 서로를 봤다. 아무 말도 안 했다.<br>밀정 둘이 할 수 있는 말이 없었다.`,
                failText:`혼자 읽었다. 절반뿐이다.<br><br><span style="color:#888;">"양쪽 다 속이는 자가..."</span><br>뒤가 없다. 뒤가 중요한 문장인데.` },
      good:`전부 읽었다.`, bad:`절반만 읽었다.`, flag:'bothSidesRead' }
  ] }
);

epicSlot('ruin', 'spy').push(
{ title:'폐허 — 벽 너머로 듣는다',
  text:`벽 하나가 얇다.<br><br>
    반대편 소리가 들린다. 밀정은 듣는 것으로 산다.<br>
    다만 혼자 들으면 방향을 모른다.<br><br>
    둘이 떨어져 들으면 어디서 나는지 잡힌다.`,
  opts:[
    { l:'① 동료와 떨어져 듣는다.', co:'sync',
      coOpt:{ ask:'저쪽 끝에서 들어 주십시오. 어느 쪽이 더 크게 들리는지 봅시다.', sec:60, p:950,
        text:`둘이 들으면 방향이 잡힌다.`,
        doneText:`양 끝에서 귀를 댔다.<br><br>저쪽이 더 크게 들린다고 한다. 이쪽은 흐리다.<br>소리가 나는 쪽은 저쪽 가까이다.<br><br>가 보니 벽이 아니라 문이었다. 벽처럼 발라 놓았다.<br>둘이 아니었으면 못 찾았다.`,
                failText:`혼자 여기저기 귀를 댔다.<br><br>어디서나 비슷하게 들린다.<br>방향을 못 잡았다.` },
      good:`찾았다.`, bad:`못 찾았다.`, flag:'wallDoorFound' },
    { l:'② 벽을 두드려 본다.', mini:'beat', miniOpt:{ p:750, total:10, gap:700 },
      good:`한 칸씩 두드렸다. 열 번.<br><br>세 번째와 일곱 번째가 다른 소리다.<br>안쪽이 비어 있다.<br><br>두 곳을 표시해 두고 물러났다.`, flag:'hollowWall',
      bad:`두드리는데 반대편에서 같은 박자로 돌아온다.<br><br>맞춰 주는 것이다.<br>멈췄다. 저쪽도 멈췄다.` }
  ] }
);

epicSlot('gate', 'spy').push(
{ title:'성문 — 순서대로 넘는다',
  text:`아치가 반쯤 막혔다.<br><br>
    한 명씩 지나야 한다. 순서가 있다.<br>
    먼저 간 쪽이 반대편을 확인하고 신호를 준다.<br><br>
    밀정 둘이 문을 지나는 법이다.`,
  opts:[
    { l:'① 동료를 먼저 보낸다.', co:'standin',
      coOpt:{ ask:'먼저 지나가서 반대편을 봐 주십시오. 안전하면 두 번 두드려 주십시오.', sec:55, p:950,
        text:`한쪽이 먼저 확인한다.`,
        doneText:`저쪽이 먼저 빠져나갔다.<br><br>한참 조용했다. 그러다 두 번 두드리는 소리가 났다.<br>이쪽도 지났다.<br><br>반대편에 서 있었다. 별일 없었다고 했다.<br>조용했던 건 확인하느라 그랬다고.`,
                failText:`혼자 지났다.<br><br>반대편이 안 보이는 채로 나갔다.<br>다행히 아무것도 없었다. 다행이라고 해 두기로 했다.` },
      good:`둘 다 지났다.`, bad:`혼자 지났다.`, flag:'orderPass' }
  ] }
);
;

