// index.html 에서 epic-spy-2.js 다음에 불러온다
// ==========================================

epicSlot('castle', 'spy').push(
{ title:'성 — 누구 편이냐고 묻는다',
  text:`복도에서 하나와 마주쳤다.<br><br>
    옷이 어느 쪽도 아니다. 아무 표식도 없다.<br>
    밀정은 표식 없는 상대를 제일 경계한다.<br><br>
    같은 처지일 수도 있어서.`,
  opts:[
    { l:'① 이쪽 표식을 먼저 보인다.', dc:13, kind:'bond', p:700,
      doom:{ title:'보인 표식', what:'표식이 기록되었습니다', dc:14, sec:70,
        text:`소매 안쪽을 보여 줬다. 이쪽 진영 표식이다.<br><br>상대가 고개를 끄덕인다. 그리고 적는다.<br>어디서 꺼냈는지 모를 종이에.<br><br>표식과 얼굴을 함께 적고 있다.<br>밀정이 제일 두려워하는 일이 지금 일어나고 있다.`,
        dieText:`먼저 보인 쪽이 지는 게임이다.<br><br>표식은 지울 수 있지만 적힌 것은 못 지운다.<br>이름 없이 사는 방법이 하나 줄었다.` },
      good:`보이려다 손을 멈췄다.<br><br>먼저 보이면 지는 게임이다. 배운 대로다.<br>대신 아무 표식도 없는 쪽 소매를 보였다.<br><br>상대도 같은 쪽을 보였다. 둘 다 아무것도 안 보인 셈이다.<br>지나쳤다.`, flag:'showedNothing' },
    { l:'② 말을 안 건다.', dc:11, kind:'hide', p:550,
      good:`눈을 안 마주치고 지나쳤다.<br><br>상대도 그랬다. 둘 다 같은 걸 배운 모양이다.<br>지나치고 나서 돌아봤다. 그쪽도 돌아봤다.<br><br>같은 순간에 돌아본 게 우스웠다.`, flag:'bothLooked',
      bad:`지나치는데 뒤에서 멈춘다.<br><br>발소리가 안 난다. 안 나는데 멈춘 게 느껴진다.<br>걸음을 빨리했다.`, poll:8 }
  ] },

{ title:'성 — 지워진 항목',
  text:`장부에 지운 자국이 있다.<br><br>
    한 줄만. 칼로 긁어냈다.<br>
    밀정은 지운 자국에서 읽는다. 지운 사람은 남기니까.<br><br>
    긁은 방향이 오른쪽에서 왼쪽이다.`,
  opts:[
    { l:'① 눌린 자국을 읽는다.', dc:14, kind:'gaze', p:800,
      good:`빛에 비스듬히 대 봤다.<br><br>눌린 자국이 남았다. 글자 모양이 잡힌다.<br>이름이다. 세 글자.<br><br>아는 이름은 아니다. 다만 어디서 본 필체였다.`, flag:'pressedName',
      bad:`비춰 봐도 안 보인다.<br><br>눌린 자국까지 문질러 냈다.<br>철저한 사람이 지웠다.`, poll:8 },
    { l:'② 다음 장을 본다.', dc:12, kind:'sense', p:650,
      good:`뒷장에 배어 있다. 잉크가 스몄다.<br><br>거꾸로 읽으면 읽힌다.<br>지운 항목은 사람이 아니라 날짜였다.<br><br>그 날짜에 무슨 일이 있었는지는 안 적혀 있다.`, flag:'bledThrough',
      bad:`뒷장이 없다.<br><br>뜯겨 나갔다. 뜯은 자리가 깨끗하다.<br>지운 쪽이 가져간 것이다.`, poll:7 }
  ] }
);

epicSlot('market', 'spy').push(
{ title:'장터 — 셋째 좌판',
  text:`값이 다른 좌판이 둘이었다.<br><br>
    세 번째를 찾으면 어느 쪽이 속이는지 안다.<br>
    밀정은 늘 셋을 본다. 둘로는 판단이 안 서니까.<br><br>
    세 번째 좌판이 안쪽에 있다.`,
  opts:[
    { l:'① 세 번째를 본다.', dc:13, kind:'gaze', p:750,
      good:`안쪽 좌판에서 같은 물건 값을 봤다.<br><br>둘 중 낮은 쪽과 같다.<br>높게 부르던 쪽이 속이고 있었다.<br><br>알고 나니 별것 아니었다. 다만 안 것이 중요하다.`, flag:'thirdStall',
      bad:`세 번째에는 그 물건이 없다.<br><br>없는 게 아니라 안 내놓는다.<br>판단이 안 섰다.`, poll:7 },
    { l:'② 높게 부른 쪽에 되묻는다.', dc:14, kind:'bond', p:800,
      doom:{ title:'되물은 값', what:'값이 이쪽에 매겨졌습니다', dc:14, sec:70,
        text:`왜 다르냐고 물었다.<br><br>주인이 처음으로 고개를 든다. 얼굴이 없다.<br><span style="color:#d4af37;">"묻는 쪽이 값을 정하시오."</span><br><br>정하라고 한다. 정하면 그게 값이 된다.<br>무엇의 값인지는 안 말해 준다. 이미 매겨지고 있다.`,
        dieText:`밀정은 묻는 사람이다.<br><br>여기서는 묻는 쪽이 대답하게 된다.<br>좌판에 값이 붙은 것이 하나 늘었다.` },
      good:`물으려다 그만뒀다.<br><br>여기서 묻는 건 위험하다. 묻는 순간 이쪽이 드러난다.<br>밀정은 묻지 않고 안다.<br><br>세 번째 좌판을 찾으러 갔다.`, flag:'didntAsk' }
  ] }
);

epicSlot('tower', 'spy').push(
{ title:'탑 — 기록을 남긴다',
  text:`관측대에 기록이 쌓여 있다.<br><br>
    앞서 온 사람들이 적은 것이다.<br>
    밀정은 기록에 자기 것을 보탠다. 그게 일이다.<br><br>
    마지막 장에 빈 줄이 있다.`,
  opts:[
    { l:'① 본 것만 적는다.', dc:12, p:650,
      good:`위치와 거리, 수를 적었다.<br><br>판단은 안 적었다. 판단은 다른 사람이 한다.<br>밀정은 사실만 적는다.<br><br>적고 나니 줄이 하나 늘었다. 다음 사람이 이어 적을 것이다.`, flag:'factsOnly',
      bad:`적는데 손이 판단을 쓴다.<br><br>본 것이 아니라 생각한 것이 나온다.<br>긁어 지웠다. 지운 자국이 남았다.`, poll:7 },
    { l:'② 앞선 기록을 전부 읽는다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'읽은 기록', what:'기록에 들어갔습니다', dc:14, sec:70,
        text:`처음부터 읽었다. 스물셋 명분이다.<br><br>전부 사실만 적었다. 판단은 없다.<br>마지막 줄만 다르다. 판단이 적혀 있다.<br><br><span style="color:#d4af37;">"읽은 자는 스물넷째가 된다."</span><br><br>읽었다. 이미 읽었다.`,
        dieText:`밀정은 기록하는 사람이다.<br><br>기록되는 쪽이 되면 할 수 있는 게 없다.<br>스물넷째 줄이 채워졌다.` },
      good:`세 장만 읽고 덮었다.<br><br>전부 읽으면 오래 걸리고, 오래 있으면 표가 난다.<br>필요한 것만 읽는다.<br><br>덮고 나서 마지막 장은 안 봤다. 보기 싫었다.`, flag:'readThree' }
  ] }
);

epicSlot('forest', 'spy').push(
{ title:'검은 숲 — 쫓기는 쪽',
  text:`뒤에 붙었다.<br><br>
    소리는 안 나는데 붙었다. 밀정은 붙은 걸 안다.<br>
    떼어 내는 방법이 몇 가지 있다.<br><br>
    전부 시간이 걸린다.`,
  opts:[
    { l:'① 원을 그려 뒤로 돈다.', dc:13, kind:'evade', p:750,
      good:`크게 돌아 뒤로 붙었다.<br><br>쫓던 것이 앞서간다. 이쪽 자국을 따라.<br>뒤에서 보니 사람 모양이다. 사람 걸음은 아니다.<br><br>반대로 걸었다. 안 돌아봤다.`, flag:'circledBehind',
      bad:`돌았는데 그쪽도 돈다.<br><br>같은 방향으로. 거리가 그대로다.<br>계속 걸었다.`, poll:8 },
    { l:'② 옷을 벗어 걸어 둔다.', dc:12, kind:'hide', p:700,
      good:`겉옷을 벗어 나뭇가지에 걸었다.<br><br>사람처럼 보인다. 어둠 속에서는 특히.<br>안쪽 옷만 입고 갔다. 진영이 바뀐 셈이다.<br><br>한참 뒤에 돌아보니 걸어 둔 옷 앞에 뭔가 서 있었다.`, flag:'decoyCoat',
      bad:`벗는데 안쪽 옷이 없다.<br><br>겹쳐 입은 줄 알았는데 한 벌이다.<br>다시 입었다.`, poll:8 }
  ] }
);

epicSlot('village', 'spy').push(
{ title:'빈 마을 — 닫힌 집',
  text:`하나뿐인 닫힌 문 앞이다.<br><br>
    밀정은 닫힌 것을 본다. 열린 스물둘보다 이쪽이 중요하다.<br>
    닫아 둔 데는 이유가 있다.<br><br>
    안에서 잠갔다. 걸쇠가 안쪽이다.`,
  opts:[
    { l:'① 창으로 들여다본다.', dc:13, kind:'gaze', p:750,
      good:`창틈에 눈을 댔다.<br><br>밥상이 없다. 스물둘 집에는 다 있는데 여기만 없다.<br>대신 벽에 금이 있다. 키를 잰 자국.<br><br>맨 위 금이 어른 키다. 그 위에 하나 더 있다.`, flag:'closedHouseIn',
      bad:`눈을 대자 안쪽이 어둡다.<br><br>어두운 게 아니라 막혀 있다. 창 안쪽에 뭔가 대 놓았다.<br>물러났다.`, poll:8 },
    { l:'② 걸쇠를 열어 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'안에서 잠근 문', what:'문이 안에서 열렸습니다', dc:14, sec:70,
        text:`칼을 넣어 걸쇠를 들었다.<br><br>걸린다. 다만 열리지 않는다. 다른 것이 잡고 있다.<br>당겼다. 저쪽도 당긴다.<br><br>안에서 여는 중이다. 이쪽이 연 게 아니다.<br>열리고 나면 들어가야 한다. 안 들어갈 수가 없다.`,
        dieText:`안에서 잠근 문은 안에서 열린다.<br><br>밖에서 할 수 있는 건 기다리는 것뿐이다.<br>스물셋 집이 전부 열려 있다. 이제는.` },
      good:`칼을 넣다가 뺐다.<br><br>안에서 잠근 문은 안 연다. 이유가 있으니 잠갔다.<br>밀정은 이유를 존중한다. 존중이 아니라 계산이다.<br><br>창으로만 보고 갔다.`, flag:'leftLatched' }
  ] }
);

epicSlot('grave', 'spy').push(
{ title:'묘지 — 세어 둔 수',
  text:`관리소 벽에 금이 있다.<br><br>
    묻은 수를 센 것이다. 스물셋.<br>
    밀정은 수를 믿지 않는다. 세는 사람이 있으니까.<br><br>
    세는 사람은 자기를 안 센다.`,
  opts:[
    { l:'① 세는 사람을 찾는다.', dc:14, kind:'sense', p:800,
      good:`금 옆에 이름이 없다. 센 사람 이름이.<br><br>도구에 손자국이 있다. 오래 쓴 자국.<br>세는 사람은 여기 있었다. 지금은 없다.<br><br>스물셋에 세는 사람은 안 들어간다. 그럼 스물넷이다.`, flag:'uncountedOne',
      bad:`찾는데 금이 하나 늘어난다.<br><br>스물넷. 방금 그어졌다.<br>주변에 아무도 없다.`, poll:9 },
    { l:'② 이쪽이 금을 하나 긋는다.', dc:12, p:650,
      doom:{ title:'그은 금', what:'세어졌습니다', dc:14, sec:70,
        text:`손톱으로 하나 그었다. 스물넷.<br><br>긋는 순간 손이 멈춘다. 금이 이쪽 것이 아니게 된다.<br>세는 게 아니라 세어진 것이다.<br><br>벽에서 손이 안 떨어진다.<br>세는 사람은 자기를 안 센다. 세면 세어진다.`,
        dieText:`금이 스물넷이 됐다.<br><br>세는 사람이 없어졌으니 다음에 세는 사람이 올 것이다.<br>스물다섯이 될 것이다.` },
      good:`그으려다 손을 내렸다.<br><br>세는 사람은 자기를 안 센다. 규칙이 그렇다.<br>규칙에는 이유가 있다.<br><br>스물셋으로 두고 나왔다.`, flag:'didntMark' }
  ] }
);

epicSlot('temple', 'spy').push(
{ title:'신전 — 벽 안쪽',
  text:`제단 뒤 벽에 금이 있다.<br><br>
    두드려 보니 비어 있다. 안쪽에 공간이 있다.<br>
    밀정은 비어 있는 벽을 안 지나친다.<br><br>
    다만 여는 데는 소리가 난다.`,
  opts:[
    { l:'① 조용히 연다.', dc:14, kind:'hide', p:800,
      good:`금을 따라 천천히 밀었다.<br><br>돌 한 장이 옆으로 움직인다. 소리가 거의 안 났다.<br>안쪽에 상자가 있다. 문서함이다.<br><br>안에 명단이 있다. 스물넷 이름, 스물셋에 줄.<br>남은 하나는 읽지 않았다.`, flag:'wallCache',
      bad:`미는데 소리가 난다.<br><br>돌이 갈리는 소리가 신전을 울린다.<br>멈췄다. 절반만 열렸다.`, poll:8 },
    { l:'② 그대로 둔다.', dc:11, p:550,
      good:`두드려 확인만 하고 물러났다.<br><br>비어 있다는 걸 아는 것으로 충분하다.<br>여는 건 다음 사람이 해도 된다.<br><br>벽에 작게 표식을 남겼다. 여기가 비었다고.`, flag:'markedWall',
      bad:`표식을 남기는데 안쪽에서 두드림이 돌아온다.<br><br>같은 자리를 같은 박자로.<br>손을 뗐다.`, poll:8 }
  ] }
);

epicSlot('lake', 'spy').push(
{ title:'거울 호수 — 비친 표식',
  text:`물에 비친 이쪽 소매에 표식이 있다.<br><br>
    실제 소매에는 없다. 지웠으니까.<br>
    비친 쪽에는 남아 있다.<br><br>
    밀정에게 지워지지 않는 표식은 사형 선고다.`,
  opts:[
    { l:'① 어느 쪽 표식인지 본다.', dc:13, kind:'gaze', p:750,
      good:`비친 것을 자세히 봤다.<br><br>이쪽 진영 것이다. 처음 쓰던 것.<br>바꾼 지 오래됐는데 물은 옛것을 기억한다.<br><br>물러났다. 비치지 않으면 없는 것이다.`, flag:'oldMark',
      bad:`보다 보니 표식이 바뀐다.<br><br>이쪽 것이었다가 저쪽 것이 된다.<br>번갈아 가며.`, poll:9 },
    { l:'② 물에 손을 넣어 지운다.', dc:14, p:800,
      doom:{ title:'지우려던 것', what:'저쪽 소매가 잡혔습니다', dc:14, sec:70,
        text:`손을 넣어 비친 소매를 문질렀다.<br><br>지워진다. 지워지는 만큼 이쪽 소매에 나타난다.<br>옮겨 온 것이다.<br><br>손을 빼려는데 저쪽이 소매를 잡는다.<br>표식을 돌려주려는 것이다. 받으면 안 되는데.`,
        dieText:`지운 표식은 없어지는 게 아니라 옮겨 간다.<br><br>옮길 데가 없으면 돌아온다.<br>물가에 밀정이 하나 서 있다. 소매에 표식이 있다.` },
      good:`손을 대려다 말았다.<br><br>비친 것을 지우면 이쪽에 생긴다.<br>거울은 옮기는 물건이지 지우는 물건이 아니다.<br><br>물러났다.`, flag:'leftReflection' }
  ] }
);

epicSlot('road', 'spy').push(
{ title:'끊긴 길 — 건너간 쪽',
  text:`안개 위에 발자국이 있다.<br><br>
    하나다. 건너간 사람이 하나뿐이라는 뜻이다.<br>
    성문 금과 맞는다. 나간 금도 하나였다.<br><br>
    같은 사람일 것이다.`,
  opts:[
    { l:'① 발자국을 대조한다.', dc:13, kind:'sense', p:750,
      good:`크기와 걸음 폭을 쟀다.<br><br>성문 안쪽 자국과 같다. 같은 사람이다.<br>들어와서 나갔다. 하나뿐인 그 사람.<br><br>나간 쪽 방향을 적었다. 돌아오지는 않았다.`, flag:'matchedPrints',
      bad:`재는데 크기가 이쪽과 같다.<br><br>걸음 폭도 같다.<br>재는 걸 그만뒀다.`, poll:9 },
    { l:'② 따라 건넌다.', dc:14, kind:'evade', p:800,
      doom:{ title:'따라간 자국', what:'자국이 늘지 않습니다', dc:14, sec:70,
        text:`같은 자리를 밟으며 건넜다.<br><br>안 빠진다. 다져진 자리다.<br>건너편에 닿아 돌아봤다.<br><br>자국이 하나다. 둘이어야 하는데 하나다.<br>밟은 자리에 이쪽 자국이 안 남았다. 건넌 걸로 안 쳐진다.`,
        dieText:`나간 자는 하나였다.<br><br>둘이 될 수는 없다.<br>먼저 나간 쪽이 남고, 나중은 안 센다.` },
      good:`발을 올렸다가 내렸다.<br><br>자국이 하나뿐인 게 걸렸다.<br>여럿이 건넜으면 여럿이 남았어야 한다.<br><br>안 건넜다. 밀정은 안 맞는 수를 안 넘긴다.`, flag:'didntFollow' }
  ] }
);

epicSlot('ruin', 'spy').push(
{ title:'폐허 — 발라 놓은 문',
  text:`벽처럼 발라 놓은 문이 있다.<br><br>
    밀정은 이런 걸 만든다. 그래서 알아본다.<br>
    바른 사람도 밀정이었을 것이다.<br><br>
    바르는 데는 이유가 있다.`,
  opts:[
    { l:'① 바른 방식을 본다.', dc:13, kind:'gaze', p:750,
      good:`흙을 바른 방향이 안쪽에서 밖이다.<br><br>안에 있던 사람이 발랐다는 뜻이다.<br>스스로 가뒀다.<br><br>열지 않았다. 스스로 가둔 문은 안 연다.`, flag:'sealedInside',
      bad:`보다 보니 바깥에서 바른 자국도 있다.<br><br>두 번 발랐다. 안에서 한 번, 밖에서 한 번.<br>손을 뗐다.`, poll:9 },
    { l:'② 긁어낸다.', dc:14, kind:'break', p:800,
      doom:{ title:'긁어낸 문', what:'안에서 밀고 있습니다', dc:14, sec:70,
        text:`흙을 긁어냈다. 문틀이 드러난다.<br><br>손잡이는 없다. 안쪽에만 있는 구조다.<br>긁는 동안 안에서 소리가 난다. 가까워진다.<br><br>마지막 흙이 떨어지자 문이 밀린다.<br>이쪽이 연 게 아니다. 열어 준 것이다.`,
        dieText:`발라 놓은 문은 열지 말라는 뜻이다.<br><br>안에서 바른 문은 특히 그렇다.<br>문이 다시 발라졌다. 이번에는 밖에서.` },
      good:`가장자리만 조금 긁었다.<br><br>문틀이 보인다. 그 이상은 안 긁었다.<br>발라 놓은 데는 이유가 있다.<br><br>도로 덮었다. 흙을 손으로 눌러서.`, flag:'recovered' }
  ] }
);

epicSlot('gate', 'spy').push(
{ title:'성문 — 마지막에 나간 자',
  text:`석상이 말한다.<br><br>
    <span style="color:#d4af37;">"들어온 자는 여럿, 나간 자는 하나."</span><br><br>
    밀정은 하나가 누구인지가 궁금하다.<br>
    이름이 아니라 방법이.`,
  opts:[
    { l:'① 어떻게 나갔냐고 묻는다.', dc:13, kind:'bond', p:750,
      good:`방법을 물었다. 이름은 안 물었다.<br><br>석상이 오래 생각한다.<br><span style="color:#d4af37;">"세지 않게 하였소."</span><br><br>세어지지 않으면 나갈 수 있다는 뜻이다.<br>세는 사람이 없어야 한다는 뜻이기도 하다.`, flag:'howLeft',
      bad:`묻자 석상이 이쪽을 본다.<br><br>대답 대신 세기 시작한다.<br>하나, 둘, 셋.`, poll:9 },
    { l:'② 이름을 묻는다.', dc:14, p:800,
      doom:{ title:'물은 이름', what:'이름이 대조되고 있습니다', dc:15, sec:70,
        text:`누구였냐고 물었다.<br><br>석상이 받침의 이름들을 읽기 시작한다. 스물넷.<br>스물셋은 지워졌고 하나가 남았다.<br><br>남은 이름을 읽는다. 읽고 나서 이쪽을 본다.<br>같은지 확인하는 것이다. 대답해야 한다.`,
        dieText:`밀정은 이름이 둘이라 하나도 없다.<br><br>없는 이름으로는 대답할 수 없다.<br>받침에 이름이 하나 새로 새겨졌다.` },
      good:`물으려다 그만뒀다.<br><br>이름을 물으면 이름을 대야 한다. 주고받는 것이니까.<br>밀정은 이름을 안 준다.<br><br>대신 고개만 숙였다. 석상도 숙였다.`, flag:'noNameAsked' }
  ] }
);
;

