epicSlot('market', 'spy').push(
{ title:'장터 — 안 파는 좌판',
  text:`좌판 하나에 물건이 없다.<br><br>
    주인만 앉아 있다. 고개를 숙이고.<br>
    밀정은 파는 게 없는 좌판이 왜 있는지 안다.<br><br>
    보려고 앉아 있는 것이다.`,
  opts:[
    { l:'① 지나가며 곁눈질한다.', dc:12, kind:'hide', p:650,
      good:`걸음을 안 늦추고 눈만 돌렸다.<br><br>무릎 위에 종이가 있다. 뭔가 적고 있다.<br>지나는 사람을 적는 것이다.<br><br>적히기 전에 지나갔다. 그러기를 바랐다.`, flag:'watcherStall',
      bad:`곁눈질하는데 고개가 든다.<br><br>눈이 마주쳤다. 아주 잠깐.<br>적는 소리가 났다.`, poll:8 },
    { l:'② 앞에 서서 본다.', dc:14, kind:'gaze', p:800,
      good:`마주 섰다. 한참.<br><br>주인이 적기를 멈춘다. 이쪽이 보는 동안은 못 적는다.<br>보는 쪽과 보이는 쪽이 정해져 있는 것이다.<br><br>물러나자 다시 적기 시작했다. 그래도 그만큼은 벌었다.`, flag:'staredBack',
      bad:`서 있는데 주변 좌판들이 전부 고개를 든다.<br><br>스물셋 개가 이쪽을 본다.<br>물러났다.`, poll:9 }
  ] }
);

epicSlot('castle', 'spy').push(
{ title:'성 — 옮겨 간 한 벌',
  text:`옷장을 다시 봤다.<br><br>
    이쪽 것 열둘, 저쪽 것 열하나였다.<br>
    지금은 열하나와 열둘이다. 바뀌었다.<br><br>
    한 벌이 옮겨 갔다.`,
  opts:[
    { l:'① 옮겨 간 옷을 찾는다.', dc:14, kind:'sense', p:800,
      good:`한 벌씩 소매 안쪽을 봤다.<br><br>표식을 뜯어낸 자국이 있는 게 하나 있다.<br>뜯고 반대쪽 표식을 달았다.<br><br>바꾼 사람이 여기서 바꿨다. 급하게.`, flag:'switchedCoat',
      bad:`찾는데 전부 뜯은 자국이 있다.<br><br>스물셋 벌 전부.<br>어느 것이 원래 무엇이었는지 모르겠다.`, poll:9 },
    { l:'② 이쪽 것도 바꿔 단다.', dc:13, kind:'hide', p:750,
      doom:{ title:'바꿔 단 표식', what:'어느 쪽도 아니게 됐습니다', dc:14, sec:70,
        text:`소매 표식을 뜯고 반대쪽 것을 달았다.<br><br>달고 나니 어느 쪽인지 모르겠다.<br>이쪽이었던 것도 저쪽이었던 것도 흐려진다.<br><br>옷장에 한 벌 더 걸려 있다. 아무 표식도 없는 것.<br>그게 맞는 것 같다. 손이 그쪽으로 간다.`,
        dieText:`밀정은 양쪽을 오간다. 오가는 동안은 어느 쪽에도 있다.<br><br>멈추면 어느 쪽에도 없다.<br>옷장에 표식 없는 옷이 두 벌이 됐다.` },
      good:`뜯으려다 손을 멈췄다.<br><br>여기서 바꾸면 돌아갈 데가 없어진다.<br>밀정은 돌아갈 곳을 하나는 남겨 둔다.<br><br>그대로 두고 나왔다.`, flag:'keptSide' }
  ] }
);

epicSlot('forest', 'spy').push(
{ title:'검은 숲 — 걸어 둔 옷',
  text:`나뭇가지에 옷이 걸려 있다.<br><br>
    미끼로 걸어 둔 것이다. 밀정이 쓰는 방식.<br>
    이쪽도 써 본 적이 있다.<br><br>
    다만 이건 오래됐다. 걸어 둔 사람은 안 돌아왔다.`,
  opts:[
    { l:'① 표식을 확인한다.', dc:12, kind:'gaze', p:700,
      good:`소매를 뒤집어 봤다.<br><br>표식이 없다. 뜯어낸 자국만 있다.<br>양쪽 다 버린 사람이었다.<br><br>걸어 두고 어디로 갔는지는 모르겠다.`, flag:'abandonedCoat',
      bad:`소매에 표식이 있다.<br><br>이쪽 것이다. 지금 쓰는 것과 같은 모양.<br>손을 뗐다.`, poll:9 },
    { l:'② 가져간다.', dc:13, p:700,
      good:`벗겨서 챙겼다. 한 벌 더 있으면 쓸 데가 있다.<br><br>가볍다. 오래 걸려 있어서 바랬다.<br>입지는 않았다. 개켜서 넣었다.<br><br>입으면 그 사람이 된다. 안 입는다.`, flag:'tookDecoy',
      bad:`벗기는데 무겁다.<br><br>빈 옷인데 무겁다.<br>놓고 물러났다.`, poll:8 }
  ] }
);

epicSlot('temple', 'spy').push(
{ title:'신전 — 읽지 않은 이름',
  text:`문서함 안에 명단이 있었다.<br><br>
    스물넷 이름, 스물셋에 줄. 남은 하나를 안 읽었다.<br>
    밀정은 안 읽는 쪽을 택할 줄 안다.<br><br>
    다만 안 읽은 것이 계속 걸린다.`,
  opts:[
    { l:'① 끝까지 안 읽는다.', dc:12, p:700,
      good:`문서함을 닫았다.<br><br>안 읽으면 모르는 채로 남는다. 모르는 게 나을 때가 있다.<br>밀정은 아는 것으로 죽는 직업이다.<br><br>닫고 벽을 도로 밀었다. 소리가 안 났다.`, flag:'neverRead' },
    { l:'② 읽는다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'남은 이름', what:'읽은 것이 대조되고 있습니다', dc:15, sec:70,
        text:`펴서 읽었다.<br><br>세 글자다. 아는 이름이다. 아주 잘 아는.<br>줄이 안 그어진 이유는 아직 안 끝났기 때문이다.<br><br>읽고 나니 줄이 그어지기 시작한다. 천천히.<br>읽는 것으로 끝난다는 걸 몰랐다.`,
        dieText:`명단은 읽으라고 있는 게 아니라 세라고 있는 것이다.<br><br>세는 것과 읽는 것은 다르다.<br>스물넷에 전부 줄이 그어졌다.` },
      good:`반쯤 펴다가 접었다.<br><br>세 글자 중 첫 글자만 봤다. 그것만으로 충분했다.<br>아는 글자였다.<br><br>접어서 도로 넣었다. 손이 떨렸다.`, flag:'halfRead' }
  ] }
);

epicSlot('village', 'spy').push(
{ title:'빈 마을 — 키를 잰 자국',
  text:`닫힌 집 창으로 본 것이 걸린다.<br><br>
    벽에 키를 잰 금이 있었다. 맨 위 금이 어른 키.<br>
    그 위에 하나 더 있었다.<br><br>
    어른보다 큰 아이는 없다.`,
  opts:[
    { l:'① 다른 집도 확인한다.', dc:13, kind:'sense', p:750,
      good:`열린 집들을 돌며 벽을 봤다.<br><br>스물둘 집 전부에 금이 있다. 맨 위가 어른 키.<br>그 위에 하나씩 더 있다. 전부.<br><br>같은 높이다. 사람 키가 아니라 표시다.`, flag:'heightMarks',
      bad:`보다 보니 금이 늘어난다.<br><br>맨 위가 점점 높아진다.<br>고개를 들다가 그만뒀다.`, poll:9 },
    { l:'② 이쪽 키를 재 본다.', dc:12, p:650,
      doom:{ title:'잰 키', what:'금이 그어졌습니다', dc:14, sec:70,
        text:`벽에 등을 대고 손으로 표시했다.<br><br>맨 위 금보다 조금 아래다. 어른 키에 못 미친다.<br>그런데 위쪽 금까지 자란다. 선 채로.<br><br>등이 벽에 붙는다. 키가 늘어난다.<br>집마다 금이 그렇게 생긴 것이다.`,
        dieText:`금은 자란 것을 기록한 것이 아니라<br>자라게 한 것이다.<br><br>스물셋 집에 금이 하나씩 더 생겼다.` },
      good:`등을 대려다 말았다.<br><br>여기서 키를 재면 재어진다.<br>세는 것도 재는 것도 여기서는 위험하다.<br><br>물러났다. 벽에서 멀리.`, flag:'didntMeasure' }
  ] }
);

epicSlot('tower', 'spy').push(
{ title:'탑 — 점을 확인한다',
  text:`세 곳에서 잰 값이 한 점을 가리킨다.<br><br>
    숲과 묘지 사이. 거리 팔백.<br>
    밀정의 일은 여기까지다. 위치를 잡는 것.<br><br>
    가 보는 건 다른 사람의 일이다.`,
  opts:[
    { l:'① 위치만 적고 내려간다.', dc:12, p:700,
      good:`적었다. 정확하게.<br><br>거리, 방향, 지형. 판단은 안 적었다.<br>기록에 한 줄 보탰다.<br><br>내려가면서 뒤를 안 봤다. 볼 것도 없었다.`, flag:'loggedPoint', flag2:true },
    { l:'② 망원으로 들여다본다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'들여다본 점', what:'저쪽이 마주 보고 있습니다', dc:15, sec:70,
        text:`도구를 맞춰 그 점을 봤다.<br><br>나무 사이에 빈터가 있다. 가운데 뭔가 서 있다.<br>사람 모양이다. 이쪽을 보고 있다.<br><br>팔백 걸음 거리에서 눈이 마주쳤다.<br>망원은 이쪽만 당겨 보는 도구가 아니다.`,
        dieText:`보는 쪽과 보이는 쪽은 같은 도구를 쓴다.<br><br>먼저 본 쪽이 먼저 보인다.<br>탑 위에 도구가 하나 남았다. 초점이 맞춰진 채로.` },
      good:`도구에 눈을 대기 전에 각도만 확인했다.<br><br>맞춰 놓고 안 봤다.<br>보면 보인다. 밀정이 제일 먼저 배우는 것이다.<br><br>도구를 돌려놓고 내려갔다.`, flag:'didntLook' }
  ] }
);

epicSlot('grave', 'spy').push(
{ title:'묘지 — 다음 사람에게',
  text:`관리소에 종이가 있다.<br><br>
    다음에 올 사람에게 남기는 것이다.<br>
    밀정은 늘 다음 사람을 상정한다.<br><br>
    자기가 못 나갈 것을 전제로 적는다.`,
  opts:[
    { l:'① 알아낸 것을 적는다.', dc:12, kind:'bond', p:750,
      good:`짧게 적었다.<br><br><span style="color:#d4af37;">"금은 세지 말 것. 키는 재지 말 것. 이름은 읽지 말 것."</span><br><br>왜인지는 안 적었다. 적으면 시험해 볼 테니까.<br>접어서 도구 아래 끼워 두었다.<br><br>다음 사람이 찾을 것이다. 밀정이라면.`, flag:'leftNote' },
    { l:'② 이쪽 가명을 적는다.', dc:11, p:650,
      good:`끝에 가명 하나를 적었다.<br><br>본명이 아니니 상관없다.<br>다음 사람이 누가 적었는지 알면 믿을 것이다.<br><br>가명은 그럴 때 쓰는 것이다.`, flag:'signedAlias',
      bad:`적는데 손이 본명을 쓴다.<br><br>두 글자에서 멈췄다. 긁어 지웠다.<br>지운 자국이 남았다. 밀정이 보면 읽을 것이다.`, poll:8 }
  ] }
);

epicSlot('lake', 'spy').push(
{ title:'거울 호수 — 둘 중 하나',
  text:`물에 비친 것이 이쪽을 본다.<br><br>
    바위 글자가 떠오른다.<br>
    <span style="color:#888;">"양쪽 다 속이는 자가 한 명 있다."</span><br><br>
    밀정은 그게 자기일 수 있다는 걸 안다.`,
  opts:[
    { l:'① 비친 것에게 묻는다.', dc:14, kind:'bond', p:800,
      good:`물었다. 너냐고.<br><br>비친 것이 입을 움직인다. 같은 말을 한다.<br>같은 순간에. 이쪽이 물은 것인지 저쪽이 물은 것인지 모르겠다.<br><br>대답은 안 왔다. 물은 쪽이 둘이라 그렇다.`, flag:'askedMirror',
      bad:`묻자 비친 것이 고개를 젓는다.<br><br>이쪽은 안 저었다.<br>물러났다.`, poll:9 },
    { l:'② 아무것도 안 한다.', dc:11, p:650,
      good:`한참 보다가 돌아섰다.<br><br>둘 중 하나가 속인다면 확인할 방법이 없다.<br>확인할 수 없는 건 안 다룬다.<br><br>밀정은 판단을 미루는 법을 안다. 미루는 게 답일 때가 있다.`, flag:'deferred',
      bad:`돌아서는데 물소리가 난다.<br><br>나오는 소리 같다.<br>걸음을 빨리했다.`, poll:8 }
  ] }
);

epicSlot('road', 'spy').push(
{ title:'끊긴 길 — 남은 쪽',
  text:`줄을 잡고 남은 사람이 있었다면.<br><br>
    건넌 쪽은 안 돌아온다. 남은 쪽은 계속 잡고 있다.<br>
    밀정 둘이 있으면 늘 한쪽이 남는다.<br><br>
    남는 쪽이 하는 일이 있다.`,
  opts:[
    { l:'① 표식을 하나 더 남긴다.', dc:12, p:700,
      good:`끊긴 자리 앞에 그었다.<br><br>양쪽이 절반씩 그은 경고 아래에.<br><span style="color:#d4af37;">"하나는 남을 것."</span><br><br>다음에 오는 둘이 읽을 것이다.<br>읽고 누가 남을지 정할 것이다.`, flag:'thirdWarning' },
    { l:'② 줄을 끊어 둔다.', dc:13, kind:'break', p:750,
      good:`걸려 있던 줄을 끊었다.<br><br>못 건너게 하는 것이다. 못 건너면 안 잃는다.<br>끊고 나니 마음이 편했다.<br><br>밀정이 사람을 살리는 방법은 대개 이런 식이다.`, flag:'cutRope',
      bad:`끊으려는데 줄이 안 끊어진다.<br><br>칼이 안 든다. 밧줄이 아닌 것 같다.<br>그만뒀다.`, poll:8 }
  ] }
);

epicSlot('ruin', 'spy').push(
{ title:'폐허 — 벽에 적는다',
  text:`회랑 벽이 넓다.<br><br>
    천장에 스물셋 줄이 있고 맨 위가 비어 있다.<br>
    밀정은 빈 줄을 보면 채우고 싶어진다.<br><br>
    채우는 게 일이라서 그렇다.`,
  opts:[
    { l:'① 안 채운다.', dc:12, p:700,
      good:`올려다보기만 했다.<br><br>스물셋. 비어 있는 자리는 비워 둔다.<br>채우면 채워진 쪽이 된다.<br><br>밀정은 세는 쪽에 있어야 한다. 세어지면 끝이다.`, flag:'leftBlank' },
    { l:'② 다른 벽에 적는다.', dc:12, kind:'bond', p:700,
      good:`천장 말고 옆벽에 적었다.<br><br>세는 자리가 아니라 남기는 자리에.<br><span style="color:#d4af37;">"스물셋까지만 셀 것."</span><br><br>다음에 오는 사람이 볼 것이다.<br>천장은 안 건드렸다.`, flag:'sideWall',
      bad:`적는데 옆벽이 천장과 이어진다.<br><br>적은 것이 위로 올라간다. 스물넷째 줄 자리로.<br>손으로 문질러 지웠다.`, poll:9 }
  ] }
);

epicSlot('gate', 'spy').push(
{ title:'성문 — 세지 않게 한다',
  text:`석상이 알려 준 방법이 있었다.<br><br>
    <span style="color:#888;">"세지 않게 하였소."</span><br><br>
    세어지지 않으면 나갈 수 있다.<br>
    다만 세는 것이 무엇인지는 안 알려 줬다.`,
  opts:[
    { l:'① 들어온 금을 지운다.', dc:14, kind:'break', p:800,
      good:`아치 안쪽 금 중에 이쪽이 그은 것을 긁어냈다.<br><br>지워진다. 스물넷으로 돌아갔다.<br>들어온 적이 없게 된 것이다.<br><br>나갈 때 세어지지 않으려면 들어온 적도 없어야 한다.<br>말이 되는지는 모르겠다. 다만 그렇게 했다.`, flag:'erasedEntry' },
    { l:'② 이름을 지운다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'지운 이름', what:'지울 것이 남지 않았습니다', dc:15, sec:70,
        text:`받침에 새겨진 것 중 이쪽 가명을 찾아 긁었다.<br><br>지워진다. 다음 가명도 지웠다. 그다음도.<br>쓰던 이름이 셋이었다. 전부 지웠다.<br><br>남은 게 본명뿐이다. 그것도 새겨져 있다.<br>긁는 손이 멈추지 않는다. 지우면 나갈 수 있다고 했으니까.`,
        dieText:`밀정은 이름이 여럿이라 하나도 없다고 한다.<br><br>여럿을 다 지우면 마지막 하나가 남는다.<br>그것까지 지우면 지운 사람도 없어진다.` },
      good:`가명 하나만 지웠다.<br><br>쓰던 것 중 제일 오래된 것으로.<br>나머지는 뒀다. 전부 지우면 남는 게 없다.<br><br>하나쯤은 남겨 둬야 돌아올 수 있다.`, flag:'erasedOneAlias' }
  ] }
);
;

