// ==========================================
// ★ 검사 확장 1/4
// index.html 에서 epic-spy-4.js 다음에 불러온다
// ==========================================

epicSlot('ruin', 'swordsman').push(
{ title:'폐허 — 부러진 칼',
  text:`돌 사이에 칼이 박혀 있다.<br><br>
    날 절반이 없다. 부러진 자리가 깨끗하다.<br>
    검사는 부러진 칼을 보면 어떻게 부러졌는지 안다.<br><br>
    이건 부러진 게 아니라 잘렸다.`,
  opts:[
    { l:'① 잘린 면을 본다.', dc:13, kind:'sense', p:700,
      good:`손끝으로 단면을 훑었다.<br><br>매끈하다. 한 번에 갔다.<br>칼을 자르려면 더 좋은 칼이 있어야 한다.<br><br>여기 어딘가에 그게 있다는 뜻이다.`, flag:'cutBlade',
      bad:`만지는데 손이 베인다.<br><br>부러진 칼에 베였다. 있을 수 없는 일이다.<br>피가 돌에 떨어졌다.`, poll:8 },
    { l:'② 뽑아 든다.', dc:12, kind:'break', p:650,
      good:`뽑았다. 반만 남은 칼이다.<br><br>가볍다. 쓰기는 어렵지만 던지기는 좋다.<br>허리에 찼다.<br><br>검사는 칼을 안 버린다. 반쪽이라도.`, flag:'halfBlade',
      bad:`뽑는데 안 나온다.<br><br>박힌 게 아니라 자란 것 같다. 돌에서.<br>세 번 당기고 놓았다.`, poll:7 }
  ] },

{ title:'폐허 — 벤 자국',
  text:`기둥에 자국이 있다.<br><br>
    칼자국이다. 하나가 아니라 여럿. 같은 높이에.<br>
    검사는 자국을 보면 몇 번 휘둘렀는지 안다.<br><br>
    스물셋 번이다.`,
  opts:[
    { l:'① 깊이를 재 본다.', dc:12, kind:'sense', p:650,
      good:`손가락을 넣어 봤다.<br><br>처음 것이 제일 깊고 뒤로 갈수록 얕다.<br>힘이 빠진 것이다. 스물셋 번을 휘두르면 그렇게 된다.<br><br>마지막 자국은 긁힌 정도다.`, flag:'fadingCuts',
      bad:`재는데 깊이가 똑같다.<br><br>스물셋 번 전부. 힘이 안 빠졌다.<br>사람이 휘두른 게 아니다.`, poll:8 },
    { l:'② 같은 자리를 벤다.', dc:13, kind:'break', p:700,
      good:`같은 높이를 한 번 그었다.<br><br>스물넷째 자국이 생겼다. 이쪽 것이 제일 얕다.<br>앞사람만 못하다.<br><br>그래도 그었다. 세어지는 것과 남기는 것은 다르다.`, flag:'addedCut',
      bad:`베는데 칼이 튄다.<br><br>기둥이 단단하다. 돌보다 단단하다.<br>손목이 울렸다.`, poll:8 }
  ] }
);

epicSlot('market', 'swordsman').push(
{ title:'장터 — 팔지 않는 칼',
  text:`좌판에 칼이 놓여 있다.<br><br>
    잘 만든 것이다. 검사는 보면 안다.<br>
    값이 안 붙어 있다.<br><br>
    주인이 손으로 덮고 있다.`,
  opts:[
    { l:'① 값을 묻는다.', dc:12, kind:'bond', p:650,
      good:`얼마냐고 물었다.<br><br>주인이 고개를 든다.<br><span style="color:#d4af37;">"쓸 사람이 오면 주려고 두었소."</span><br><br>손을 뗀다. 가져가라는 뜻이다.<br>들어 보니 무겁다. 손에는 맞는다.`, flag:'givenSword',
      bad:`묻자 손을 더 눌러 덮는다.<br><br>아직 아니라는 뜻이다.<br>물러났다.`, poll:7 },
    { l:'② 날만 본다.', dc:13, kind:'gaze', p:700,
      good:`덮은 손 사이로 날을 봤다.<br><br>이가 하나도 안 나갔다. 쓴 적이 없다.<br>쓴 적 없는 칼이 여기 있는 게 이상하다.<br><br>만든 사람이 쓸 일이 없었다는 뜻이다.`, flag:'unusedBlade',
      bad:`보는데 날에 이쪽이 비친다.<br><br>얼굴이 아니라 목이 비친다.<br>눈을 돌렸다.`, poll:9 }
  ] }
);

epicSlot('gate', 'swordsman').push(
{ title:'성문 — 막아섰던 자리',
  text:`아치 아래 바닥이 패어 있다.<br><br>
    두 발 자국이다. 오래 버틴 자리.<br>
    검사는 버틴 자국을 안다. 발끝에 힘을 주면 저렇게 된다.<br><br>
    한 사람이 여기서 오래 막아섰다.`,
  opts:[
    { l:'① 같은 자리에 선다.', dc:12, kind:'bond', p:700,
      good:`발을 맞춰 섰다. 자세가 잡힌다.<br><br>여기서 보면 길이 한눈에 들어온다.<br>막기 좋은 자리다. 고른 사람이 아는 사람이었다.<br><br>서 있으니 어깨가 무거웠다.`, flag:'stoodGuard',
      bad:`서는데 발이 안 맞는다.<br><br>자국이 이쪽보다 크다.<br>물러났다.`, poll:7 },
    { l:'② 얼마나 버텼는지 본다.', dc:13, kind:'sense', p:700,
      good:`패인 깊이를 봤다.<br><br>돌이 이만큼 패려면 한나절로는 안 된다.<br>여러 날이다.<br><br>혼자 여러 날을 막아섰다. 그러고도 스물셋이 들어왔다.`, flag:'longStand',
      bad:`보다 보니 자국이 셋이 된다.<br><br>둘이었는데 셋이다.<br>세어 보는 걸 그만뒀다.`, poll:8 }
  ] }
);

epicSlot('castle', 'swordsman').push(
{ title:'성 — 걸린 칼들',
  text:`벽에 칼이 걸려 있다.<br><br>
    스물셋 자루. 전부 날이 밖을 향해 있다.<br>
    검사는 칼 거는 법을 안다. 날은 안쪽으로 거는 것이다.<br><br>
    밖을 향하게 건 것은 꺼내 쓰려는 것이다.`,
  opts:[
    { l:'① 하나 뽑아 본다.', dc:12, kind:'break', p:650,
      good:`가운데 것을 뽑았다.<br><br>손에 맞는다. 무게도 길이도.<br>휘둘러 보니 익숙하다.<br><br>쓰던 사람 것이 아니라 쓸 사람 것으로 만들어졌다.`, flag:'tookWallBlade',
      bad:`뽑는데 옆것들이 흔들린다.<br><br>스물셋 자루가 동시에. 소리가 크다.<br>도로 걸었다.`, poll:8 },
    { l:'② 날의 방향을 돌린다.', dc:13, p:700,
      doom:{ title:'돌린 칼', what:'전부 이쪽을 향했습니다', dc:14, sec:70,
        text:`하나씩 돌려 날을 안쪽으로 걸었다.<br><br>스물둘까지 했다. 마지막 하나가 안 돌아간다.<br>억지로 돌렸다.<br><br>돌아가는 순간 앞의 스물둘이 도로 돌아간다.<br>전부 밖을 향한다. 밖은 이쪽이 서 있는 자리다.`,
        dieText:`칼을 어느 쪽으로 걸지는 거는 사람이 정한다.<br><br>여기서는 칼이 정한다.<br>스물넷 자루가 걸렸다. 전부 같은 쪽을 본다.` },
      good:`세 자루만 돌렸다.<br><br>돌리고 나니 나머지가 흔들린다. 그만뒀다.<br>남의 칼 거는 방식을 바꾸는 게 아니다.<br><br>돌린 셋도 도로 돌려놓았다.`, flag:'leftBlades' }
  ] }
);

epicSlot('forest', 'swordsman').push(
{ title:'검은 숲 — 벨 수 없는 것',
  text:`나뭇가지가 길을 막았다.<br><br>
    베면 되는데, 검사는 나무를 안 벤다.<br>
    벨 것과 안 벨 것을 가리는 게 검사의 일이다.<br><br>
    다만 이 가지는 방금 자랐다. 지나가려는데 자랐다.`,
  opts:[
    { l:'① 그래도 안 벤다.', dc:13, kind:'evade', p:700,
      good:`허리를 숙여 지났다.<br><br>가지가 더 내려온다. 더 숙였다.<br>기어서 지났다. 흙이 묻었다.<br><br>지나고 나서 돌아보니 가지가 올라가 있다.<br>안 베길 잘했다. 그런 느낌이 들었다.`, flag:'duckedUnder',
      bad:`숙이는데 아래도 막힌다.<br><br>뿌리가 올라왔다.<br>앞뒤가 막혔다.`, poll:8 },
    { l:'② 벤다.', dc:12, kind:'break', p:650,
      doom:{ title:'벤 가지', what:'나무가 전부 움직입니다', dc:14, sec:70,
        text:`한 번에 갔다. 잘 들었다.<br><br>가지가 떨어진다. 그리고 주변 나무가 전부 소리를 낸다.<br>바람 소리가 아니다.<br><br>가지가 사방에서 내려온다. 스물셋 그루가 동시에.<br>한 번 베었으면 전부 베어야 하는데, 팔이 하나다.`,
        dieText:`검사는 벨 것과 안 벨 것을 가린다.<br><br>여기서는 나무가 편이었다.<br>가지 하나를 벤 값이 컸다.` },
      good:`칼을 들었다가 내렸다.<br><br>가지가 방금 자랐다는 게 걸렸다.<br>자라는 것은 살아 있는 것이고, 살아 있는 것은 함부로 안 벤다.<br><br>돌아서 갔다. 멀었다.`, flag:'sparedBranch' }
  ] }
);

epicSlot('temple', 'swordsman').push(
{ title:'신전 — 칼을 두고 들어간다',
  text:`문 앞에 받침이 있다.<br><br>
    칼을 두고 들어가라는 자리다.<br>
    검사에게 칼을 두는 건 손을 두고 가는 것과 같다.<br><br>
    그래도 두는 게 예다.`,
  opts:[
    { l:'① 두고 들어간다.', dc:12, kind:'bond', p:700,
      good:`받침에 올려놓고 들어갔다.<br><br>손이 허전하다. 걸음이 어색하다.<br>제단 앞에 서니 그제야 편해졌다.<br><br>나올 때 칼이 그대로 있었다. 당연한데 안심했다.`, flag:'leftSword',
      bad:`두려는데 손이 안 펴진다.<br><br>평생 쥔 손이라 그렇다.<br>결국 차고 들어갔다.`, poll:7 },
    { l:'② 차고 들어간다.', dc:13, p:700,
      good:`그대로 들어갔다.<br><br>촛불이 전부 한 번 흔들린다. 바람은 없다.<br>알아본 것이다.<br><br>제단 앞에서 칼을 풀어 바닥에 놓았다.<br>받침이 아니어도 두면 두는 것이다.`, flag:'knelt',
      bad:`들어가자 촛불이 하나씩 꺼진다.<br><br>세 개쯤 꺼졌을 때 나왔다.<br>나오니 다시 켜졌다.`, poll:8 }
  ] }
);

epicSlot('village', 'swordsman').push(
{ title:'빈 마을 — 지킬 것이 없는 자리',
  text:`마을 가운데에 섰다.<br><br>
    검사는 지킬 것이 있어야 하는 직업이다.<br>
    지킬 사람이 없으면 서 있을 이유가 없다.<br><br>
    스물셋 집이 비어 있다.`,
  opts:[
    { l:'① 그래도 선다.', dc:12, kind:'bond', p:700,
      good:`가운데 서서 한 바퀴 돌아봤다.<br><br>지킬 것이 없어도 서 있는 게 검사다.<br>한참 섰다.<br><br>문 하나가 조금 열렸다. 열렸다가 닫혔다.<br>지킬 것이 아주 없지는 않은 모양이다.`, flag:'stoodAnyway',
      bad:`서 있는데 집들이 가까워진다.<br><br>둘러싸는 것 같다.<br>가장자리로 물러났다.`, poll:8 },
    { l:'② 한 집을 골라 지킨다.', dc:13, p:700,
      good:`닫힌 집 앞에 섰다.<br><br>스물둘은 열려 있고 하나만 닫혔다.<br>닫힌 데는 이유가 있고, 이유가 있으면 지킬 값이 있다.<br><br>한참 섰다. 아무 일도 안 일어났다. 그게 지킨 것이다.`, flag:'guardedOne',
      bad:`서 있는데 문이 안에서 밀린다.<br><br>열려는 게 아니라 확인하는 것 같다.<br>비켜 섰다.`, poll:9 }
  ] }
);

epicSlot('grave', 'swordsman').push(
{ title:'묘지 — 꽂힌 칼',
  text:`봉분 앞에 칼이 꽂혀 있다.<br><br>
    비석 대신이다. 검사의 무덤은 그렇게 표시한다.<br>
    스물셋 봉분에 칼이 하나뿐이다.<br><br>
    나머지는 검사가 아니었거나, 칼이 없었거나.`,
  opts:[
    { l:'① 칼을 확인한다.', dc:12, kind:'gaze', p:650,
      good:`가까이 가서 봤다.<br><br>날이 녹슬었다. 자루에 천이 감겨 있다. 손때가 묻었다.<br>오래 쓴 칼이다.<br><br>뽑지 않았다. 여기 꽂힌 칼은 뽑는 게 아니다.`, flag:'gravedSword',
      bad:`보다 보니 날에 자국이 있다.<br><br>스물셋 번 벤 자국. 기둥에서 본 것과 같다.<br>물러났다.`, poll:8 },
    { l:'② 이쪽 칼을 하나 꽂는다.', dc:13, kind:'bond', p:750,
      doom:{ title:'꽂은 칼', what:'자리가 정해졌습니다', dc:14, sec:70,
        text:`빈 봉분 앞에 꽂았다. 반쪽 칼을.<br><br>꽂는 순간 손이 안 떨어진다.<br>칼을 꽂은 자리는 누구 것인지 정해지는 자리다.<br><br>꽂은 쪽이 주인이 된다.<br>무릎이 꺾인다. 앉는 자세로.`,
        dieText:`검사의 무덤은 칼로 표시한다.<br><br>표시하면 그 자리가 된다.<br>봉분 앞에 칼이 둘이 됐다.` },
      good:`꽂으려다 손을 멈췄다.<br><br>여기 꽂으면 여기가 이쪽 자리가 된다.<br>아직 아니다.<br><br>대신 봉분 앞에 흙을 한 줌 덮었다. 그건 해도 되는 일이다.`, flag:'addedSoil' }
  ] }
);

epicSlot('tower', 'swordsman').push(
{ title:'탑 — 좁은 계단',
  text:`계단이 좁다.<br><br>
    칼을 휘두를 폭이 안 나온다.<br>
    검사에게 좁은 곳은 불리하다. 알면서도 올라간다.<br><br>
    내려오는 것이 있으면 피할 데가 없다.`,
  opts:[
    { l:'① 칼을 세워 들고 간다.', dc:12, kind:'evade', p:650,
      good:`날을 위로 세워 몸에 붙였다.<br><br>좁은 데서 칼을 드는 법이다. 휘두르는 게 아니라 찌른다.<br>배운 대로 올라갔다.<br><br>아무것도 안 내려왔다. 배운 게 안 쓰였다. 다행이다.`, flag:'narrowGuard',
      bad:`세우는데 천장에 걸린다.<br><br>생각보다 낮다. 눕혀 들었다.<br>눕히면 못 찌른다.`, poll:7 },
    { l:'② 칼을 두고 올라간다.', dc:13, p:700,
      good:`계단 아래에 세워 두고 올라갔다.<br><br>가볍다. 빠르다.<br>검사가 칼 없이 가는 건 계산이 선 경우다.<br><br>내려와서 챙겼다. 그대로 있었다.`, flag:'climbedLight',
      bad:`두고 올라가는데 계단 아래에서 소리가 난다.<br><br>칼이 쓰러지는 소리다. 세워 뒀는데.<br>서둘러 내려왔다.`, poll:8 }
  ] }
);

epicSlot('lake', 'swordsman').push(
{ title:'거울 호수 — 비친 자세',
  text:`물에 비친 것이 자세를 잡고 있다.<br><br>
    이쪽은 칼을 안 뽑았는데 저쪽은 뽑았다.<br>
    검사는 자세를 보면 실력을 안다.<br><br>
    저쪽 자세가 좋다. 이쪽보다.`,
  opts:[
    { l:'① 자세를 따라 잡는다.', dc:13, kind:'sense', p:750,
      good:`비친 자세를 흉내 냈다.<br><br>어깨 위치가 다르다. 팔꿈치가 더 붙었다.<br>고쳐 보니 확실히 낫다.<br><br>배웠다. 상대가 누구든 배울 건 배운다.`, flag:'copiedStance',
      bad:`따라 하는데 저쪽이 바꾼다.<br><br>맞추면 또 바꾼다.<br>계속 뒤처진다.`, poll:8 },
    { l:'② 칼을 뽑는다.', dc:14, kind:'break', p:800,
      doom:{ title:'뽑은 칼', what:'겨루게 됐습니다', dc:14, sec:70,
        text:`뽑았다. 저쪽도 이미 뽑고 있다.<br><br>겨루는 자세가 된다. 물을 사이에 두고.<br>먼저 움직이는 쪽이 진다는 걸 둘 다 안다.<br><br>팔이 저리다. 저쪽은 안 저린 것 같다.<br>기다리는 싸움에서 지는 쪽은 사람이다.`,
        dieText:`거울과 겨루면 진다.<br><br>지치는 쪽이 하나뿐이니까.<br>물가에 칼이 하나 떨어져 있다.` },
      good:`손을 자루에 댔다가 뗐다.<br><br>뽑으면 겨루게 된다. 겨루면 진다.<br>이길 수 없는 상대는 안 겨룬다. 검사가 오래 사는 법이다.<br><br>등을 돌렸다.`, flag:'didntDraw' }
  ] }
);

epicSlot('road', 'swordsman').push(
{ title:'끊긴 길 — 칼을 꽂아 본다',
  text:`안개가 평평하다.<br><br>
    깊이를 모르겠다. 검사는 칼로 잰다.<br>
    찔러 보면 바닥이 있는지 안다.<br><br>
    다만 찌른 것이 잡히면 곤란하다.`,
  opts:[
    { l:'① 반쪽 칼로 찔러 본다.', dc:12, kind:'sense', p:650,
      good:`부러진 칼을 거꾸로 잡고 찔렀다.<br><br>안 닿는다. 팔 길이만큼 넣어도 안 닿는다.<br>깊다.<br><br>뺐다. 칼이 젖어 있다. 물은 아니다.`, flag:'probedFog',
      bad:`찌르는데 뭔가 잡는다.<br><br>당겨진다. 놓았다.<br>반쪽 칼을 잃었다.`, poll:8 },
    { l:'② 좋은 칼로 찌른다.', dc:13, p:700,
      doom:{ title:'찌른 칼', what:'칼이 놓아지지 않습니다', dc:13, sec:65,
        text:`제대로 된 칼을 넣었다.<br><br>손목까지 들어갔다. 안 닿는다.<br>빼려는데 안 빠진다. 뭔가 물었다.<br><br>놓으면 되는데 손이 안 펴진다.<br>검사는 칼을 안 놓는다. 그렇게 배웠다. 그게 문제다.`,
        dieText:`칼을 놓을 줄 아는 검사가 오래 산다.<br><br>안 놓으면 칼과 같이 간다.<br>안개 위에 아무것도 안 남았다.` },
      good:`좋은 칼은 안 넣었다.<br><br>잃으면 안 되는 것으로 재는 게 아니다.<br>반쪽 칼로 쟀다.<br><br>검사는 도구를 아낀다. 목숨보다 먼저 아낀다.`, flag:'usedBroken' }
  ] }
);
;

// ---------- epic-sword-2.js ----------
// ==========================================
// ★ 검사 확장 2/4 — 동료 · 미니게임 중심
// index.html 에서 epic-sword-1.js 다음에 불러온다
// ==========================================

epicSlot('gate', 'swordsman').push(
{ title:'성문 — 둘이 막는다',
  text:`아치가 넓다.<br><br>
    혼자 막으면 옆으로 돈다. 둘이면 안 돈다.<br>
    검사는 옆을 맡길 사람이 필요하다.<br><br>
    등을 맡기는 것과 옆을 맡기는 것은 다르다.`,
  opts:[
    { l:'① 동료와 나란히 선다.', co:'sync',
      coOpt:{ ask:'옆에 서 주십시오. 제가 오른쪽을 맡겠습니다.', sec:60, p:1000,
        text:`혼자 막으면 옆으로 돈다.`,
        doneText:`나란히 섰다. 어깨가 닿는 거리로.<br><br>한참 있었다. 아무것도 안 왔다.<br>다만 안 온 게 아니라 못 온 것 같았다.<br><br>물러설 때 저쪽이 먼저 뒤로 갔다.<br>검사는 같이 선 사람의 걸음을 기억한다.`,
        failText:`혼자 섰다. 넓다.<br><br>옆이 비어 있는 게 내내 신경 쓰였다.<br>한참 서 있다가 물러났다.` },
      good:`둘이 막았다.`, bad:`혼자 섰다.`, flag:'shoulderGuard' },
    { l:'② 발자국에 맞춰 선다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`패인 자국 여섯을 순서대로 밟았다.<br><br>순서대로 밟으니 자세가 이어진다.<br>막아섰던 사람이 어떻게 움직였는지가 보인다.<br><br>좌우로 한 발씩. 뒤로는 한 번도 안 물러났다.`, flag:'guardPattern',
      bad:`순서가 엉켰다.<br><br>자국이 흐려진다. 밟은 만큼.<br>그만뒀다.` }
  ] }
);

epicSlot('castle', 'swordsman').push(
{ title:'성 — 겨루어 본다',
  text:`홀이 넓다.<br><br>
    검사는 겨루면서 배운다. 혼자 휘두르는 것으로는 안 는다.<br>
    상대가 있어야 한다.<br><br>
    다칠 각오는 서로 한다.`,
  opts:[
    { l:'① 동료와 겨룬다.', co:'sync',
      coOpt:{ ask:'한 합 겨루어 봅시다. 날은 세우지 않겠습니다.', sec:60, p:1000,
        text:`겨루면서 배운다.`,
        doneText:`날등으로 세 합을 했다.<br><br>두 번은 막았고 한 번은 맞았다.<br>어깨가 얼얼하다. 오랜만이다.<br><br>끝나고 서로 고개를 숙였다.<br>겨룬 상대는 등을 맡길 수 있다. 그게 검사가 사람을 믿는 방식이다.`,
        failText:`혼자 휘둘렀다. 허공에.<br><br>세 번 하고 그만뒀다.<br>겨룰 상대 없이 느는 재주가 아니다.` },
      good:`세 합 했다.`, bad:`혼자 휘둘렀다.`, flag:'sparred' },
    { l:'② 칼 무게를 견준다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,11] },
      good:`벽의 칼들을 재 봤다.<br><br>맞췄다. 스물셋 자루 중 셋만 무게가 다르다.<br>무거운 셋은 만든 사람이 다르다.<br><br>그 셋만 날이 안 상했다.`, flag:'weighedBlades',
      bad:`저울이 안 맞는다.<br><br>재는 족족 다르다. 같은 칼인데.<br>그만뒀다.` }
  ] }
);

epicSlot('ruin', 'swordsman').push(
{ title:'폐허 — 무너지는 쪽을 막는다',
  text:`기둥이 기운다.<br><br>
    한쪽이 받치면 한쪽이 지날 수 있다.<br>
    받치는 쪽은 못 지난다.<br><br>
    검사는 받치는 쪽을 자주 맡는다.`,
  opts:[
    { l:'① 동료를 먼저 보낸다.', co:'standin',
      coOpt:{ ask:'제가 받치겠습니다. 먼저 지나가십시오.', sec:60, p:1000,
        text:`받치는 쪽은 못 지난다.`,
        doneText:`어깨로 받쳤다. 무겁다.<br><br>저쪽이 기어서 지났다. 지나고 나서 반대쪽에서 받쳤다.<br>그 틈에 이쪽도 빠져나왔다.<br><br>둘 다 지났다. 혼자였으면 하나도 못 지났다.`,
        failText:`혼자 받치고 혼자 지나려 했다.<br><br>안 된다. 받치면 못 움직인다.<br>놓고 물러났다. 뒤에서 내려앉았다.` },
      good:`둘 다 지났다.`, bad:`돌아갔다.`, flag:'heldPillarSword' },
    { l:'② 벤 자국의 순서를 읽는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`깊은 것부터 얕은 것까지 일곱을 짚었다.<br><br>순서대로 이으니 움직인 자리가 보인다.<br>한 자리에서 안 움직였다. 스물셋 번을.<br><br>물러서지 않고 그 자리에서만 휘둘렀다.`, flag:'cutOrder',
      bad:`깊이가 뒤섞인다.<br><br>순서를 못 잡겠다.<br>다시 세어 보려다 그만뒀다.` }
  ] }
);

epicSlot('forest', 'swordsman').push(
{ title:'검은 숲 — 뒤를 맡긴다',
  text:`나무가 빽빽하다.<br><br>
    앞을 보면 뒤가 빈다. 검사는 뒤가 빈 걸 제일 싫어한다.<br>
    등을 맡길 사람이 있으면 다르다.<br><br>
    맡기는 데는 결심이 든다.`,
  opts:[
    { l:'① 등을 맞대고 간다.', co:'sync',
      coOpt:{ ask:'등을 맡기겠습니다. 뒤를 봐 주십시오.', sec:60, p:1000,
        text:`앞을 보면 뒤가 빈다.`,
        doneText:`등을 맞대고 천천히 움직였다.<br><br>저쪽이 두 번 멈췄다. 두 번 다 이쪽도 멈췄다.<br>멈춘 이유는 안 물었다.<br><br>빠져나왔다. 나와서야 저쪽이 말했다.<br>두 번 다 뭔가 따라왔다고.`,
        failText:`혼자 갔다. 뒤를 계속 돌아봤다.<br><br>돌아보는 만큼 앞이 늦다.<br>가지에 두 번 긁혔다.` },
      good:`빠져나왔다.`, bad:`긁혔다.`, flag:'backToBackSword' },
    { l:'② 발소리를 맞춰 간다.', mini:'beat', miniOpt:{ p:750, total:10, gap:730 },
      good:`열 걸음. 박자를 안 놓쳤다.<br><br>겹치니 하나로 들린다. 둘이 아니라 하나가 간다.<br>따라오던 것이 멈췄다.<br><br>수를 못 세면 못 따라온다.`, flag:'stepMatch',
      bad:`박자가 어긋났다.<br><br>둘로 들린다. 뒤에서 멈추는 소리가 났다.<br>서둘렀다.` }
  ] }
);

epicSlot('village', 'swordsman').push(
{ title:'빈 마을 — 교대로 선다',
  text:`지킬 자리가 있다.<br><br>
    혼자 서면 오래 못 간다. 둘이면 교대가 된다.<br>
    검사는 교대할 사람이 있어야 제대로 선다.<br><br>
    끝까지 혼자 서는 건 고집이지 지키는 게 아니다.`,
  opts:[
    { l:'① 동료와 교대한다.', co:'standin',
      coOpt:{ ask:'교대로 섭시다. 제가 먼저 서겠습니다.', sec:60, p:950,
        text:`혼자 서면 오래 못 간다.`,
        doneText:`먼저 섰다. 한참 있다 저쪽이 왔다.<br><br>말없이 자리를 바꿨다. 뒤에 앉아 쉬었다.<br>쉬는 동안 아무 일도 안 났다.<br><br>일어나 보니 저쪽이 같은 자세로 서 있었다.<br>가르친 적 없는데 똑같았다.`,
        failText:`혼자 섰다. 끝까지.<br><br>다리가 굳었다. 눈이 흐려진다.<br>고집이었다. 알면서도 그랬다.` },
      good:`교대했다.`, bad:`혼자 섰다.`, flag:'tookTurns' },
    { l:'② 문 앞의 자국을 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`닫힌 집 앞 자국 여섯을 순서대로 짚었다.<br><br>드나든 순서가 나온다. 들어간 것이 여섯, 나온 것이 다섯.<br>하나가 안 나왔다.<br><br>그래서 닫아 둔 것이다.`, flag:'doorOrder',
      bad:`자국이 겹쳐 있다.<br><br>순서를 못 잡겠다.<br>한참 보다가 물러났다.` }
  ] }
);

epicSlot('grave', 'swordsman').push(
{ title:'묘지 — 둘이 묻는다',
  text:`봉분 하나가 얕다.<br><br>
    제대로 안 묻혔다. 혼자 묻으면 이렇게 된다.<br>
    검사는 묻는 일을 여러 번 한다.<br><br>
    둘이면 제대로 묻을 수 있다.`,
  opts:[
    { l:'① 동료와 다시 묻는다.', co:'handoff',
      coOpt:{ ask:'얕습니다. 같이 덮읍시다.', sec:60, p:950,
        text:`혼자 묻으면 얕아진다.`,
        doneText:`둘이 흙을 날랐다.<br><br>한나절이 걸렸다. 손이 갈라졌다.<br>덮고 나서 나란히 섰다.<br><br>저쪽이 먼저 고개를 숙였다. 이쪽도 숙였다.<br>누구 것인지는 둘 다 모른다. 그래도 했다.`,
        failText:`혼자 덮었다. 절반쯤.<br><br>팔이 안 올라간다.<br>얕은 채로 두고 왔다.` },
      good:`제대로 묻었다.`, bad:`얕게 두었다.`, flag:'buriedTogether' }
  ] }
);

epicSlot('tower', 'swordsman').push(
{ title:'탑 — 좁은 데서 둘',
  text:`계단이 좁다.<br><br>
    둘이 나란히는 못 간다. 앞뒤로 가야 한다.<br>
    앞선 쪽이 위험하고 뒤가 안전하다.<br><br>
    검사는 앞을 맡는 직업이다.`,
  opts:[
    { l:'① 앞장선다.', co:'call',
      coOpt:{ ask:'제가 앞서겠습니다. 뒤를 봐 주십시오.', sec:55, p:950,
        text:`앞선 쪽이 위험하다.`,
        doneText:`앞장섰다. 칼을 세워 들고.<br><br>세 번쯤 올라가다 멈췄다. 뒤에서 잡는 손이 있었다.<br>돌아보니 저쪽이 위를 가리킨다.<br><br>위쪽 계단이 한 칸 없었다. 못 봤다.<br>뒤에 사람이 있으면 앞이 더 잘 보인다.`,
        failText:`혼자 올라갔다.<br><br>한 칸 없는 데를 못 봤다. 발이 빠졌다.<br>난간을 잡아서 안 떨어졌다. 아슬했다.` },
      good:`올라갔다.`, bad:`빠질 뻔했다.`, flag:'ledUp' },
    { l:'② 계단 수를 세며 간다.', mini:'beat', miniOpt:{ p:750, total:12, gap:680 },
      good:`열두 칸. 박자를 맞춰 디뎠다.<br><br>여덟째에서 소리가 달랐다. 그 칸만 비어 있다.<br>건너뛰었다.<br><br>세면서 올라가면 이런 걸 안다.`, flag:'countedStairs',
      bad:`세다가 놓쳤다.<br><br>몇 칸째인지 모르겠다. 다시 셌다.<br>아래에서부터 다시 셌다.` }
  ] }
);

epicSlot('lake', 'swordsman').push(
{ title:'거울 호수 — 둘이 서면',
  text:`물가에 둘이 서면 비친 것도 둘이다.<br><br>
    둘 다 칼을 뽑고 있다. 이쪽은 안 뽑았는데.<br>
    검사는 뽑힌 칼을 보면 겨눌 준비를 한다.<br><br>
    둘 다 그렇다면 더 위험하다.`,
  opts:[
    { l:'① 동료와 함께 등을 돌린다.', co:'sync',
      coOpt:{ ask:'동시에 등을 돌립시다. 하나 둘에 돌리십시오.', sec:60, p:1000,
        text:`하나만 돌리면 남은 쪽이 겨뤄야 한다.`,
        doneText:`하나 둘에 같이 돌았다.<br><br>등 뒤에서 물소리가 났다. 둘이 동시에 들어가는 소리.<br>안 돌아봤다. 둘 다.<br><br>한참 걷고 나서 저쪽이 말했다.<br>돌리기 전에 저쪽 칼이 움직였다고. 이쪽은 못 봤다.`,
        failText:`혼자 돌았다.<br><br>남은 쪽이 있는지 없는지 모르겠다.<br>안 돌아봤다.` },
      good:`둘 다 돌았다.`, bad:`혼자 돌았다.`, flag:'turnedTogether' }
  ] }
);

epicSlot('temple', 'swordsman').push(
{ title:'신전 — 서로 칼을 맡긴다',
  text:`칼을 두고 들어가야 한다.<br><br>
    두고 들어가면 누가 가져갈지 모른다.<br>
    서로 맡기면 다르다. 하나가 들어가고 하나가 지킨다.<br><br>
    검사끼리 하는 방식이다.`,
  opts:[
    { l:'① 동료에게 맡긴다.', co:'standin',
      coOpt:{ ask:'제 칼을 맡아 주십시오. 다녀오겠습니다.', sec:55, p:950,
        text:`맡길 사람이 있으면 두고 갈 수 있다.`,
        doneText:`칼을 건넸다. 저쪽이 두 자루를 들고 문 앞에 섰다.<br><br>들어갔다. 손이 허전한데 불안하지 않았다.<br>나와서 받았다. 따뜻했다. 쥐고 있어서.<br><br>검사가 남의 칼을 쥐고 있는 건 드문 일이다.<br>드문 일을 해 준 셈이다.`,
        failText:`받침에 두고 들어갔다.<br><br>내내 신경 쓰였다. 제단 앞에서도.<br>나와 보니 그대로 있었다. 그래도 신경 쓰였던 건 사실이다.` },
      good:`맡겼다.`, bad:`두고 갔다.`, flag:'entrustedBlade' },
    { l:'② 촛불 앞에서 날을 본다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`촛불에 비춰 날을 여섯 방향으로 돌렸다.<br><br>순서대로 보니 이가 나간 자리가 보인다. 세 군데.<br>세 군데 다 같은 각도다.<br><br>같은 것을 세 번 벤 것이다. 아주 단단한 것을.`, flag:'bladeNicks',
      bad:`돌리다 놓쳤다.<br><br>날이 촛불을 스친다. 불이 한 번 꺼졌다 켜졌다.<br>칼을 거뒀다.` }
  ] }
);

epicSlot('market', 'swordsman').push(
{ title:'장터 — 날을 간다',
  text:`좌판에 숫돌이 있다.<br><br>
    검사는 칼을 간다. 하루도 안 거르는 사람도 있다.<br>
    가는 데는 박자가 있다.<br><br>
    박자가 맞아야 날이 고르게 선다.`,
  opts:[
    { l:'① 간다.', mini:'beat', miniOpt:{ p:800, total:12, gap:640 },
      good:`열두 번. 같은 힘, 같은 각도로 밀었다.<br><br>날이 섰다. 손톱에 대 보니 문다.<br>좌판 주인이 고개를 든다. 가는 걸 보고 있었다.<br><br>고개를 끄덕인다. 제대로 갈았다는 뜻이다.`, flag:'sharpened',
      bad:`각도가 흔들렸다.<br><br>날이 한쪽만 섰다. 오히려 못 쓰게 됐다.<br>다시 갈아야 한다.` },
    { l:'② 동료 칼도 같이 간다.', co:'handoff',
      coOpt:{ ask:'숫돌이 있습니다. 칼을 주시면 같이 갈겠습니다.', sec:55, p:900,
        text:`남의 칼을 가는 건 믿는다는 뜻이다.`,
        doneText:`두 자루를 나란히 갈았다.<br><br>남의 칼은 조심스럽다. 손버릇이 다르니까.<br>갈면서 그 사람 쓰는 법을 알게 된다.<br><br>돌려주니 손톱에 대 본다. 고개를 끄덕인다.<br>검사끼리 할 수 있는 제일 큰 인사다.`,
        failText:`이쪽 것만 갈았다.<br><br>숫돌이 하나뿐이라 오래 걸렸다.<br>다 갈고 나니 손이 아렸다.` },
      good:`둘 다 갈았다.`, bad:`하나만 갈았다.`, flag:'sharpenedBoth' }
  ] }
);

epicSlot('road', 'swordsman').push(
{ title:'끊긴 길 — 칼을 걸친다',
  text:`끊긴 폭이 좁은 데가 있다.<br><br>
    칼을 걸치면 발판이 된다. 한 사람이 밟고 지날 만큼.<br>
    다만 밟는 동안 누가 잡고 있어야 한다.<br><br>
    잡는 쪽이 놓으면 끝이다.`,
  opts:[
    { l:'① 동료가 잡아 준다.', co:'sync',
      coOpt:{ ask:'칼을 걸치겠습니다. 자루를 잡아 주십시오.', sec:60, p:1000,
        text:`잡는 쪽이 놓으면 끝이다.`,
        doneText:`칼을 걸쳤다. 저쪽이 자루를 밟고 눌렀다.<br><br>밟고 건넜다. 두 걸음. 짧은데 길었다.<br>건너서 반대쪽을 눌렀다. 저쪽도 건넜다.<br><br>칼을 뽑아 보니 휘어 있다. 조금.<br>펴면 된다. 사람은 못 편다.`,
        failText:`혼자 걸치고 밟았다.<br><br>한 걸음에 칼이 미끄러진다. 물러났다.<br>칼만 잃을 뻔했다.` },
      good:`둘 다 건넜다.`, bad:`못 건넜다.`, flag:'bladeBridge' },
    { l:'② 겨눠 던져 걸친다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`반쪽 칼을 던져 반대편 틈에 박았다. 두 번 만에.<br><br>줄을 걸 자리가 생겼다.<br>검사는 던지는 것도 배운다. 던질 일이 없기를 바라면서.`, flag:'thrownBlade',
      bad:`세 번 다 빗나갔다.<br><br>안개로 떨어졌다. 소리가 안 났다.<br>반쪽 칼을 잃었다.` }
  ] }
);
;

