epicSlot('castle', 'swordsman').push(
{ title:'성 — 세 자루',
  text:`무게가 다른 칼이 셋 있었다.<br><br>
    만든 사람이 다르고 날이 안 상했다.<br>
    검사는 안 상한 칼을 의심한다.<br><br>
    쓰였는데 안 상했거나, 안 쓰였거나.`,
  opts:[
    { l:'① 자루를 살핀다.', dc:13, kind:'sense', p:750,
      good:`손잡이 천을 풀어 봤다.<br><br>안쪽에 글자가 있다. 세 자루 다 같은 글자.<br>이름이 아니라 숫자다. 스물하나, 스물둘, 스물셋.<br><br>스물넷째는 없다. 만들다 말았거나, 쓰이고 있거나.`, flag:'numberedThree',
      bad:`푸는데 천이 안 풀린다.<br><br>감긴 게 아니라 붙어 있다.<br>손을 뗐다.`, poll:8 },
    { l:'② 스물넷째를 찾는다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'찾은 칼', what:'손이 맞춰졌습니다', dc:14, sec:70,
        text:`벽 아래 상자에 하나 더 있다.<br><br>천이 안 감겼다. 자루가 맨살이다.<br>쥐니까 맞는다. 다른 셋보다 훨씬.<br><br>손 모양대로 파여 있다. 이쪽 손 모양대로.<br>만든 사람이 이 손을 재고 만들었다. 언제 쟀는지 모르겠다.`,
        dieText:`스물넷째 칼에는 주인이 정해져 있었다.<br><br>쥐면 주인이 된다.<br>벽에 칼이 스물넷 자루가 됐다.` },
      good:`상자를 열다가 닫았다.<br><br>안에 하나 더 있는 게 보인다. 천이 안 감긴 자루.<br>맨 자루는 쥐면 안 된다. 손자국이 남는다.<br><br>닫고 물러났다. 셋으로 충분하다.`, flag:'leftFourth' }
  ] },

{ title:'성 — 겨룬 자리',
  text:`홀 바닥에 자국이 있다.<br><br>
    둘이 겨룬 자국이다. 발이 움직인 폭이 보인다.<br>
    검사는 겨룬 자리를 읽는다.<br><br>
    한쪽은 계속 물러났고 한쪽은 안 물러났다.`,
  opts:[
    { l:'① 물러난 쪽을 따라간다.', dc:13, kind:'sense', p:750,
      good:`물러난 자국을 따라갔다. 벽까지 간다.<br><br>벽 앞에서 자국이 멎는다. 더 물러날 데가 없었다.<br>거기서 자국이 사라진다. 쓰러진 자국은 없다.<br><br>벽을 두드려 봤다. 비어 있다.`, flag:'retreatWall',
      bad:`따라가는데 자국이 늘어난다.<br><br>물러난 자국이 계속 생긴다.<br>벽에 안 닿는다.`, poll:9 },
    { l:'② 안 물러난 쪽 자리에 선다.', dc:12, kind:'bond', p:700,
      good:`발을 맞춰 섰다. 한 자리에서 안 움직인 쪽이다.<br><br>여기서 보면 홀 전체가 보인다.<br>물러날 이유가 없는 자리였다.<br><br>이긴 게 아니라 질 수 없는 자리를 잡은 것이다.`, flag:'winningSpot',
      bad:`서는데 발이 안 맞는다.<br><br>자국이 이쪽보다 크다. 훨씬.<br>물러났다.`, poll:8 }
  ] }
);

epicSlot('market', 'swordsman').push(
{ title:'장터 — 값이 매겨진 칼',
  text:`다른 좌판에 칼이 있다.<br><br>
    이번엔 값이 붙어 있다. 싸다. 너무 싸다.<br>
    검사는 싼 칼을 의심한다.<br><br>
    좋은 칼이 싸게 나오는 데는 이유가 있다.`,
  opts:[
    { l:'① 이유를 묻는다.', dc:12, kind:'bond', p:700,
      good:`왜 싸냐고 물었다.<br><br>주인이 고개를 든다.<br><span style="color:#d4af37;">"돌아온 것이오."</span><br><br>팔았다가 돌아왔다는 뜻이다. 주인이 안 돌아오고.<br>사지 않았다.`, flag:'returnedBlade',
      bad:`묻자 값이 더 내려간다.<br><br>말없이 손가락으로 표시한다. 절반.<br>물러났다.`, poll:8 },
    { l:'② 산다.', dc:13, p:750,
      doom:{ title:'산 칼', what:'전 주인이 찾아왔습니다', dc:14, sec:70,
        text:`값을 치르고 받았다.<br><br>좋다. 이 값에 이런 칼은 없다.<br>허리에 찼다. 무게가 익는다.<br><br>밤에 자루가 움직인다. 쥐는 손이 있는 것처럼.<br>돌아온 칼은 주인도 데려온다. 값이 싼 이유였다.`,
        dieText:`검사는 칼을 고를 때 값을 안 본다.<br><br>값이 싸다는 건 앞사람이 못 지켰다는 뜻이다.<br>좌판에 칼이 다시 놓였다. 값이 더 내려갔다.` },
      good:`값을 묻고 물러났다.<br><br>싼 데는 이유가 있고, 이유를 모르면 안 산다.<br>검사는 남의 칼을 안 받는다.<br><br>쓰던 것을 계속 썼다.`, flag:'refusedCheap' }
  ] }
);

epicSlot('forest', 'swordsman').push(
{ title:'검은 숲 — 벤 자리가 아무는 나무',
  text:`나무에 자국이 있다.<br><br>
    벤 자국인데 아물고 있다. 살처럼.<br>
    검사는 벤 것이 어떻게 되는지 안다. 나무는 안 아문다.<br><br>
    아무는 것은 나무가 아니다.`,
  opts:[
    { l:'① 아문 자리를 만진다.', dc:12, kind:'sense', p:700,
      good:`손을 댔다. 따뜻하다.<br><br>겉은 나무인데 안이 따뜻하다.<br>벤 사람이 알고 벴는지는 모르겠다.<br><br>손을 뗐다. 이 숲의 나무는 안 벤다. 확실해졌다.`, flag:'warmScar',
      bad:`만지자 자국이 움직인다.<br><br>벌어진다. 안쪽이 보인다.<br>급히 물러났다.`, poll:9 },
    { l:'② 같은 자리를 다시 벤다.', dc:14, kind:'break', p:800,
      doom:{ title:'다시 벤 자리', what:'벤 만큼 돌아왔습니다', dc:14, sec:70,
        text:`아문 자리를 그었다. 한 번에.<br><br>벌어진다. 피가 아니라 수액이 나온다. 따뜻하다.<br>그리고 어깨가 아프다. 벤 적이 없는데.<br><br>옷을 걷어 보니 같은 자리에 같은 길이로 벌어져 있다.<br>나무를 벤 만큼 이쪽이 베인다.`,
        dieText:`검사는 벨 것과 안 벨 것을 가린다.<br><br>여기서는 나무가 편이라고, 누가 말해 줬어야 했다.<br>말해 줄 사람이 없었다.` },
      good:`칼을 들었다가 내렸다.<br><br>아무는 것은 살아 있는 것이다.<br>살아 있는 것은 함부로 안 벤다. 두 번째다.<br><br>이번엔 망설이지도 않았다.`, flag:'sparedAgain' }
  ] }
);

epicSlot('village', 'swordsman').push(
{ title:'빈 마을 — 안 나온 하나',
  text:`들어간 것이 여섯, 나온 것이 다섯이었다.<br><br>
    하나가 안 나왔다. 그래서 문을 닫았다.<br>
    검사는 안 나온 하나를 생각한다.<br><br>
    지키는 일에는 그게 따라붙는다.`,
  opts:[
    { l:'① 문 앞을 지킨다.', dc:12, kind:'bond', p:750,
      good:`문 앞에 섰다. 칼을 안 뽑고.<br><br>안에서 뭐가 나오든 나오는 것은 나오게 두고,<br>안 나오는 것은 안 나오게 둔다.<br><br>한참 섰다. 아무것도 안 나왔다.<br>지킨 것이다. 지켰다고 하기로 했다.`, flag:'guardedDoor',
      bad:`서 있는데 안에서 문을 두드린다.<br><br>나가려는 게 아니라 확인하는 소리다.<br>대답 안 했다.`, poll:9 },
    { l:'② 안 나온 하나를 부른다.', dc:13, kind:'bond', p:750,
      doom:{ title:'부른 하나', what:'대답이 왔습니다', dc:14, sec:70,
        text:`문에 대고 불렀다. 나오라고.<br><br>대답이 온다. 나가겠다고 한다.<br>다만 목소리가 문 안쪽이 아니라 뒤에서 난다.<br><br>돌아보니 마당이다. 아무도 없다.<br>안 나온 하나는 문 안에 있는 게 아니었다.`,
        dieText:`불렀으니 왔다.<br><br>부른 사람이 책임진다.<br>마을에 나온 것이 여섯이 됐다.` },
      good:`부르려다 입을 다물었다.<br><br>안 나온 데는 이유가 있다. 부르면 나온다.<br>나오게 하는 게 지키는 건 아니다.<br><br>문 앞에 그냥 섰다.`, flag:'didntCall' }
  ] }
);

epicSlot('grave', 'swordsman').push(
{ title:'묘지 — 칼을 뽑아 달라는 자리',
  text:`꽂힌 칼이 기울어 있다.<br><br>
    흙이 무너져 뽑힐 것 같다.<br>
    검사는 꽂힌 칼을 안 뽑는다. 다만 넘어지게 두지도 않는다.<br><br>
    바로 세우려면 한 번 뽑아야 한다.`,
  opts:[
    { l:'① 뽑았다 다시 꽂는다.', dc:13, kind:'break', p:750,
      good:`뽑았다. 흙을 다져 넣고 다시 꽂았다.<br><br>똑바로 섰다. 뽑은 시간이 짧아서 괜찮을 것이다.<br>그렇게 믿기로 했다.<br><br>손을 떼니 그대로 섰다.`, flag:'resetGrave',
      bad:`뽑는데 안 나온다.<br><br>기울었는데 단단하다.<br>흙만 더 덮었다.`, poll:8 },
    { l:'② 흙만 더 덮는다.', dc:11, p:650,
      good:`뽑지 않고 주변에 흙을 쌓았다.<br><br>기울기는 그대로다. 다만 안 넘어진다.<br>검사는 남의 칼을 안 뽑는다. 세우는 것보다 그게 먼저다.<br><br>손으로 눌러 다졌다.`, flag:'propped',
      bad:`쌓는데 흙이 흘러내린다.<br><br>쌓는 만큼 흘러내린다.<br>몇 번 하고 그만뒀다.`, poll:7 }
  ] }
);

epicSlot('temple', 'swordsman').push(
{ title:'신전 — 세 번 벤 것',
  text:`날에 이가 나간 자리가 셋이었다.<br><br>
    같은 각도로 세 번. 아주 단단한 것을 벴다.<br>
    검사는 자기 칼 이력을 안다.<br><br>
    셋 중 둘은 기억나는데 하나가 안 난다.`,
  opts:[
    { l:'① 기억을 더듬는다.', dc:13, kind:'gaze', p:750,
      good:`촛불 앞에서 오래 봤다.<br><br>둘은 안다. 언제 어디서 무엇을 벴는지.<br>셋째는 각도가 다르다. 위에서 아래가 아니라 아래에서 위다.<br><br>올려 벤 적이 없다. 이쪽 팔로는.`, flag:'thirdNick',
      bad:`더듬다 보니 둘도 흐려진다.<br><br>언제였는지, 무엇이었는지.<br>생각을 그만뒀다.`, poll:9 },
    { l:'② 제단에 칼을 올린다.', dc:12, kind:'bond', p:700,
      good:`날을 위로 해서 올려놓았다.<br><br>촛불이 날에 비친다. 스물셋 개가 한 줄로.<br>한참 봤다.<br><br>내려서 다시 찼다. 이가 나간 자리가 조금 덜해 보였다.<br>기분 탓일 것이다.`, flag:'bladeOnAltar',
      bad:`올리는 순간 촛불이 전부 흔들린다.<br><br>날에 비친 것이 스물넷이 된다.<br>거뒀다.`, poll:8 }
  ] }
);

epicSlot('tower', 'swordsman').push(
{ title:'탑 — 비어 있던 계단',
  text:`여덟째 칸이 없었다.<br><br>
    부서진 게 아니라 처음부터 없다. 단면이 깨끗하다.<br>
    검사는 잘린 면을 안다.<br><br>
    이것도 잘렸다. 폐허의 칼처럼.`,
  opts:[
    { l:'① 단면을 확인한다.', dc:13, kind:'sense', p:750,
      good:`손을 대 봤다. 매끈하다.<br><br>돌을 이렇게 자르려면 칼로는 안 된다.<br>그런데 칼자국이다. 폭이 맞는다.<br><br>스물셋 번 벤 자국과 같은 폭이다.`, flag:'cutStair',
      bad:`만지는데 단면이 차다.<br><br>돌인데 쇠처럼 차다.<br>손을 뗐다.`, poll:8 },
    { l:'② 여기서 벤 자세를 잡아 본다.', dc:14, kind:'bond', p:800,
      doom:{ title:'잡은 자세', what:'팔이 움직였습니다', dc:14, sec:70,
        text:`계단 아래 서서 자세를 잡았다.<br><br>여기서 위로 올려 베면 저 각도가 나온다.<br>해 보려고 팔을 들었다.<br><br>팔이 혼자 움직인다. 배운 적 없는 궤적으로.<br>한 번 긋고 나서야 멈췄다. 계단이 하나 더 없어졌다.`,
        dieText:`자세는 몸이 기억한다.<br><br>남의 자세를 잡으면 남의 몸이 기억한다.<br>계단이 하나씩 없어지고 있다.` },
      good:`자세를 잡다가 풀었다.<br><br>남의 자세를 따라 하는 건 겨룰 때나 하는 일이다.<br>여기서 할 일이 아니다.<br><br>여덟째를 건너뛰고 올라갔다.`, flag:'didntMimic' }
  ] }
);

epicSlot('lake', 'swordsman').push(
{ title:'거울 호수 — 이가 나간 자리',
  text:`물에 칼을 비춰 봤다.<br><br>
    비친 날에 이가 나간 자리가 셋이다. 같다.<br>
    다만 위치가 반대다. 거울이니 당연하다.<br><br>
    당연한데, 셋째 자리만 같은 쪽이다.`,
  opts:[
    { l:'① 다시 비춰 본다.', dc:13, kind:'gaze', p:750,
      good:`각도를 바꿔 세 번 봤다.<br><br>세 번 다 같다. 둘은 뒤집히고 하나는 안 뒤집힌다.<br>셋째 이는 이쪽 날에 난 게 아니다.<br><br>저쪽 날에 난 것이 비친 것이다.`, flag:'mirrorNick',
      bad:`볼수록 자리가 늘어난다.<br><br>넷, 다섯. 이쪽 날을 봐도 셋인데.<br>거뒀다.`, poll:9 },
    { l:'② 날을 물에 담근다.', dc:12, p:700,
      doom:{ title:'담근 날', what:'날이 바뀌었습니다', dc:14, sec:70,
        text:`날을 물에 넣었다. 씻는 셈으로.<br><br>넣은 만큼 저쪽 날이 나온다. 맞닿는다.<br>뺐다. 이가 나간 자리가 셋 다 반대쪽이 됐다.<br><br>이쪽 칼이 아니다. 저쪽 것이 나왔다.<br>바꾸려고 기다린 것이다.`,
        dieText:`거울에 칼을 넣으면 바뀐다.<br><br>바뀐 칼은 바뀐 주인을 부른다.<br>물가에 검사가 하나 서 있다. 남의 칼을 차고.` },
      good:`날 끝만 대 보고 뺐다.<br><br>닿는 순간 저쪽 날도 닿는다. 맞닿는 느낌이 왔다.<br>맞닿는 건 바꾸자는 것이다.<br><br>안 바꿨다. 쓰던 것을 계속 쓴다.`, flag:'keptOwnBlade' }
  ] }
);

epicSlot('road', 'swordsman').push(
{ title:'끊긴 길 — 휘어진 칼',
  text:`걸쳤던 칼이 조금 휘었다.<br><br>
    펴면 된다. 다만 편 칼은 전 같지 않다.<br>
    검사는 그걸 안다.<br><br>
    한 번 휘면 같은 자리가 또 휜다.`,
  opts:[
    { l:'① 편다.', dc:12, kind:'break', p:700,
      good:`무릎에 대고 천천히 폈다.<br><br>펴진다. 손가락으로 훑어 보니 자국이 남았다.<br>다음에 또 휠 자리다.<br><br>알고 쓴다. 검사가 칼을 아는 건 그런 것이다.`, flag:'straightened',
      bad:`펴다가 더 휘었다.<br><br>반대쪽으로. 두 번 휜 칼은 못 쓴다.<br>허리에 찼다. 쓸 일이 없기를 바랐다.`, poll:8 },
    { l:'② 그대로 쓴다.', dc:13, p:700,
      good:`휜 채로 찼다.<br><br>휜 칼은 휜 대로 쓰는 법이 있다. 베는 각도가 달라진다.<br>손에 익히면 된다.<br><br>익히는 데 시간이 걸린다. 시간이 있을지는 모르겠다.`, flag:'usedBent',
      bad:`뽑는데 칼집에 걸린다.<br><br>휘어서 안 나온다. 억지로 빼니 칼집이 찢어졌다.<br>맨 칼을 들고 다녔다.`, poll:8 }
  ] }
);

epicSlot('ruin', 'swordsman').push(
{ title:'폐허 — 물러나지 않은 자리',
  text:`벤 자국이 한 자리에 스물셋이었다.<br><br>
    한 발도 안 물러났다.<br>
    검사가 안 물러나는 건 뒤에 뭔가 있을 때다.<br><br>
    뒤를 보니 벽이다.`,
  opts:[
    { l:'① 벽을 살핀다.', dc:13, kind:'sense', p:750,
      good:`두드려 보니 비어 있다.<br><br>뒤에 공간이 있다. 사람이 들어갈 만한.<br>거기 누가 있었던 것이다.<br><br>그래서 안 물러났다. 물러나면 벽이 열리니까.`, flag:'wallBehind',
      bad:`두드리자 안에서도 두드린다.<br><br>같은 자리를 같은 수만큼.<br>손을 뗐다.`, poll:9 },
    { l:'② 그 자리에서 스물셋 번 휘둘러 본다.', dc:14, p:800,
      doom:{ title:'스물셋 번', what:'팔이 멈추지 않습니다', dc:14, sec:70,
        text:`같은 자리에서 같은 각도로 휘둘렀다.<br><br>열 번쯤에서 팔이 무겁다. 스물 번에서 숨이 찬다.<br>스물셋에서 멈추려는데 안 멈춘다.<br><br>스물넷, 스물다섯. 자국이 늘어난다.<br>앞사람은 스물셋에서 멈췄다. 멈출 수 있어서가 아니었을 것이다.`,
        dieText:`한 자리에서 스물셋 번을 휘두른 사람이 있었다.<br><br>스물넷 번째를 휘두른 사람도 있다.<br>기둥에 자국이 늘고 있다.` },
      good:`셋 번 휘두르고 멈췄다.<br><br>팔이 벌써 무겁다. 스물셋은 사람이 할 수 있는 수가 아니다.<br>할 수 있었다면 다른 이유가 있었을 것이다.<br><br>칼을 거뒀다.`, flag:'stoppedAtThree' }
  ] }
);
;

// ---------- epic-sword-4.js ----------
// ==========================================
// ★ 검사 확장 4/4
// index.html 에서 epic-sword-3.js 다음에 불러온다
// ==========================================

epicSlot('ruin', 'swordsman').push(
{ title:'폐허 — 벽 안쪽',
  text:`비어 있는 벽을 찾았다.<br><br>
    안 물러난 사람이 등지고 섰던 자리.<br>
    안에 사람이 들어갈 만한 공간이 있다.<br><br>
    검사는 지킬 것이 뭐였는지가 궁금하다.`,
  opts:[
    { l:'① 연다.', dc:13, kind:'break', p:750,
      good:`돌을 밀었다. 소리 없이 움직인다.<br><br>안이 비어 있다. 아무것도 없다.<br>다만 바닥에 앉은 자국이 있다. 오래.<br><br>안에 있던 것은 나갔다. 지킨 게 헛되지 않았다.`, flag:'emptyNiche',
      bad:`미는데 안 움직인다.<br><br>안쪽에서 잡고 있다.<br>손을 뗐다.`, poll:8 },
    { l:'② 그대로 둔다.', dc:11, p:650,
      good:`두드려 확인만 하고 물러났다.<br><br>안 물러난 사람이 지킨 것이다. 이쪽이 열 게 아니다.<br>대신 벽 앞에 섰다. 잠깐.<br><br>같은 자리에 서 보는 것으로 충분했다.`, flag:'stoodAtWall',
      bad:`물러나는데 안에서 소리가 난다.<br><br>나가려는 소리가 아니다. 일어나는 소리다.<br>걸음을 빨리했다.`, poll:9 }
  ] }
);

epicSlot('castle', 'swordsman').push(
{ title:'성 — 물러난 쪽이 간 곳',
  text:`벽 앞에서 자국이 사라졌다.<br><br>
    쓰러진 자국은 없다. 물러나다 벽으로 들어갔다.<br>
    검사는 진 사람이 어떻게 되는지 안다.<br><br>
    대개는 남는다. 여기서는 안 남았다.`,
  opts:[
    { l:'① 벽을 두드려 본다.', dc:13, kind:'sense', p:750,
      good:`두드렸다. 소리가 다르다. 얇다.<br><br>안쪽에 공간이 있다. 폐허의 벽과 같은 구조다.<br>같은 사람이 만들었다.<br><br>안 열었다. 벽에 든 사람은 스스로 든 것이다.`, flag:'thinWall',
      bad:`두드리자 안에서 대답이 온다.<br><br>같은 수만큼. 세 번.<br>손을 뗐다.`, poll:9 },
    { l:'② 자국을 되짚어 처음을 찾는다.', dc:12, kind:'gaze', p:700,
      good:`거꾸로 따라가니 홀 가운데다.<br><br>둘이 마주 섰던 자리. 거기서 시작했다.<br>시작한 자리에 표식이 있다. 발로 그린 원.<br><br>겨루기 전에 긋는 선이다. 예를 갖춘 겨룸이었다.`, flag:'duelCircle',
      bad:`되짚는데 자국이 이쪽으로 이어진다.<br><br>지금 선 자리까지.<br>발을 옮겼다.`, poll:8 }
  ] }
);

epicSlot('forest', 'swordsman').push(
{ title:'검은 숲 — 칼을 두고 지난다',
  text:`나무들이 길을 막는다.<br><br>
    두 번 안 벴다. 세 번째도 안 벨 것이다.<br>
    검사가 칼을 안 쓰기로 하면 방법은 하나다.<br><br>
    안 들고 가는 것.`,
  opts:[
    { l:'① 칼을 두고 간다.', dc:13, kind:'bond', p:800,
      good:`나무 아래 세워 두고 걸었다.<br><br>가지가 올라간다. 길이 열린다.<br>칼을 든 사람만 막았던 것이다.<br><br>지나서 돌아보니 칼이 그대로 있다.<br>가져올까 하다가 그냥 뒀다. 나올 때 가져가기로 했다.`, flag:'leftBladeForest',
      bad:`두고 걷는데 손이 허전하다.<br><br>세 걸음에서 돌아가 다시 찼다.<br>가지가 도로 내려온다.`, poll:7 },
    { l:'② 칼집째 밀며 간다.', dc:12, kind:'evade', p:700,
      good:`뽑지 않고 칼집으로 가지를 밀었다.<br><br>밀린다. 안 베고도 지날 수 있다.<br>칼집은 칼이 아니다. 그렇게 치기로 했다.<br><br>나무도 그렇게 친 모양이다.`, flag:'usedSheath',
      bad:`미는데 칼집이 걸린다.<br><br>가지가 감는다. 당겨서 뺐다.<br>칼집에 자국이 남았다.`, poll:8 }
  ] }
);

epicSlot('village', 'swordsman').push(
{ title:'빈 마을 — 지켜 준 것',
  text:`문 앞에 오래 섰다.<br><br>
    아무 일도 안 일어났다.<br>
    검사는 아무 일도 안 일어난 걸 성과로 친다.<br><br>
    남들은 안 쳐 준다. 그래도 그렇게 친다.`,
  opts:[
    { l:'① 표식을 남기고 간다.', dc:12, p:700,
      good:`문틀에 칼로 작게 그었다.<br><br>검사끼리 쓰는 표식이다. 여기는 지켜졌다는 뜻.<br>다음에 오는 사람이 보면 안다.<br><br>안 열어도 되는 문이라는 것도.`, flag:'guardMark' },
    { l:'② 집을 한 바퀴 돈다.', dc:12, kind:'sense', p:700,
      good:`뒤쪽으로 돌아가 봤다.<br><br>창이 하나 있다. 안에서 널빤지를 댔다.<br>나가지 않으려고 막은 것이다. 못 나오게가 아니라.<br><br>대 놓은 쪽이 안이라는 게 중요했다.`, flag:'boardedIn',
      bad:`도는데 뒤쪽이 없다.<br><br>집이 벽에 붙어 있다. 앞에서 볼 때는 안 그랬다.<br>돌아 나왔다.`, poll:9 }
  ] }
);

epicSlot('grave', 'swordsman').push(
{ title:'묘지 — 이름 없는 검사',
  text:`칼이 꽂힌 봉분 앞이다.<br><br>
    비석이 없다. 칼이 비석이다.<br>
    검사의 무덤은 이름을 안 적는다. 칼이 대신한다.<br><br>
    칼을 보면 누구였는지 안다. 아는 사람만.`,
  opts:[
    { l:'① 칼을 읽는다.', dc:13, kind:'gaze', p:800,
      good:`자루 천을 감은 방식을 봤다.<br><br>오른쪽부터 감았다. 왼손잡이가 감는 방식이다.<br>날에 이가 나간 자리는 셋. 같은 각도.<br><br>셋째가 아래에서 위다. 올려 벤 자국.<br>왼손으로 올려 베면 그 각도가 나온다.`, flag:'readGraveBlade',
      bad:`보다 보니 이쪽 칼과 같다.<br><br>감은 방식도 이 나간 자리도.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 옆에 나란히 앉는다.', dc:11, kind:'bond', p:700,
      good:`봉분 옆에 앉았다.<br><br>검사끼리 하는 일이다. 말은 안 한다.<br>한참 앉아 있다 일어섰다.<br><br>일어설 때 칼이 한 번 울렸다. 바람이었을 것이다.`, flag:'satBeside',
      bad:`앉으니 일어서기가 싫어진다.<br><br>편하다. 너무 편하다.<br>억지로 일어섰다.`, poll:8 }
  ] }
);

epicSlot('temple', 'swordsman').push(
{ title:'신전 — 올려 벤 자국',
  text:`셋째 이가 올려 벤 각도였다.<br><br>
    왼손으로 올려 베면 그 각도다.<br>
    이쪽은 오른손잡이다.<br><br>
    검사는 자기 손을 안다.`,
  opts:[
    { l:'① 왼손으로 잡아 본다.', dc:13, p:750,
      doom:{ title:'왼손', what:'손이 익숙해졌습니다', dc:14, sec:70,
        text:`왼손으로 자루를 잡았다.<br><br>어색하다. 어색한데 잡힌다.<br>올려 그어 봤다. 궤적이 매끈하다. 배운 적 없는데.<br><br>바꿔 쥐려는데 오른손이 안 움직인다.<br>왼손이 먼저 움직인다. 이쪽 손이 아닌데.`,
        dieText:`셋째 이는 이쪽 칼에 난 게 아니었다.<br><br>쥐는 손이 바뀌면 칼도 바뀐다.<br>왼손잡이 검사가 하나 늘었다.` },
      good:`왼손으로 잡았다가 놓았다.<br><br>어색한 게 맞다. 어색해야 한다.<br>익숙하면 그게 이상한 것이다.<br><br>오른손으로 고쳐 쥐었다. 이게 이쪽 손이다.`, flag:'rightHand' },
    { l:'② 이가 나간 자리를 갈아 없앤다.', dc:12, kind:'break', p:700,
      good:`숫돌에 대고 갈았다. 셋째 자리만.<br><br>갈린다. 없어졌다. 날이 조금 얕아졌다.<br>얕아진 만큼 이쪽 칼이 됐다.<br><br>남의 자국은 지우는 게 맞다.`, flag:'groundNick',
      bad:`가는데 안 없어진다.<br><br>갈수록 깊어진다. 날 안쪽까지.<br>그만뒀다.`, poll:9 }
  ] }
);

epicSlot('tower', 'swordsman').push(
{ title:'탑 — 없어진 계단들',
  text:`계단이 또 하나 없다.<br><br>
    여덟째였는데 이번엔 열둘째도 없다.<br>
    검사는 늘어나는 것을 센다.<br><br>
    세다 보면 언제 멈출지 알 수 있다.`,
  opts:[
    { l:'① 없어진 수를 센다.', dc:12, kind:'gaze', p:700,
      good:`올라가며 셌다. 없는 칸이 셋이다.<br><br>여덟, 열둘, 열아홉. 간격이 넓어진다.<br>다음은 스물셋쯤일 것이다.<br><br>계단은 스물넷 칸이다. 마지막 하나 전이다.`, flag:'countedGaps',
      bad:`세다 보니 없는 칸이 늘어난다.<br><br>셀 때마다 다르다.<br>그만 세고 올라갔다.`, poll:8 },
    { l:'② 없는 칸에 칼을 걸친다.', dc:13, kind:'break', p:750,
      good:`반쪽 칼을 양쪽 벽에 끼워 발판을 만들었다.<br><br>밟고 올라갔다. 잘 버틴다.<br>내려올 때 뽑으려다 그냥 뒀다.<br><br>다음에 오는 사람이 밟을 것이다.`, flag:'stairBlade',
      bad:`끼우는데 벽이 물렁하다.<br><br>칼이 들어가 버린다. 박힌 게 아니라 먹혔다.<br>반쪽 칼을 잃었다.`, poll:8 }
  ] }
);

epicSlot('lake', 'swordsman').push(
{ title:'거울 호수 — 왼손의 상',
  text:`물에 비친 것이 왼손으로 잡고 있다.<br><br>
    거울이니 당연하다.<br>
    당연한데, 그래서 셋째 이가 안 뒤집혔던 것이다.<br><br>
    저쪽은 처음부터 왼손이었다.`,
  opts:[
    { l:'① 확인한다.', dc:13, kind:'gaze', p:750,
      good:`손을 바꿔 잡아 봤다. 왼손으로.<br><br>비친 쪽이 오른손이 된다. 정상이다.<br>다시 오른손으로 잡으니 저쪽이 왼손이다. 정상이다.<br><br>셋째 이만 안 뒤집힌다. 손과 상관없이.<br>저 자국은 거울 저쪽에서 왔다.`, flag:'confirmedNick',
      bad:`바꿔 잡는데 저쪽이 안 바꾼다.<br><br>계속 왼손이다.<br>거뒀다.`, poll:9 },
    { l:'② 저쪽에게 칼을 겨눈다.', dc:14, p:800,
      doom:{ title:'겨눈 칼', what:'먼저 겨눈 쪽이 됐습니다', dc:15, sec:70,
        text:`겨눴다. 저쪽도 겨눈다. 같은 순간에.<br><br>겨룰 때 먼저 겨눈 쪽이 움직여야 한다. 규칙이다.<br>움직이면 지는 것도 안다.<br><br>둘 다 안 움직인다. 팔이 저린다.<br>저쪽은 안 저린다. 거울에는 피가 안 통한다.`,
        dieText:`겨눈 쪽이 먼저 움직여야 한다.<br><br>안 움직이면 계속 겨누고 있어야 한다.<br>물가에 검사가 서 있다. 칼을 든 채로.` },
      good:`겨누려다 칼을 내렸다.<br><br>겨누면 겨룬다. 겨루면 규칙이 생긴다.<br>규칙이 생기면 지친 쪽이 진다.<br><br>등을 돌렸다. 세 번째다. 이제는 망설이지도 않았다.`, flag:'loweredBlade' }
  ] }
);

epicSlot('market', 'swordsman').push(
{ title:'장터 — 칼을 맡긴다',
  text:`좌판 주인이 손을 내민다.<br><br>
    칼을 달라는 뜻이다. 봐 주겠다는 것인지, 가져가겠다는 것인지.<br>
    검사는 남에게 칼을 안 준다.<br><br>
    다만 갈아 주겠다는 손짓이기도 하다.`,
  opts:[
    { l:'① 건넨다.', dc:13, kind:'bond', p:750,
      good:`자루 쪽을 돌려 건넸다.<br><br>날을 상대 쪽으로 주지 않는다. 그게 예다.<br>주인이 한참 보더니 숫돌에 댄다.<br><br>갈아서 돌려줬다. 값은 안 받았다.<br>이가 나간 자리는 그대로였다. 못 가는 것이 아니라 안 간 것이다.`, flag:'stallSharpen',
      bad:`건네는데 주인이 날 쪽을 잡는다.<br><br>손이 안 베인다.<br>급히 거뒀다.`, poll:9 },
    { l:'② 안 준다.', dc:11, p:650,
      good:`고개를 저었다.<br><br>주인이 손을 거둔다. 아무 일도 안 났다.<br>검사가 칼을 안 주는 건 무례가 아니다.<br><br>주인도 아는 모양이었다.`, flag:'keptHold',
      bad:`고개를 젓는데 손이 안 내려간다.<br><br>계속 내밀고 있다.<br>돌아서 갔다.`, poll:7 }
  ] }
);

epicSlot('road', 'swordsman').push(
{ title:'끊긴 길 — 건너지 않는다',
  text:`안개가 평평하다.<br><br>
    건널 방법은 있다. 걸치거나 던지거나.<br>
    검사는 건널 이유가 있는지를 먼저 본다.<br><br>
    지킬 것이 저쪽에 있는가.`,
  opts:[
    { l:'① 안 건넌다.', dc:12, p:700,
      good:`한참 보다가 돌아섰다.<br><br>저쪽에 지킬 것이 없다. 건널 이유가 없다.<br>검사는 이유 없이 안 움직인다.<br><br>돌아서는 게 물러나는 건 아니다. 그건 다르다.`, flag:'noReason' },
    { l:'② 표식을 남긴다.', dc:12, kind:'bond', p:700,
      good:`끊긴 자리 앞 돌에 칼로 그었다.<br><br>검사 표식이다. 여기부터는 지킬 수 없다는 뜻.<br>다음에 오는 사람이 보면 안다.<br><br>그어 놓고 나니 마음이 가벼웠다.`, flag:'limitMark',
      bad:`긋는데 돌이 안 파인다.<br><br>칼이 미끄러진다. 세 번 하고 그만뒀다.<br>손으로 표시만 했다.`, poll:7 }
  ] }
);

epicSlot('gate', 'swordsman').push(
{ title:'성문 — 나가는 자',
  text:`석상이 말한다.<br><br>
    <span style="color:#d4af37;">"들어온 자는 여럿, 나간 자는 하나."</span><br><br>
    검사는 나간 하나가 어떻게 나갔는지보다<br>
    남은 스물셋이 왜 안 나갔는지가 궁금하다.`,
  opts:[
    { l:'① 남은 쪽을 묻는다.', dc:13, kind:'bond', p:800,
      good:`왜 안 나갔냐고 물었다.<br><br>석상이 오래 생각한다.<br><span style="color:#d4af37;">"지킬 것이 안에 있었소."</span><br><br>나갈 수 있었는데 안 나갔다는 뜻이다.<br>검사는 그 말을 이해한다. 너무 잘 이해한다.`, flag:'whyStayed',
      bad:`묻자 석상이 이쪽을 본다.<br><br>대답 대신 되묻는 것 같다.<br>대답할 말이 없었다.`, poll:9 },
    { l:'② 이쪽이 남겠다고 한다.', dc:14, p:800,
      doom:{ title:'남겠다는 말', what:'받아들여졌습니다', dc:15, sec:70,
        text:`남겠다고 했다. 지킬 것이 있으면 남는 게 검사다.<br><br>석상이 고개를 숙인다. 깊게.<br>받침에 이름이 하나 새겨진다. 이쪽 것이다.<br><br>새겨지는 동안 발이 굳는다.<br>남는다는 말은 여기서 계약이다. 무를 수가 없다.`,
        dieText:`검사는 지킬 것이 있으면 남는다.<br><br>여기서는 남겠다는 말 자체가 지킬 것이 된다.<br>성문에 서 있는 것이 하나 늘었다.` },
      good:`말하려다 입을 다물었다.<br><br>여기서 남겠다고 하면 남게 된다. 말이 그대로 된다.<br>지킬 것이 없는데 남는 건 지키는 게 아니다.<br><br>고개만 숙였다. 석상도 숙였다.`, flag:'didntPledge' }
  ] }
);
;

