epicSlot('gate', 'warden').push(
{ title:'성문 — 둘이 선다',
  text:`문턱 양쪽에 앉은 자국이 있었다.<br><br>
    둘이 섰던 자리다. 파수꾼은 둘씩 선다.<br>
    하나가 졸면 하나가 깨운다.<br><br>
    혼자 서면 졸아도 아무도 모른다.`,
  opts:[
    { l:'① 동료와 양쪽에 선다.', co:'sync',
      coOpt:{ ask:'양쪽에 섭시다. 제가 안쪽을 보겠습니다.', sec:60, p:1000,
        text:`혼자 서면 졸아도 모른다.`,
        doneText:`양쪽에 섰다. 이쪽이 안, 저쪽이 밖.<br><br>한참 있었다. 아무것도 안 지났다.<br>중간에 저쪽이 헛기침을 했다. 이쪽이 졸고 있었다.<br><br>깼다. 깨워 준 것이다.<br>둘이 서는 이유가 그것이다.`,
        failText:`혼자 섰다. 양쪽을 번갈아 봤다.<br><br>보는 사이에 반대쪽이 빈다.<br>빈 사이에 뭐가 지났는지는 모른다.` },
      good:`둘이 섰다.`, bad:`혼자 섰다.`, flag:'pairedPost' },
    { l:'② 눈금 순서를 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`눈금 여섯을 시각 순으로 짚었다.<br><br>순서가 맞자 교대 차례가 보인다.<br>여섯 번 돌고 한 번 쉰다. 그게 한 조다.<br><br>지워진 눈금은 쉬는 차례 바로 앞이다.`, flag:'shiftOrder',
      bad:`순서가 엉켰다.<br><br>어느 게 먼저인지 모르겠다.<br>해를 봐도 안 맞는다.` }
  ] }
);

epicSlot('castle', 'warden').push(
{ title:'성 — 반대로 돈다',
  text:`복도가 길다.<br><br>
    혼자 돌면 한 바퀴에 오래 걸린다.<br>
    둘이 반대로 돌면 절반이고, 중간에 만난다.<br><br>
    만나는 게 중요하다. 만나면 둘 다 무사한 것이다.`,
  opts:[
    { l:'① 반대 방향으로 돈다.', co:'sync',
      coOpt:{ ask:'반대로 돕시다. 중간에서 만나면 됩니다.', sec:60, p:1000,
        text:`만나면 둘 다 무사한 것이다.`,
        doneText:`갈라져서 돌았다.<br><br>중간에서 만났다. 서로 고개를 끄덕였다.<br>말은 안 했다. 만난 것으로 충분하다.<br><br>두 바퀴째도 만났다. 세 바퀴째는 안 돌았다.<br>두 번 만났으면 됐다.`,
        failText:`혼자 한 바퀴 돌았다.<br><br>끊긴 자리에서 돌아섰다. 반 바퀴다.<br>나머지 반은 못 봤다.` },
      good:`두 번 만났다.`, bad:`반 바퀴 돌았다.`, flag:'counterRound' },
    { l:'② 등불 자리를 순서대로 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`그을음 진한 순서로 일곱을 짚었다.<br><br>순서가 나온다. 도는 방향이 보인다.<br>시계 반대 방향이다.<br><br>그을음 없는 자리는 순서에서 빠져 있다. 건너뛰었다.`, flag:'lampRoute',
      bad:`그을음이 다 비슷하다.<br><br>순서를 못 잡겠다.<br>아무 데나 짚었다.` }
  ] }
);

epicSlot('tower', 'warden').push(
{ title:'탑 — 둘이 본다',
  text:`망루가 넓다.<br><br>
    혼자 보면 반만 본다. 둘이면 다 본다.<br>
    파수꾼은 시야를 나눠 쓴다.<br><br>
    나눠 보면 놓치는 게 줄어든다.`,
  opts:[
    { l:'① 동료와 반대쪽을 본다.', co:'sync',
      coOpt:{ ask:'반대쪽을 봐 주십시오. 제가 숲 쪽을 보겠습니다.', sec:60, p:1000,
        text:`혼자 보면 반만 본다.`,
        doneText:`등을 맞대고 반대쪽을 봤다.<br><br>저쪽이 낮게 말했다. 마을 쪽에서 문 하나가 열렸다고.<br>이쪽에서는 숲 쪽 빈터가 보였다. 가운데 뭔가 서 있다.<br><br>둘이 동시에 본 것이다. 동시에 본 것은 기록이 된다.<br>파수꾼은 그렇게 배운다.`,
        failText:`혼자 한쪽만 봤다.<br><br>고개를 돌리면 아까 본 쪽이 안 보인다.<br>돌리는 사이에 뭔가 바뀌었을 것이다.` },
      good:`둘이 봤다.`, bad:`반만 봤다.`, flag:'sharedWatch' },
    { l:'② 난간 자국을 순서대로 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`패인 깊이 순서로 짚었다. 여섯 자리.<br><br>제일 깊은 자리가 숲 쪽이다.<br>거기를 제일 오래 봤다.<br><br>나머지는 형식이었다. 숲만 봤다.`, flag:'deepestView',
      bad:`깊이가 비슷하다.<br><br>어디를 오래 봤는지 모르겠다.<br>그냥 한 바퀴 둘러봤다.` }
  ] }
);

epicSlot('village', 'warden').push(
{ title:'빈 마을 — 교대로 지킨다',
  text:`닫힌 집 앞이다.<br><br>
    혼자 서면 오래 못 간다.<br>
    교대할 사람이 있으면 다르다.<br><br>
    파수꾼이 제일 바라는 게 교대다.`,
  opts:[
    { l:'① 동료와 교대한다.', co:'standin',
      coOpt:{ ask:'교대합시다. 제가 먼저 서겠습니다.', sec:60, p:1000,
        text:`교대할 사람이 있어야 오래 선다.`,
        doneText:`먼저 섰다. 한참 뒤에 저쪽이 왔다.<br><br>자리를 바꿨다. 말은 안 했다.<br>뒤에 앉아 다리를 폈다. 오랜만이다.<br><br>일어나 보니 저쪽이 같은 자세로 서 있었다.<br>가르친 적 없는데 똑같았다. 서는 자세는 하나뿐인 모양이다.`,
        failText:`혼자 섰다. 끝까지.<br><br>발이 벌어졌다. 힘이 빠진 것이다.<br>그래도 안 앉았다.` },
      good:`교대했다.`, bad:`혼자 섰다.`, flag:'villageRelief' },
    { l:'② 집들이 향한 방향을 잰다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`막대와 돌로 각도를 잰 셈을 맞췄다.<br><br>스물둘 집이 한 점을 향한다.<br>그 점이 숲과 묘지 사이다.<br><br>닫힌 집 하나만 등지고 있다. 정확히 반대다.`, flag:'houseAngle',
      bad:`잴수록 각이 어긋난다.<br><br>집이 움직이는 건 아닐 텐데.<br>그만뒀다.` }
  ] }
);

epicSlot('grave', 'warden').push(
{ title:'묘지 — 둘이 선다',
  text:`입구 자국이 하나뿐이다.<br><br>
    혼자 섰다는 뜻이다.<br>
    파수꾼은 묘지를 혼자 안 지킨다. 그게 규정이다.<br><br>
    혼자 섰다면 규정을 못 지킨 것이다.`,
  opts:[
    { l:'① 동료와 나란히 선다.', co:'witness',
      coOpt:{ ask:'혼자 서는 자리가 아닙니다. 같이 서 주십시오.', sec:60, p:1000,
        text:`묘지는 혼자 안 지킨다.`,
        doneText:`둘이 나란히 섰다. 안쪽을 보고.<br><br>비석 스물셋이 보인다. 둘 다 세었다.<br>세어 보니 둘 다 스물셋이라 했다.<br><br>혼자 세면 틀린다. 둘이 세면 맞는다.<br>규정이 그래서 있는 것이다.`,
        failText:`혼자 섰다. 세어 보니 스물셋이다.<br><br>다시 세니 스물넷이다. 또 세니 스물셋.<br>혼자 세면 이렇게 된다.` },
      good:`둘이 세었다.`, bad:`혼자 세었다.`, flag:'twoCounted' }
  ] }
);

epicSlot('forest', 'warden').push(
{ title:'검은 숲 — 경계를 다시 긋는다',
  text:`표가 지워진 데가 있다.<br><br>
    나무가 자라면 표가 묻힌다.<br>
    파수꾼은 경계를 다시 긋는다. 그게 일 중 하나다.<br><br>
    혼자 하면 놓친다. 둘이면 안 놓친다.`,
  opts:[
    { l:'① 동료와 나눠 긋는다.', co:'handoff',
      coOpt:{ ask:'경계를 다시 긋읍시다. 반대쪽을 맡아 주십시오.', sec:60, p:950,
        text:`혼자 하면 놓친다.`,
        doneText:`갈라져서 그었다. 반대편에서 만났다.<br><br>합쳐 보니 원이 닫힌다. 빠진 데가 없다.<br>저쪽이 그은 쪽에 묻힌 표가 셋 있었다고 한다.<br><br>혼자 했으면 못 찾았을 것이다.<br>경계는 한 군데만 끊겨도 경계가 아니다.`,
        failText:`혼자 그었다. 절반쯤에서 어두워졌다.<br><br>나머지는 못 했다. 끊긴 경계는 경계가 아니다.` },
      good:`원이 닫혔다.`, bad:`끊긴 채로 뒀다.`, flag:'reMarked' },
    { l:'② 표의 높이를 맞춘다.', mini:'scale', miniOpt:{ p:750, target:18, pool:[2,3,5,6,8,10] },
      good:`먼저 그은 표들의 높이를 재 맞췄다.<br><br>전부 같은 높이다. 어른 어깨쯤.<br>맞춰 그으니 이어진다.<br><br>높이가 같아야 멀리서 보인다. 그래서 맞추는 것이다.`, flag:'evenHeight',
      bad:`높이가 제각각이다.<br><br>맞춰도 어긋난다. 나무가 기울어서 그렇다.<br>그냥 그었다.` }
  ] }
);

epicSlot('temple', 'warden').push(
{ title:'신전 — 양쪽에 선다',
  text:`문 양쪽 자국이다.<br><br>
    한쪽은 깊고 한쪽은 얕았다.<br>
    둘이 서면 양쪽이 고르게 닳아야 한다.<br><br>
    한쪽만 깊다는 건 한쪽이 오래 혼자 섰다는 뜻이다.`,
  opts:[
    { l:'① 동료와 양쪽에 선다.', co:'sync',
      coOpt:{ ask:'양쪽에 섭시다. 얕은 쪽을 맡아 주십시오.', sec:60, p:1000,
        text:`양쪽이 고르게 닳아야 한다.`,
        doneText:`양쪽에 섰다. 저쪽이 얕은 쪽.<br><br>한참 있었다. 촛불이 스물셋 개 다 같은 밝기다.<br>저쪽이 말했다. 여기서는 제단이 안 보인다고.<br><br>자리를 바꿔 봤다. 이쪽에서도 안 보인다.<br>보는 자리와 안 보는 자리를 나눠 놓은 것이다.`,
        failText:`혼자 깊은 쪽에 섰다.<br><br>얕은 쪽이 계속 비어 있다.<br>비어 있는 게 신경 쓰였다.` },
      good:`양쪽에 섰다.`, bad:`한쪽만 섰다.`, flag:'bothSidesPost' },
    { l:'② 촛불 밝기 순서를 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`밝은 순서로 여섯을 짚었다.<br><br>제단에서 먼 쪽이 밝다. 가까운 쪽이 어둡다.<br>거꾸로다.<br><br>어두운 쪽을 보라고 만든 배치다.`, flag:'reverseLight',
      bad:`밝기가 계속 바뀐다.<br><br>짚는 순간 어두워지고 다른 게 밝아진다.<br>그만뒀다.` }
  ] }
);

epicSlot('ruin', 'warden').push(
{ title:'폐허 — 초소를 고친다',
  text:`초소 바깥이 무너졌다.<br><br>
    안은 멀쩡하다. 바깥만 손보면 쓸 수 있다.<br>
    파수꾼은 초소를 손볼 줄 안다.<br><br>
    다만 혼자서는 돌을 못 든다.`,
  opts:[
    { l:'① 동료와 고친다.', co:'handoff',
      coOpt:{ ask:'초소를 손봅시다. 돌을 들어 주십시오.', sec:60, p:950,
        text:`혼자서는 돌을 못 든다.`,
        doneText:`둘이 돌을 쌓았다. 반나절이 걸렸다.<br><br>벽이 섰다. 지붕은 없지만 바람은 막힌다.<br>안에 들어가 앉아 봤다. 둘이 앉으니 좁다.<br><br>좁은 게 나았다. 원래 둘이 쓰는 자리다.`,
        failText:`혼자 돌을 밀었다. 셋 쌓고 무너졌다.<br><br>그만뒀다. 안쪽만 쓸 수 있다.` },
      good:`고쳤다.`, bad:`무너뜨렸다.`, flag:'rebuiltPost' },
    { l:'② 날짜 금을 세어 본다.', mini:'beat', miniOpt:{ p:750, total:12, gap:680 },
      good:`다섯씩 묶인 것을 박자로 세었다. 열두 묶음.<br><br>예순 날이다. 마지막 묶음은 셋.<br>예순셋 날 동안 섰다.<br><br>두 달이 넘는다. 교대 없이.`, flag:'daysCounted',
      bad:`세다가 놓쳤다.<br><br>묶음이 겹쳐 있다. 몇 개인지 모르겠다.<br>그만 셌다.` }
  ] }
);

epicSlot('lake', 'warden').push(
{ title:'거울 호수 — 둘이 본다',
  text:`비친 초소에 불이 켜져 있다.<br><br>
    혼자 보면 부르게 된다. 파수꾼의 버릇이다.<br>
    교대를 기다리는 사람을 보면 그렇게 된다.<br><br>
    둘이 보면 하나가 말린다.`,
  opts:[
    { l:'① 동료와 함께 본다.', co:'witness',
      coOpt:{ ask:'저기 초소가 비칩니다. 같이 봐 주십시오.', sec:60, p:1000,
        text:`혼자 보면 부르게 된다.`,
        doneText:`둘이 들여다봤다.<br><br>저쪽도 보인다고 한다. 앉아 있는 등까지.<br>부르려는데 저쪽이 팔을 잡았다.<br><br>교대라는 말은 자리를 바꾸는 말이라고, 저쪽이 말했다.<br>파수꾼이 아닌데 알고 있었다. 어디서 들었는지는 안 물었다.`,
        failText:`혼자 봤다. 오래.<br><br>입이 열리려는 걸 참았다.<br>참는 데 힘이 들었다.` },
      good:`안 불렀다.`, bad:`참았다.`, flag:'stoppedFromCalling' }
  ] }
);

epicSlot('road', 'warden').push(
{ title:'끊긴 길 — 경계석을 세운다',
  text:`경계석이 하나뿐이다.<br><br>
    한쪽에만 있다. 반대쪽에는 없다.<br>
    파수꾼은 양쪽에 세운다. 혼자 세우면 한쪽만 된다.<br><br>
    반대쪽은 건너가야 세운다.`,
  opts:[
    { l:'① 동료가 건너가 세운다.', co:'standin',
      coOpt:{ ask:'반대쪽에도 세워야 합니다. 건너가 주시겠습니까.', sec:60, p:1000,
        text:`혼자 세우면 한쪽만 된다.`,
        doneText:`저쪽이 걸쳐 둔 것을 밟고 건넜다.<br><br>돌을 하나 세웠다. 이쪽과 마주 보게.<br>양쪽에 서니 경계가 된다.<br><br>손을 얹고 돌아섰다. 저쪽도 얹었다.<br>동시에 했다. 약속한 적 없는데.`,
        failText:`혼자 한쪽만 세웠다.<br><br>마주 볼 돌이 없다. 경계가 안 된다.<br>한쪽 표시로만 뒀다.` },
      good:`양쪽에 세웠다.`, bad:`한쪽만 세웠다.`, flag:'pairedStones' },
    { l:'② 돌을 겨눠 던진다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`작은 돌을 던져 반대편에 쌓았다. 두 번 만에.<br><br>돌무더기가 됐다. 경계석 대신은 된다.<br>멀리서 보면 표시가 된다.<br><br>파수꾼은 있는 것으로 한다.`, flag:'thrownCairn',
      bad:`세 번 다 안개로 떨어졌다.<br><br>소리가 안 났다.<br>표시를 못 남겼다.` }
  ] }
);

epicSlot('market', 'warden').push(
{ title:'장터 — 둘러본다',
  text:`좌판이 많다.<br><br>
    파수꾼은 사람 많은 데서 눈이 바쁘다.<br>
    혼자 보면 놓친다.<br><br>
    여기는 사람이 없는데도 눈이 바쁘다.`,
  opts:[
    { l:'① 동료와 나눠 본다.', co:'sync',
      coOpt:{ ask:'나눠서 봅시다. 제가 안쪽 줄을 보겠습니다.', sec:60, p:950,
        text:`혼자 보면 놓친다.`,
        doneText:`갈라져서 훑었다.<br><br>합쳐 보니 좌판이 스물셋이다. 둘 다 같은 수를 셌다.<br>다만 저쪽이 본 줄에 빈 좌판이 하나 있었다고 한다.<br><br>물건도 주인도 없는 좌판.<br>이쪽 줄에는 없었다.`,
        failText:`혼자 훑었다. 세어 보니 스물넷이다.<br><br>다시 세니 스물셋.<br>혼자 세면 이렇게 된다.` },
      good:`같이 세었다.`, bad:`혼자 세었다.`, flag:'stallCount' },
    { l:'② 좌판 사이 간격을 잰다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,10] },
      good:`간격이 전부 같다.<br><br>손으로 놓은 것치고는 정확하다.<br>재어서 놓은 것이다.<br><br>마을 집 간격과도 같다. 같은 도면이다.`, flag:'sameSpacing',
      bad:`재는데 간격이 달라진다.<br><br>잴 때마다. 좌판이 움직이는 건 아닐 텐데.<br>그만뒀다.` }
  ] }
);
;
